window.DQ=window.DQ||{};DQ["berachot"]={"a":[["עַל אֵיזֶה מַאֲכָל מְבָרְכִים \"הַמּוֹצִיא לֶחֶם מִן הָאָרֶץ\"?",["כּוֹס חָלָב","פְּרוּסַת לֶחֶם","תַּפּוּחַ אָדֹם"],1,"עַל לֶחֶם מְבָרְכִים \"הַמּוֹצִיא\". עַל הֶחָלָב – \"שֶׁהַכֹּל\", וְעַל הַתַּפּוּחַ – \"בּוֹרֵא פְּרִי הָעֵץ\".","פֶּרֶק א׳, הֲלָכָה ד׳","תּוֹדָה לַה׳ וְיָדַיִם טְהוֹרוֹת"],["עַל אֵיזֶה מַאֲכָל מְבָרְכִים \"שֶׁהַכֹּל נִהְיָה בִּדְבָרוֹ\"?",["אֶשְׁכּוֹל עֲנָבִים","פְּרוּסַת עוּגָה","חֲתִיכַת בָּשָׂר"],2,"בָּשָׂר וְחָלָב אֵינָם גְּדֵלִים מִן הָאָרֶץ, וְלָכֵן מְבָרְכִים עֲלֵיהֶם \"שֶׁהַכֹּל\". עַל עֲנָבִים – \"הָעֵץ\", וְעַל עוּגָה – \"מְזוֹנוֹת\".","פֶּרֶק א׳, הֲלָכָה ד׳","תּוֹדָה לַה׳ וְיָדַיִם טְהוֹרוֹת"],["אֵיךְ אוֹמְרִים בְּרָכָה עַל תַּפּוּחַ?",["בַּפֶּה, בְּקוֹל שֶׁשּׁוֹמְעִים","רַק בַּמַּחֲשָׁבָה, בַּלֵּב","תּוֹךְ כְּדֵי סִדּוּר הַצַּלָּחוֹת"],0,"אֶת הַבְּרָכָה מוֹצִיאִים בַּשְּׂפָתַיִם, וְטוֹב בְּקוֹל. מַחֲשָׁבָה בִּלְבַד לֹא מַסְפִּיקָה, וּבִזְמַן הַבְּרָכָה לֹא עוֹשִׂים שׁוּם עֲבוֹדָה.","פֶּרֶק א׳, הֲלָכָה ז׳","תּוֹדָה לַה׳ וְיָדַיִם טְהוֹרוֹת"],["אַבָּא מְבָרֵךְ \"הַמּוֹצִיא\". מָתַי עוֹנִים \"אָמֵן\"?",["בְּאֶמְצַע הַבְּרָכָה","אַחֲרֵי שֶׁכֻּלָּם כְּבָר אוֹכְלִים","מִיָּד בְּסוֹף הַבְּרָכָה"],2,"עוֹנִים \"אָמֵן\" מִיָּד כְּשֶׁהַבְּרָכָה נִגְמֶרֶת. לִפְנֵי הַסּוֹף זוֹ \"אָמֵן חֲטוּפָה\", וּמְאֻחָר מִדַּי זוֹ \"אָמֵן יְתוֹמָה\".","פֶּרֶק א׳, הֲלָכָה ט׳","תּוֹדָה לַה׳ וְיָדַיִם טְהוֹרוֹת"],["בְּמָה נוֹטְלִים יָדַיִם לִפְנֵי אֲכִילַת לֶחֶם?",["בְּנַטְלָה","בְּשַׂקִּית נַיְלוֹן","בְּבֶרֶז הַכִּיּוֹר"],0,"צָרִיךְ לִטֹּל מִכְּלִי. שַׂקִּית אֵינָהּ כְּלִי, וְגַם צִנּוֹר הַבֶּרֶז אֵינוֹ כְּלִי – וְלָכֵן נוֹטְלִים בְּנַטְלָה.","פֶּרֶק ב׳, הֲלָכוֹת ח׳–ט׳","תּוֹדָה לַה׳ וְיָדַיִם טְהוֹרוֹת"],["בְּאֵילוּ מַיִם מֻתָּר לִטֹּל יָדַיִם?",["מִיץ תַּפּוּזִים","מַיִם צְלוּלִים","מַיִם מִשְּׁטִיפַת כֵּלִים"],1,"נוֹטְלִים בְּמַיִם שְׁקוּפִים כְּמַרְאֵיהֶם הַטִּבְעִי. מִיץ – מַרְאֵהוּ שֻׁנָּה, וּבְמַיִם שֶׁשָּׁטְפוּ בָּהֶם כֵּלִים כְּבָר עָשׂוּ עֲבוֹדָה.","פֶּרֶק ב׳, הֲלָכָה ז׳","תּוֹדָה לַה׳ וְיָדַיִם טְהוֹרוֹת"],["אֵיזוֹ יָד נוֹטְלִים רִאשׁוֹנָה לִפְנֵי הַסְּעוּדָה?",["אֶת יַד יָמִין","אֶת שְׁתֵּיהֶן יַחַד","אֶת יַד שְׂמֹאל"],0,"מַקְדִּימִים אֶת יַד יָמִין – כְּנֶגֶד מִדַּת הַחֶסֶד – וְנוֹטְלִים אוֹתָהּ פַּעֲמַיִם בָּרֶצֶף. אַחַר כָּךְ נוֹטְלִים אֶת יַד שְׂמֹאל.","פֶּרֶק ב׳, הֲלָכָה י״א","תּוֹדָה לַה׳ וְיָדַיִם טְהוֹרוֹת"],["מָתַי מְבָרְכִים \"עַל נְטִילַת יָדַיִם\" לִפְנֵי הַסְּעוּדָה?",["אַחֲרֵי הַנִּגּוּב בַּמַּגֶּבֶת","לִפְנֵי שֶׁשּׁוֹפְכִים מַיִם","כְּשֶׁהַיָּדַיִם עוֹד רְטֻבּוֹת"],2,"מְבָרְכִים אַחֲרֵי הַנְּטִילָה וְלִפְנֵי הַנִּגּוּב. הַנִּגּוּב הוּא חֵלֶק מֵהַמִּצְוָה, וְלָכֵן הַבְּרָכָה עֲדַיִן נֶאֱמֶרֶת לִפְנֵי שֶׁהַמִּצְוָה נִגְמְרָה.","פֶּרֶק ב׳, הֲלָכָה י״ג","תּוֹדָה לַה׳ וְיָדַיִם טְהוֹרוֹת"],["מִי בֶּאֱמֶת \"מוֹצִיא לֶחֶם מִן הָאָרֶץ\"?",["הָאוֹפֶה בַּמַּאֲפִיָּה","הַחַקְלַאי בַּשָּׂדֶה","ה׳, שֶׁנּוֹתֵן לָהֶם אֶת הַכֹּל"],2,"הַחַקְלַאי וְהָאוֹפֶה עָמְלוּ הַרְבֵּה, אֲבָל הָאֲדָמָה, הַדָּגָן וְהַחָכְמָה לֶאֱפוֹת – כֻּלָּם מֵה׳. לָכֵן אוֹמְרִים שֶׁהוּא \"הַמּוֹצִיא לֶחֶם מִן הָאָרֶץ\".","פֶּרֶק ג׳, הֲלָכָה א׳","הַמּוֹצִיא לֶחֶם מִן הָאָרֶץ"],["אֵיךְ טוֹב לֶאֱחֹז אֶת הַלֶּחֶם בִּשְׁעַת \"הַמּוֹצִיא\"?",["בִּשְׁתֵּי הַיָּדַיִם","בְּיַד אַחַת","מֻנָּח עַל הַצַּלַּחַת"],0,"מִפְּנֵי חֲשִׁיבוּת הַלֶּחֶם אוֹחֲזִים אוֹתוֹ בְּעֶשֶׂר אֶצְבָּעוֹת – כְּנֶגֶד עֶשֶׂר הַמִּצְוֹת שֶׁבַּהֲכָנָתוֹ.","פֶּרֶק ג׳, הֲלָכָה ב׳","הַמּוֹצִיא לֶחֶם מִן הָאָרֶץ"],["יֵשׁ לַחְמָנִיַּת חִטָּה וְלַחְמָנִיַּת שְׂעוֹרָה. עַל אֵיזוֹ מְבָרְכִים?",["עַל שְׁתֵּיהֶן יַחַד, אַחַת בְּכָל יָד","עַל לַחְמָנִיַּת הַחִטָּה","עַל לַחְמָנִיַּת הַשְּׂעוֹרָה"],1,"לֶחֶם חִטָּה חָשׁוּב יוֹתֵר: הַחִטָּה מֻקְדֶּמֶת בְּשִׁבְעַת הַמִּינִים, וְטַעֲמָהּ מְשֻׁבָּח יוֹתֵר.","פֶּרֶק ג׳, הֲלָכָה ב׳","הַמּוֹצִיא לֶחֶם מִן הָאָרֶץ"],["יֵשׁ לֶחֶם גָּדוֹל שֶׁכְּבָר חָתְכוּ מִמֶּנּוּ, וְלַחְמָנִיָּה קְטַנָּה שְׁלֵמָה. עַל מָה מְבָרְכִים?",["עַל הַלֶּחֶם הַגָּדוֹל הֶחָתוּךְ","עַל פְּרוּסָה אַחַת","עַל הַלַּחְמָנִיָּה הַשְּׁלֵמָה"],2,"מַעֲלַת הַשְּׁלֵמוּת חֲשׁוּבָה מִמַּעֲלַת הַגֹּדֶל – וְלָכֵן מְבָרְכִים עַל הַלַּחְמָנִיָּה הַשְּׁלֵמָה.","פֶּרֶק ג׳, הֲלָכָה ב׳","הַמּוֹצִיא לֶחֶם מִן הָאָרֶץ"],["דָּנִי בֵּרֵךְ \"הַמּוֹצִיא\". מָה הוּא עוֹשֶׂה מִיָּד אַחֲרֵי הַבְּרָכָה?",["טוֹעֵם מִן הַלֶּחֶם","מְסַפֵּר לְאַבָּא מָה הָיָה בַּכִּתָּה","קָם לְשַׂחֵק בַּכַּדּוּר"],0,"מִיָּד אַחֲרֵי הַבְּרָכָה טוֹעֲמִים. מִי שֶׁמְּדַבֵּר לִפְנֵי שֶׁטָּעַם מַפְסִיק בֵּין הַבְּרָכָה לָאֲכִילָה, וְצָרִיךְ לְבָרֵךְ שׁוּב.","פֶּרֶק ג׳, הֲלָכָה ג׳","הַמּוֹצִיא לֶחֶם מִן הָאָרֶץ"],["מָה מַנִּיחִים עַל שֻׁלְחַן הַסְּעוּדָה, כְּמוֹ שֶׁהָיוּ שָׂמִים עַל הַקָּרְבָּנוֹת?",["מֶלַח","קֻבִּיּוֹת סֻכָּר","אֲגַרְטַל פְּרָחִים"],0,"הַתּוֹרָה צִוְּתָה: \"עַל כָּל קָרְבָּנְךָ תַּקְרִיב מֶלַח\". הַשֻּׁלְחָן שֶׁלָּנוּ דּוֹמֶה לַמִּזְבֵּחַ, וְלָכֵן מַנִּיחִים עָלָיו מֶלַח.","פֶּרֶק ג׳, הֲלָכָה ה׳","הַמּוֹצִיא לֶחֶם מִן הָאָרֶץ"],["בְּאֶמְצַע הַסְּעוּדָה – עַל אֵיזֶה מַאֲכָל צָרִיךְ לְבָרֵךְ בְּרָכָה מִשֶּׁלּוֹ?",["אֹרֶז עִם עוֹף","פְּלַח אֲבַטִּיחַ","סָלָט יְרָקוֹת"],1,"אֹרֶז, עוֹף וְסָלָט אוֹכְלִים כְּדֵי לִשְׂבֹּעַ, וְ\"הַמּוֹצִיא\" פּוֹטֵר אוֹתָם. אֲבַטִּיחַ הוּא קִנּוּחַ, וּמְבָרְכִים עָלָיו \"בּוֹרֵא פְּרִי הָאֲדָמָה\".","פֶּרֶק ג׳, הֲלָכָה ו׳","הַמּוֹצִיא לֶחֶם מִן הָאָרֶץ"],["אֵיזֶה מַשְׁקֶה בַּסְּעוּדָה לֹא נִפְטָר בְּ\"הַמּוֹצִיא\"?",["כּוֹס מַיִם","כּוֹס מִיץ","כּוֹס יַיִן"],2,"מַיִם וּמִיץ שֶׁשּׁוֹתִים בַּסְּעוּדָה נִפְטָרִים בְּ\"הַמּוֹצִיא\". הַיַּיִן חָשׁוּב בִּמְיֻחָד, וּמְבָרְכִים עָלָיו \"בּוֹרֵא פְּרִי הַגָּפֶן\".","פֶּרֶק ג׳, הֲלָכָה ו׳","הַמּוֹצִיא לֶחֶם מִן הָאָרֶץ"],["בְּאֵיזֶה זְמַן תִּקֵּן מֹשֶׁה רַבֵּנוּ אֶת בִּרְכַּת \"הַזָּן\"?",["כְּשֶׁנִּכְנְסוּ לָאָרֶץ","כְּשֶׁנִּבְנָה בֵּית הַמִּקְדָּשׁ","כְּשֶׁיָּרַד הַמָּן בַּמִּדְבָּר"],2,"כְּשֶׁיָּרַד הַמָּן תִּקֵּן מֹשֶׁה אֶת בִּרְכַּת \"הַזָּן\". יְהוֹשֻׁעַ תִּקֵּן אֶת בִּרְכַּת הָאָרֶץ, וְדָוִד וּשְׁלֹמֹה – אֶת הַבְּרָכָה עַל יְרוּשָׁלַיִם וְהַמִּקְדָּשׁ.","פֶּרֶק ד׳, הֲלָכָה א׳","אָכַלְנוּ, שָׂבַעְנוּ – וּמְבָרְכִים"],["הַיּוֹם שַׁבָּת. אֵיזוֹ תּוֹסֶפֶת אוֹמְרִים בְּבִרְכַּת הַמָּזוֹן?",["רְצֵה וְהַחֲלִיצֵנוּ","עַל הַנִּסִּים","יַעֲלֶה וְיָבוֹא"],0,"בְּשַׁבָּת – \"רְצֵה\". \"עַל הַנִּסִּים\" – בַּחֲנֻכָּה וּבְפוּרִים, וְ\"יַעֲלֶה וְיָבוֹא\" – בְּרֹאשׁ חֹדֶשׁ, בְּחַג וּבְחֹל הַמּוֹעֵד.","פֶּרֶק ד׳, הֲלָכָה ז׳","אָכַלְנוּ, שָׂבַעְנוּ – וּמְבָרְכִים"],["שְׁלוֹשָׁה יְלָדִים מְבָרְכִים בִּרְכַּת הַמָּזוֹן. מִי מְבָרֵךְ כְּמוֹ שֶׁצָּרִיךְ?",["מִי שֶׁמְּסַדֵּר אֶת הַצַּלָּחוֹת","מִי שֶׁיּוֹשֵׁב וּמְרֻכָּז בַּבְּרָכָה","מִי שֶׁמִּסְתּוֹבֵב בַּבַּיִת"],1,"מְבָרְכִים בִּישִׁיבָה, כִּי כָּךְ קַל יוֹתֵר לְכַוֵּן. בְּאֶמְצַע הַבְּרָכָה לֹא עוֹשִׂים שׁוּם מְלָאכָה – אֲפִלּוּ לֹא מְסַדְּרִים צַלָּחוֹת.","פֶּרֶק ד׳, הֲלָכָה י״ב","אָכַלְנוּ, שָׂבַעְנוּ – וּמְבָרְכִים"],["הַסְּעוּדָה נִגְמְרָה. מָה נָכוֹן לְהַשְׁאִיר עַל הַשֻּׁלְחָן בִּזְמַן בִּרְכַּת הַמָּזוֹן?",["סַכִּין חַדָּה וּגְלוּיָה","קְלִפּוֹת שֶׁל פֵּרוֹת","מְעַט לֶחֶם"],2,"הַלֶּחֶם שֶׁנִּשְׁאַר מַרְאֶה שֶׁה׳ נָתַן לָנוּ בְּשֶׁפַע, וְשֶׁאֶפְשָׁר לָתֵת מִמֶּנּוּ לֶעָנִי. אֶת הַסַּכִּין הַחַדָּה מְכַסִּים בְּיוֹם חֹל, וְיֵשׁ מְהַדְּרִים לְהָסִיר שְׁיָרֵי אֹכֶל.","פֶּרֶק ד׳, הֲלָכָה י״א","אָכַלְנוּ, שָׂבַעְנוּ – וּמְבָרְכִים"],["אַהֲרֹן אָכַל אֲרוּחָה בַּמִּטְבָּח, יָצָא לֶחָצֵר – וְנִזְכַּר שֶׁעוֹד לֹא בֵּרַךְ. מָה יַעֲשֶׂה?",["יַחֲזֹר לַמִּטְבָּח וִיבָרֵךְ שָׁם","יְבָרֵךְ בֶּחָצֵר, אֵיפֹה שֶׁהוּא","לֹא יְבָרֵךְ, כִּי כְּבָר יָצָא"],0,"מְבָרְכִים בַּמָּקוֹם שֶׁאָכַלְנוּ בּוֹ. מִי שֶׁשָּׁכַח וְיָצָא – חוֹזֵר לִמְקוֹם הַסְּעוּדָה, וְשָׁם מְבָרֵךְ.","פֶּרֶק ד׳, הֲלָכָה י״ג","אָכַלְנוּ, שָׂבַעְנוּ – וּמְבָרְכִים"],["בְּאֵיזֶה מַצָּב חַיָּבִים לְזַמֵּן?",["בְּמִסְעָדָה, כָּל אֶחָד בְּשֻׁלְחָן אַחֵר","שְׁלוֹשָׁה שֶׁאָכְלוּ לֶחֶם יַחַד","יֶלֶד שֶׁאָכַל כָּרִיךְ לְבַד"],1,"שְׁלוֹשָׁה שֶׁקָּבְעוּ לֶאֱכֹל לֶחֶם יַחַד – חַיָּבִים לְזַמֵּן. בְּמִסְעָדָה, כְּשֶׁאֵין קֶשֶׁר בֵּין הַשֻּׁלְחָנוֹת – אֵין זִמּוּן.","פֶּרֶק ה׳, הֲלָכוֹת א׳–ב׳","אָכַלְנוּ, שָׂבַעְנוּ – וּמְבָרְכִים"],["לִסְעוּדַת שַׁבָּת הִגִּיעַ אוֹרֵחַ. לְמִי נוֹהֲגִים לָתֵת לְזַמֵּן?",["לַשָּׁכֵן שֶׁנִּכְנַס וְלֹא אָכַל","לָאוֹרֵחַ","לַבֵּן הַקָּטָן בְּיוֹתֵר"],1,"נוֹהֲגִים לְכַבֵּד אֶת הָאוֹרֵחַ, כְּדֵי שֶׁיְּבָרֵךְ בְּקוֹל אֶת בַּעַל הַבַּיִת וְכֻלָּם יַעֲנוּ אָמֵן. הַמְּזַמֵּן צָרִיךְ לִהְיוֹת מִמִּי שֶׁאָכַל לֶחֶם.","פֶּרֶק ה׳, הֲלָכוֹת ד׳, י׳","אָכַלְנוּ, שָׂבַעְנוּ – וּמְבָרְכִים"],["הַנּוֹהֲגִים לִטֹּל מַיִם אַחֲרוֹנִים – אֵיךְ נוֹטְלִים?",["מְעַט מַיִם עַל קְצוֹת הָאֶצְבָּעוֹת","שׁוֹפְכִים מַיִם עַל הָרִצְפָּה","רוֹחֲצִים אֶת הַיָּדַיִם עַד הַמַּרְפֵּק"],0,"נוֹטְלִים רַק אֶת קְצוֹת הָאֶצְבָּעוֹת, כְּשֶׁהֵן פּוֹנוֹת לְמַטָּה, לְתוֹךְ כְּלִי אוֹ כִּיּוֹר – לֹא עַל הָרִצְפָּה. וּמִיָּד מְבָרְכִים.","פֶּרֶק ד׳, הֲלָכָה י׳","אָכַלְנוּ, שָׂבַעְנוּ – וּמְבָרְכִים"],["אֵיזֶה מֵהֵם הוּא אֶחָד מֵחֲמֵשֶׁת מִינֵי הַדָּגָן?",["אֹרֶז","שִׁבֹּלֶת שׁוּעָל","תִּירָס"],1,"חֲמֵשֶׁת מִינֵי הַדָּגָן הֵם חִטָּה, שְׂעוֹרָה, כֻּסְּמִין, שִׁיפוֹן וְשִׁבֹּלֶת שׁוּעָל. אֹרֶז וְתִירָס אֵינָם בָּרְשִׁימָה.","פֶּרֶק ו׳, הֲלָכָה א׳","מִן הַשָּׂדֶה וּמִן הַכֶּרֶם"],["עַל מָה מְבָרְכִים \"בּוֹרֵא פְּרִי הָאֲדָמָה\"?",["עוּגַת שׁוֹקוֹלָד","צַלַּחַת אִטְרִיּוֹת","גַּרְעִינֵי חִטָּה חַיִּים"],2,"גַּרְעִינִים חַיִּים עוֹד לֹא הִגִּיעוּ לַמַּעֲלָה שֶׁל מַאֲפֶה אוֹ תַּבְשִׁיל, וּמְבָרְכִים עֲלֵיהֶם \"הָאֲדָמָה\". עַל עוּגָה וְעַל אִטְרִיּוֹת מְבָרְכִים \"מְזוֹנוֹת\".","פֶּרֶק ו׳, הֲלָכוֹת א׳, י״ג","מִן הַשָּׂדֶה וּמִן הַכֶּרֶם"],["עַל אֵיזֶה מַאֲכָל מְבָרְכִים \"מְזוֹנוֹת\" גַּם כְּשֶׁאוֹכְלִים מִמֶּנּוּ אֲרוּחָה שְׁלֵמָה?",["קְעָרָה גְּדוֹלָה שֶׁל פְּתִיתִים","פְּרוּסוֹת לֶחֶם","פִּיתָה"],0,"פְּתִיתִים הֵם תַּבְשִׁיל, וְעַל תַּבְשִׁיל מִדָּגָן מְבָרְכִים תָּמִיד \"מְזוֹנוֹת\" וְ\"עַל הַמִּחְיָה\". עַל לֶחֶם וּפִיתָה מְבָרְכִים \"הַמּוֹצִיא\" – גַּם כְּשֶׁאוֹכְלִים מְעַט.","פֶּרֶק ו׳, הֲלָכָה י׳","מִן הַשָּׂדֶה וּמִן הַכֶּרֶם"],["אֵיזֶה מַאֲפֶה הוּא \"פַּת הַבָּאָה בְּכִסָּנִין\", שֶׁמְּבָרְכִים עָלָיו \"מְזוֹנוֹת\"?",["פְּרוּסַת לֶחֶם","אָזְנֵי הָמָן","לַחְמָנִיָּה רְגִילָה"],1,"אָזְנֵי הָמָן הֵן מַאֲפֶה מְמֻלָּא בְּמִלּוּי מָתוֹק, שֶׁאוֹכְלִים לְקִנּוּחַ – \"מְזוֹנוֹת\". לֶחֶם וְלַחְמָנִיָּה נוֹעֲדוּ לִסְעוּדָה – \"הַמּוֹצִיא\".","פֶּרֶק ו׳, הֲלָכָה ב׳","מִן הַשָּׂדֶה וּמִן הַכֶּרֶם"],["סֻפְגָּנִיּוֹת מְטֻגָּנוֹת בְּשֶׁמֶן עָמֹק. לְמָה הֵן דּוֹמוֹת בְּדִינָן?",["לְלֶחֶם","לְעוּגָה אֲפוּיָה","לְתַבְשִׁיל"],2,"טִגּוּן בְּשֶׁמֶן עָמֹק נֶחְשָׁב כְּמוֹ בִּשּׁוּל. לָכֵן עַל סֻפְגָּנִיּוֹת מְבָרְכִים תָּמִיד \"מְזוֹנוֹת\" וְ\"עַל הַמִּחְיָה\". (סֻפְגָּנִיּוֹת אֲפוּיוֹת – דִּינָן כְּעוּגָה.)","פֶּרֶק ו׳, הֲלָכָה י׳","מִן הַשָּׂדֶה וּמִן הַכֶּרֶם"],["עַל אֵיזֶה מַשְׁקֶה מְבָרְכִים \"בּוֹרֵא פְּרִי הַגֶּפֶן\"?",["מִיץ תַּפּוּזִים","מִיץ תַּפּוּחִים","מִיץ עֲנָבִים"],2,"מִיץ עֲנָבִים יוֹצֵא מִפְּרִי הַגֶּפֶן כְּמוֹ הַיַּיִן, וְזוֹכֶה לִבְרָכָתוֹ – \"הַגֶּפֶן\". עַל שְׁאָר מִיצֵי הַפֵּרוֹת מְבָרְכִים \"שֶׁהַכֹּל\".","פֶּרֶק ז׳, הֲלָכוֹת ג׳, ו׳","מִן הַשָּׂדֶה וּמִן הַכֶּרֶם"],["עַל מָה מְבָרְכִים \"בּוֹרֵא פְּרִי הָעֵץ\"?",["אֶשְׁכּוֹל עֲנָבִים","כּוֹס מִיץ עֲנָבִים","כּוֹס מִיץ תַּפּוּזִים"],0,"עַל עֲנָבִים – כְּמוֹ עַל כָּל פְּרִי הָעֵץ – \"הָעֵץ\". מִיץ הָעֲנָבִים הִתְעַלָּה וּמְבָרְכִים עָלָיו \"הַגֶּפֶן\", וּמִיץ תַּפּוּזִים אִבֵּד אֶת מַעֲלַת הַפְּרִי – \"שֶׁהַכֹּל\".","פֶּרֶק ז׳, הֲלָכָה ג׳","מִן הַשָּׂדֶה וּמִן הַכֶּרֶם"],["בַּקִּדּוּשׁ שֶׁבְּבֵית הַכְּנֶסֶת שָׁמַע יוֹסִי אֶת הַקִּדּוּשׁ וְשָׁתָה מִיץ עֲנָבִים. עַכְשָׁו הוּא רוֹצֶה כּוֹס מַיִם מִן הַשֻּׁלְחָן. מָה יַעֲשֶׂה?",["שׁוֹתֶה בְּלִי בְּרָכָה","מְבָרֵךְ \"שֶׁהַכֹּל\" וְשׁוֹתֶה","מְבָרֵךְ שׁוּב \"הַגֶּפֶן\""],0,"בִּרְכַּת \"הַגֶּפֶן\" עַל הַיַּיִן אוֹ עַל מִיץ הָעֲנָבִים פּוֹטֶרֶת אֶת כָּל הַמַּשְׁקִים שֶׁעַל הַשֻּׁלְחָן – וְיוֹסִי שׁוֹתֶה בְּלִי בְּרָכָה נוֹסֶפֶת.","פֶּרֶק ז׳, הֲלָכוֹת ד׳, ו׳","מִן הַשָּׂדֶה וּמִן הַכֶּרֶם"],["עַל אֵיזֶה פְּרִי מְבָרְכִים \"בּוֹרֵא פְּרִי הָעֵץ\"?",["עַגְבָנִיָּה","תַּפּוּחַ","מְלָפְפוֹן"],1,"הַתַּפּוּחַ גָּדֵל עַל עֵץ שֶׁהַגֶּזַע שֶׁלּוֹ נִשְׁאָר שָׁנִים רַבּוֹת – \"הָעֵץ\". עַל עַגְבָנִיָּה וּמְלָפְפוֹן מְבָרְכִים \"הָאֲדָמָה\".","פֶּרֶק ח׳, הֲלָכָה א׳","הָעֵץ, הָאֲדָמָה וְשֶׁהַכֹּל"],["עַל אֵיזֶה פְּרִי מְבָרְכִים \"בּוֹרֵא פְּרִי הָאֲדָמָה\"?",["בָּנָנָה","עֲנָבִים","אַגָּס"],0,"הַבָּנָנָה גְּבוֹהָה כְּמוֹ עֵץ, אֲבָל הַגֶּזַע שֶׁלָּהּ נוֹבֵל בְּסוֹף כָּל עוֹנָה – וְלָכֵן \"הָאֲדָמָה\". עַל עֲנָבִים וְעַל אַגָּס – \"הָעֵץ\".","פֶּרֶק ח׳, הֲלָכָה ב׳","הָעֵץ, הָאֲדָמָה וְשֶׁהַכֹּל"],["עַל מָה מְבָרְכִים \"שֶׁהַכֹּל\"?",["תִּירָס","שְׁקֵדִים","פִּטְרִיּוֹת"],2,"הַפִּטְרִיּוֹת נִרְאוֹת כְּמוֹ יְרָקוֹת, אֲבָל הֵן לֹא יוֹנְקוֹת מְזוֹן מִן הָאֲדָמָה – וְלָכֵן \"שֶׁהַכֹּל\". תִּירָס – \"הָאֲדָמָה\", שְׁקֵדִים – \"הָעֵץ\".","פֶּרֶק ח׳, הֲלָכוֹת א׳, ג׳","הָעֵץ, הָאֲדָמָה וְשֶׁהַכֹּל"],["מָתַי שׁוֹתִים מַיִם בְּלִי לְבָרֵךְ?",["אַחֲרֵי רִיצָה בַּחוּץ","כְּדֵי לִבְלֹעַ כַּדּוּר","בְּיוֹם חַם וְצָמֵא"],1,"מִי שֶׁשּׁוֹתֶה מְעַט מַיִם רַק כְּדֵי לִבְלֹעַ כַּדּוּר – לֹא נֶהֱנֶה, וְלָכֵן לֹא מְבָרֵךְ. מִי שֶׁשּׁוֹתֶה לַצָּמָא – מְבָרֵךְ \"שֶׁהַכֹּל\".","פֶּרֶק ט׳, הֲלָכָה א׳","הָעֵץ, הָאֲדָמָה וְשֶׁהַכֹּל"],["אֵיזֶה מַאֲכָל מִתַּפּוּחֵי אֲדָמָה בִּרְכָתוֹ \"שֶׁהַכֹּל\"?",["צִ׳יפְּס","פִּירֶה","תַּפּוּחַ אֲדָמָה חַי"],2,"תַּפּוּחַ אֲדָמָה רְגִילִים לֶאֱכֹל מְבֻשָּׁל, וּמִי שֶׁאוֹכֵל אוֹתוֹ חַי מְבָרֵךְ \"שֶׁהַכֹּל\". עַל צִ׳יפְּס וּפִירֶה – \"הָאֲדָמָה\".","פֶּרֶק ח׳, הֲלָכוֹת י״ב, י״ד","הָעֵץ, הָאֲדָמָה וְשֶׁהַכֹּל"],["עַל אֵיזֶה מַאֲכָל מְבָרְכִים \"בּוֹרֵא פְּרִי הָאֲדָמָה\"?",["סֻכָּרִיָּה","סָלָט יְרָקוֹת חָתוּךְ","כּוֹס חָלָב"],1,"בַּסָּלָט הַיְּרָקוֹת רַק נֶחְתְּכוּ, וְרוֹאִים אוֹתָם – \"הָאֲדָמָה\". עַל סֻכָּרִיָּה וְעַל חָלָב מְבָרְכִים \"שֶׁהַכֹּל\".","פֶּרֶק ח׳, הֲלָכוֹת ח׳, י׳, י״ב","הָעֵץ, הָאֲדָמָה וְשֶׁהַכֹּל"],["אָבִי רוֹצֶה לֶאֱכֹל תַּפּוּז. מָה יַעֲשֶׂה לִפְנֵי הַבְּרָכָה?",["יָשִׂים אוֹתוֹ בַּמְּקָרֵר","יַרְאֶה אוֹתוֹ לְאָחִיו","יְקַלֵּף אֶת הַתַּפּוּז"],2,"קֹדֶם מְכִינִים אֶת הַמַּאֲכָל, וְרַק אָז מְבָרְכִים – כְּדֵי לֶאֱכֹל מִיָּד אַחֲרֵי הַבְּרָכָה, בְּלִי הֶפְסֵק.","פֶּרֶק ט׳, הֲלָכָה ג׳","הָעֵץ, הָאֲדָמָה וְשֶׁהַכֹּל"],["אַחֲרֵי אֵיזֶה פְּרִי מְבָרְכִים \"עַל הָעֵץ\" (מֵעֵין שָׁלֹשׁ)?",["תַּפּוּחַ","תְּאֵנִים","אַגָּס"],1,"הַתְּאֵנָה הִיא מִשִּׁבְעַת הַמִּינִים, וְלָכֵן אַחֲרֶיהָ מְבָרְכִים \"עַל הָעֵץ\". אַחֲרֵי תַּפּוּחַ וְאַגָּס – \"בּוֹרֵא נְפָשׁוֹת\".","פֶּרֶק י׳, הֲלָכָה ב׳","בְּרָכָה אַחֲרוֹנָה, עִקָּר וְטָפֵל"],["אַחֲרֵי אֵיזֶה מַאֲכָל מְבָרְכִים \"בּוֹרֵא נְפָשׁוֹת\"?",["בָּנָנָה","תְּמָרִים","עוּגָה"],0,"הַבָּנָנָה אֵינָהּ מִשִּׁבְעַת הַמִּינִים – \"בּוֹרֵא נְפָשׁוֹת\". אַחֲרֵי תְּמָרִים – \"עַל הָעֵץ\", וְאַחֲרֵי עוּגָה – \"עַל הַמִּחְיָה\".","פֶּרֶק י׳, הֲלָכוֹת ב׳, ד׳","בְּרָכָה אַחֲרוֹנָה, עִקָּר וְטָפֵל"],["אַחֲרֵי כַּמָּה אֹכֶל מְבָרְכִים בְּרָכָה אַחֲרוֹנָה?",["פֵּרוּר קָטָן","גַּרְגִּיר אֹרֶז אֶחָד","חֲצִי בֵּיצָה וְיוֹתֵר"],2,"בְּרָכָה אַחֲרוֹנָה מְבָרְכִים רַק אַחֲרֵי \"כְּזַיִת\" – וְנוֹהֲגִים לְשַׁעֵר אוֹתוֹ כְּנֶפַח חֲצִי בֵּיצָה.","פֶּרֶק י׳, הֲלָכָה ה׳","בְּרָכָה אַחֲרוֹנָה, עִקָּר וְטָפֵל"],["אֵיזֶה מֵהֵם נֶחְשָׁב אֹכֶל וְלֹא מַשְׁקֶה?",["מִיץ תַּפּוּזִים","גְּלִידָה בִּקְעָרָה","כּוֹס מַיִם"],1,"גְּלִידָה לֹא נִשְׁפֶּכֶת לְכָל הַצְּדָדִים, וְלוֹעֲטִים אוֹתָהּ בַּלָּשׁוֹן – וְלָכֵן הִיא אֹכֶל. מִיץ וּמַיִם – מַשְׁקִים.","פֶּרֶק י׳, הֲלָכָה י״א","בְּרָכָה אַחֲרוֹנָה, עִקָּר וְטָפֵל"],["מָתַי צָרִיךְ לְבָרֵךְ אֶת הַבְּרָכָה הָאַחֲרוֹנָה?",["בָּעֶרֶב, לִפְנֵי הַשֵּׁנָה","לְמָחֳרָת בַּבֹּקֶר","מִיָּד בְּסוֹף הָאֲכִילָה"],2,"מְבָרְכִים מִיָּד כְּשֶׁגּוֹמְרִים לֶאֱכֹל, לִפְנֵי שֶׁעוֹסְקִים בְּדָבָר אַחֵר – וְכָךְ גַּם לֹא שׁוֹכְחִים.","פֶּרֶק י׳, הֲלָכָה י״ב","בְּרָכָה אַחֲרוֹנָה, עִקָּר וְטָפֵל"],["רוֹנִי אוֹכֵל פְּתִיתִים עִם קֶטְשׁוֹפּ. עַל מָה יְבָרֵךְ?",["עַל הַפְּתִיתִים בִּלְבַד","עַל הַקֶּטְשׁוֹפּ בִּלְבַד","עַל כָּל אֶחָד בְּנִפְרָד"],0,"הַקֶּטְשׁוֹפּ בָּא רַק כְּדֵי לְהַטְעִים אֶת הַפְּתִיתִים – הוּא טָפֵל. מְבָרְכִים \"מְזוֹנוֹת\" עַל הַפְּתִיתִים, וְהַקֶּטְשׁוֹפּ נִפְטָר.","פֶּרֶק י״א, הֲלָכָה א׳","בְּרָכָה אַחֲרוֹנָה, עִקָּר וְטָפֵל"],["אֵיזֶה מַמְתָּק בִּרְכָתוֹ \"בּוֹרֵא פְּרִי הָעֵץ\"?",["סֻכָּרִיָּה וּבְתוֹכָהּ שָׁקֵד","שְׁקֵדִים מְצֻפִּים בְּשׁוֹקוֹלָד","שׁוֹקוֹלָד עִם אֱגוֹזִים"],1,"בַּשְּׁקֵדִים הַמְּצֻפִּים הַשָּׁקֵד הוּא הָעִקָּר – \"הָעֵץ\". סֻכָּרִיָּה עִם שָׁקֵד וְשׁוֹקוֹלָד עִם אֱגוֹזִים – \"שֶׁהַכֹּל\", כִּי הַפְּרִי טָפֵל. שֵׁם הַמַּמְתָּק מְלַמֵּד מָה הָעִקָּר.","פֶּרֶק י״א, הֲלָכָה ח׳","בְּרָכָה אַחֲרוֹנָה, עִקָּר וְטָפֵל"],["עַל אֵיזֶה מַאֲכָל מְבָרְכִים \"מְזוֹנוֹת\"?",["סָלָט יְרָקוֹת וּבוֹ כַּמָּה זֵיתִים","שְׁנִיצֶל עוֹף","אֹרֶז עִם צִמּוּקִים"],2,"בָּאֹרֶז עִם הַצִּמּוּקִים הָאֹרֶז עִקָּר – \"מְזוֹנוֹת\". בַּסָּלָט הַיְּרָקוֹת עִקָּר – \"הָאֲדָמָה\". וּבַשְּׁנִיצֶל הַבָּשָׂר עִקָּר וְהַצִּפּוּי רַק מַטְעִים – \"שֶׁהַכֹּל\".","פֶּרֶק י״א, הֲלָכוֹת ג׳, ה׳","בְּרָכָה אַחֲרוֹנָה, עִקָּר וְטָפֵל"],["בְּאֵיזֶה מַצָּב ״הַמּוֹצִיא״ הִיא בְּרָכָה לְבַטָּלָה?",["לִפְנֵי שֶׁאוֹכְלִים פְּרוּסָה","כְּשֶׁאֵין לֶחֶם בִּכְלָל","עַל חַלָּה בְּשַׁבָּת"],1,"״הַמּוֹצִיא״ מְבָרְכִים רַק כְּשֶׁאוֹכְלִים לֶחֶם. בְּלִי לֶחֶם – זוֹ בְּרָכָה לְבַטָּלָה, וְאוֹמְרִים מִיָּד ״בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד״.","פֶּרֶק י״ב, הֲלָכָה א׳","בְּרָכָה בִּמְקוֹמָהּ וְשֻׁלְחָן שֶׁל חֶסֶד"],["אָחִיו הַקָּטָן שֶׁל דָּנִי, בֶּן שֵׁשׁ, בֵּרֵךְ יָפֶה ״שֶׁהַכֹּל״ עַל מַיִם. מָה יַעֲשֶׂה דָּנִי?",["יַעֲנֶה אָמֵן","יִשְׁתֹּק","יְבָרֵךְ בִּמְקוֹמוֹ"],0,"יֶלֶד שֶׁיּוֹדֵעַ לְבָרֵךְ כָּרָאוּי – עוֹנִים אַחֲרָיו אָמֵן, כְּמוֹ אַחֲרֵי גָּדוֹל. בְּדֶרֶךְ כְּלָל יְלָדִים מַגִּיעִים לְכָךְ בְּגִיל חָמֵשׁ אוֹ שֵׁשׁ.","פֶּרֶק י״ב, הֲלָכָה ח׳","בְּרָכָה בִּמְקוֹמָהּ וְשֻׁלְחָן שֶׁל חֶסֶד"],["בִּסְעוּדַת שַׁבָּת הַמִּשְׁפָּחָה יוֹשֶׁבֶת יַחַד. מִי מְבָרֵךְ ״הַמּוֹצִיא״?",["כָּל אֶחָד לְעַצְמוֹ","רַק הַיֶּלֶד הַקָּטָן","אַבָּא בִּשְׁבִיל כֻּלָּם"],2,"כְּשֶׁיּוֹשְׁבִים לֶאֱכֹל לֶחֶם יַחַד, טוֹב שֶׁאֶחָד יְבָרֵךְ לְכֻלָּם וְכֻלָּם יַעֲנוּ אָמֵן – ״בְּרָב עָם הַדְרַת מֶלֶךְ״. בְּשַׁבָּת גְּדוֹל הַבַּיִת מְבָרֵךְ.","פֶּרֶק י״ב, הֲלָכָה ז׳","בְּרָכָה בִּמְקוֹמָהּ וְשֻׁלְחָן שֶׁל חֶסֶד"],["אָסוּר לִטְעֹם כְּלוּם לִפְנֵי שֶׁמַּאֲכִילִים אֶת בַּעֲלֵי הַחַיִּים. אֶת אֵילוּ?",["אֶת הַתַּרְנְגוֹלוֹת שֶׁלָּנוּ בֶּחָצֵר","אֶת הַיּוֹנִים בַּגַּן הַצִּבּוּרִי","אֶת הַדָּגִים בַּיָּם"],0,"הַמִּצְוָה הִיא עַל בַּעֲלֵי חַיִּים שֶׁלָּנוּ, שֶׁאֵין לָהֶם אֹכֶל אֶלָּא מִמֶּנּוּ. כָּתוּב ״וְנָתַתִּי עֵשֶׂב בְּשָׂדְךָ לִבְהֶמְתֶּךָ״ – וְרַק אַחַר כָּךְ ״וְאָכַלְתָּ וְשָׂבָעְתָּ״.","פֶּרֶק י״ג, הֲלָכָה א׳","בְּרָכָה בִּמְקוֹמָהּ וְשֻׁלְחָן שֶׁל חֶסֶד"],["מָה מֻתָּר לִזְרֹק לְחָבֵר מֵעֵבֶר לַשֻּׁלְחָן?",["תְּמָרִים","אֱגוֹזִים בִּקְלִפָּה","תְּאֵנִים"],1,"אָסוּר לִזְרֹק מַאֲכָל שֶׁיִּתְלַכְלֵךְ וְיִמָּאֵס אִם יִפֹּל, כְּמוֹ תְּמָרִים וּתְאֵנִים. אֱגוֹזִים לֹא נִפְגָּעִים, וּמֻתָּר לִזְרֹק אוֹתָם.","פֶּרֶק י״ג, הֲלָכָה ג׳","בְּרָכָה בִּמְקוֹמָהּ וְשֻׁלְחָן שֶׁל חֶסֶד"],["אֵיזֶה יֶלֶד שׁוֹמֵר עַל הַלֶּחֶם?",["מַעֲבִיר כּוֹס מְלֵאָה מֵעַל הַלֶּחֶם","מַנִּיחַ צַלַּחַת מְלֻכְלֶכֶת עַל הַלֶּחֶם","מַעֲבִיר אֶת הַכּוֹס מִצַּד הַשֻּׁלְחָן"],2,"חֲכָמִים הִזְהִירוּ שֶׁלֹּא לְהַעֲבִיר כּוֹס מְלֵאָה מֵעַל הַלֶּחֶם – שֶׁמָּא תִּשָּׁפֵךְ וְתַהֲרֹס אוֹתוֹ. וְגַם לֹא מַנִּיחִים עַל הַלֶּחֶם כְּלִי מְלֻכְלָךְ.","פֶּרֶק י״ג, הֲלָכָה ג׳","בְּרָכָה בִּמְקוֹמָהּ וְשֻׁלְחָן שֶׁל חֶסֶד"],["אַחֲרֵי הָאֲרוּחָה נִשְׁאֲרוּ פֵּרוּרֵי לֶחֶם עַל הַשֻּׁלְחָן. מָה נָכוֹן לַעֲשׂוֹת?",["לֶאֱסֹף וּלְהַנִּיחַ בַּפַּח","לְנַעֵר אוֹתָם לָרִצְפָּה","לְפַזֵּר לְיַד פַּחֵי הָרְחוֹב"],0,"פֵּרוּרִים לֹא זוֹרְקִים לָרִצְפָּה, שֶׁשָּׁם דּוֹרְכִים עֲלֵיהֶם. גַּם לֹא מַשְׁאִירִים לֶחֶם לְיַד פַּחֵי הָאַשְׁפָּה – זֶה בִּזָּיוֹן לַלֶּחֶם וְצַעַר לַשְּׁכֵנִים. אוֹסְפִים, וּמַנִּיחִים בַּפַּח בְּכָבוֹד.","פֶּרֶק י״ג, הֲלָכָה ד׳","בְּרָכָה בִּמְקוֹמָהּ וְשֻׁלְחָן שֶׁל חֶסֶד"],["יוֹאָב רוֹצֶה רַק חֲצִי פְּרוּסָה. מָה נָכוֹן?",["נוֹגֵס, וּמַחֲזִיר אֶת הַשְּׁאָר לַסַּל","חוֹתֵךְ חֲצִי, וְהַשְּׁאָר נִשְׁאָר בַּסַּל","נוֹגֵס, וְנוֹתֵן אֶת הַשְּׁאָר לְחָבֵר"],1,"מִפְּרוּסָה נְגוּסָה רַבִּים נִגְעָלִים. לָכֵן חוֹתְכִים מֵרֹאשׁ רַק מָה שֶׁרוֹצִים לֶאֱכֹל, וְהַשְּׁאָר נִשְׁאָר בַּסַּל.","פֶּרֶק י״ג, הֲלָכָה ו׳","בְּרָכָה בִּמְקוֹמָהּ וְשֻׁלְחָן שֶׁל חֶסֶד"],["עַל מָה מְבָרְכִים ״בּוֹרֵא עֲצֵי בְשָׂמִים״?",["לִימוֹן","עֲנַף הֲדַס","פֶּרַח נַרְקִיס"],1,"הֲדַס הוּא שִׂיחַ שֶׁגִּבְעוֹלוֹ קָשֶׁה – ״עֲצֵי בְשָׂמִים״. עַל נַרְקִיס, שֶׁגִּבְעוֹלוֹ רַךְ – ״עִשְׂבֵי בְשָׂמִים״. וְעַל לִימוֹן שֶׁלּוֹקְחִים כְּדֵי לְהָרִיחַ – ״הַנּוֹתֵן רֵיחַ טוֹב בַּפֵּרוֹת״.","פֶּרֶק י״ד, הֲלָכָה ה׳","רֵיחַ טוֹב וּמַרְאוֹת נִפְלָאִים"],["עַל אֵיזֶה רֵיחַ טוֹב מְבָרְכִים?",["סַבּוֹן רַחְצָה","מְטַהֵר אֲוִיר בַּשֵּׁרוּתִים","שִׂיחַ יַסְמִין בַּגִּנָּה"],2,"שִׂיחַ שֶׁשָּׁתְלוּ בַּגִּנָּה כְּדֵי לְהָפִיץ רֵיחַ טוֹב – מְבָרְכִים עָלָיו ״עֲצֵי בְשָׂמִים״. סַבּוֹן נוֹעַד לְנַקּוֹת, וּמְטַהֵר אֲוִיר – לְהַרְחִיק רֵיחַ רַע, וְלָכֵן לֹא מְבָרְכִים עֲלֵיהֶם.","פֶּרֶק י״ד, הֲלָכוֹת ג׳–ד׳","רֵיחַ טוֹב וּמַרְאוֹת נִפְלָאִים"],["שְׁמוּאֵל עוֹבֵר לְיַד פַּרְדֵּס פּוֹרֵחַ. מָתַי יְבָרֵךְ עַל הָרֵיחַ?",["נִגָּשׁ וּמֵרִיחַ פֶּרַח","רַק עוֹבֵר בַּשְּׁבִיל","קוֹטֵף תַּפּוּז לֶאֱכֹל"],0,"פַּרְדֵּס נוֹעַד לְגַדֵּל פֵּרוֹת, וְהָרֵיחַ שֶׁלּוֹ טָפֵל. רַק מִי שֶׁעוֹשֶׂה מַעֲשֶׂה וְנִגָּשׁ לְהָרִיחַ – מַחְשִׁיב אֶת הָרֵיחַ, וּמְבָרֵךְ.","פֶּרֶק י״ד, הֲלָכָה ד׳","רֵיחַ טוֹב וּמַרְאוֹת נִפְלָאִים"],["עַל אֵיזֶה רֵיחַ טוֹב לֹא מְבָרְכִים?",["לֶחֶם חַם מֵהַתַּנּוּר","קָפֶה שֶׁטּוֹחֲנִים בַּחֲנוּת","עֲנַף רוֹזְמָרִין"],0,"רֵיחַ הַלֶּחֶם רַק מְעוֹרֵר תֵּאָבוֹן, וְהוּא טָפֵל לָאֲכִילָה. עַל קָפֶה שֶׁטּוֹחֲנִים בַּחֲנוּת – ״מִינֵי בְשָׂמִים״, וְעַל רוֹזְמָרִין – ״עֲצֵי בְשָׂמִים״.","פֶּרֶק י״ד, הֲלָכָה ה׳","רֵיחַ טוֹב וּמַרְאוֹת נִפְלָאִים"],["עַל מָה מְבָרְכִים ״זוֹכֵר הַבְּרִית״?",["בָּרָק בַּשָּׁמַיִם","עֵצִים פּוֹרְחִים","קֶשֶׁת בֶּעָנָן"],2,"״זוֹכֵר הַבְּרִית וְנֶאֱמָן בִּבְרִיתוֹ וְקַיָּם בְּמַאֲמָרוֹ״ – עַל הַקֶּשֶׁת, אוֹת הַבְּרִית שֶׁל ה׳ עִם נֹחַ, שֶׁלֹּא יָבוֹא עוֹד מַבּוּל.","פֶּרֶק ט״ו, הֲלָכָה י׳","רֵיחַ טוֹב וּמַרְאוֹת נִפְלָאִים"],["עַל מָה נוֹהֲגִים לְבָרֵךְ ״שֶׁכֹּחוֹ וּגְבוּרָתוֹ מָלֵא עוֹלָם״?",["שְׁקִיעָה יָפָה","רַעַם חָזָק","קֶשֶׁת בֶּעָנָן"],1,"עַל הָרַעַם, שֶׁקּוֹלוֹ מַפְחִיד, נוֹהֲגִים לְבָרֵךְ ״שֶׁכֹּחוֹ וּגְבוּרָתוֹ״. עַל הַבָּרָק – ״עוֹשֶׂה מַעֲשֵׂה בְרֵאשִׁית״, וְעַל הַקֶּשֶׁת – ״זוֹכֵר הַבְּרִית״.","פֶּרֶק ט״ו, הֲלָכָה ז׳","רֵיחַ טוֹב וּמַרְאוֹת נִפְלָאִים"],["עַל אֵיזֶה עֵץ מְבָרְכִים בִּרְכַּת הָאִילָנוֹת?",["עֵץ תַּפּוּחַ פּוֹרֵחַ","עֵץ אֹרֶן יָרֹק וְגָבוֹהַּ","עֵץ עִם תַּפּוּחִים גְּדוֹלִים"],0,"מְבָרְכִים עַל עֵץ פְּרִי בִּזְמַן הַפְּרִיחָה – שֶׁמִּפְּרָחָיו יִצְמְחוּ פֵּרוֹת. עַל עֵץ שֶׁאֵינוֹ נוֹתֵן פְּרִי לֹא מְבָרְכִים, וְגַם לֹא כְּשֶׁהַפֵּרוֹת כְּבָר גְּדוֹלִים.","פֶּרֶק ט״ו, הֲלָכָה ח׳","רֵיחַ טוֹב וּמַרְאוֹת נִפְלָאִים"],["בְּגַן הַחַיּוֹת. עַל אֵיזוֹ חַיָּה מְבָרְכִים ״מְשַׁנֶּה הַבְּרִיּוֹת״?",["אַרְיֵה","פִּיל","זֶבְּרָה"],1,"עַל הַקּוֹף וְעַל הַפִּיל מְבָרְכִים ״מְשַׁנֶּה הַבְּרִיּוֹת״, כִּי הֵם דּוֹמִים קְצָת לָאָדָם. הַפִּיל מְשַׁמֵּשׁ בַּחֶדֶק כְּמוֹ בְּיָד, וְעוֹרוֹ חָלָק בְּלִי שְׂעָרוֹת.","פֶּרֶק ט״ו, הֲלָכָה ט״ו","רֵיחַ טוֹב וּמַרְאוֹת נִפְלָאִים"],["מִי צָרִיךְ לְבָרֵךְ \"הַגּוֹמֵל\"?",["מִי שֶׁקָּנָה חֻלְצָה חֲדָשָׁה","מִי שֶׁיָּשַׁן שְׁנַת צָהֳרַיִם","מִי שֶׁהִבְרִיא מִמַּחֲלָה מְסֻכֶּנֶת"],2,"חוֹלֶה שֶׁהִבְרִיא הוּא אֶחָד מֵהָאַרְבָּעָה שֶׁצְּרִיכִים לְהוֹדוֹת בְּבִרְכַּת הַגּוֹמֵל. עַל חֻלְצָה חֲדָשָׁה מְבָרְכִים \"שֶׁהֶחֱיָנוּ\".","פֶּרֶק ט״ז, הֲלָכוֹת א׳, ד׳","תּוֹדָה עַל כָּל טוֹבָה"],["בִּפְנֵי מִי מְבָרְכִים \"הַגּוֹמֵל\"?",["בִּפְנֵי מִנְיָן שֶׁל עֲשָׂרָה","לְבַד בַּחֶדֶר","בִּפְנֵי חָבֵר אֶחָד"],0,"בִּרְכַּת הַגּוֹמֵל נֶאֱמֶרֶת בִּפְנֵי מִנְיָן, כְּדֵי לְהוֹדוֹת לַה׳ \"בִּקְהַל עָם\". בְּלִי מִנְיָן – לֹא מְבָרְכִים.","פֶּרֶק ט״ז, הֲלָכָה ב׳","תּוֹדָה עַל כָּל טוֹבָה"],["עַל אֵיזֶה פְּרִי מְבָרְכִים \"שֶׁהֶחֱיָנוּ\"?",["בָּנָנָה","דֻּבְדְּבָנִים בִּתְחִלַּת הָעוֹנָה","תַּפּוּחַ אֲדָמָה"],1,"דֻּבְדְּבָנִים מוֹפִיעִים רַק בְּעוֹנָה מְסֻיֶּמֶת, וּכְשֶׁהֵם מִתְחַדְּשִׁים מְבָרְכִים \"שֶׁהֶחֱיָנוּ\". בָּנָנוֹת וְתַפּוּחֵי אֲדָמָה נִמְצָאִים כָּל הַשָּׁנָה.","פֶּרֶק י״ז, הֲלָכָה ט״ו","תּוֹדָה עַל כָּל טוֹבָה"],["עַל מָה מְבָרְכִים \"שֶׁהֶחֱיָנוּ\"?",["זוּג גַּרְבַּיִם חֲדָשִׁים","קְנִיּוֹת אֹכֶל לַשָּׁבוּעַ","חֻלְצַת שַׁבָּת חֲדָשָׁה וְיָפָה"],2,"עַל בֶּגֶד יָפֶה שֶׁשְּׂמֵחִים בּוֹ מְבָרְכִים \"שֶׁהֶחֱיָנוּ\". עַל גַּרְבַּיִם וְעַל קְנִיּוֹת אֹכֶל רְגִילוֹת – לֹא, כִּי אֵין רְגִילִים לִשְׂמֹחַ בָּהֶם.","פֶּרֶק י״ז, הֲלָכָה ד׳","תּוֹדָה עַל כָּל טוֹבָה"],["מָתַי נוֹהֲגִים לְבָרֵךְ \"שֶׁהֶחֱיָנוּ\" עַל פְּרִי חָדָשׁ?",["בַּפַּעַם הָרִאשׁוֹנָה שֶׁאוֹכְלִים מִמֶּנּוּ","בַּפַּעַם הַשְּׁנִיָּה שֶׁאוֹכְלִים מִמֶּנּוּ","כְּשֶׁהַפְּרִי עוֹד יָרֹק וְלֹא בָּשֵׁל"],0,"נוֹהֲגִים לְבָרֵךְ בָּאֲכִילָה הָרִאשׁוֹנָה, כְּשֶׁהַשִּׂמְחָה מִתְחַדֶּשֶׁת. מִי שֶׁשָּׁכַח – לֹא מְבָרֵךְ בַּשְּׁנִיָּה. וְעַל פְּרִי שֶׁעוֹד לֹא בָּשֵׁל לֹא מְבָרְכִים.","פֶּרֶק י״ז, הֲלָכָה י״ד","תּוֹדָה עַל כָּל טוֹבָה"],["אֵלִיָּהוּ פָּגַשׁ חָבֵר טוֹב וְשָׂמַח מְאוֹד. מָתַי יְבָרֵךְ \"שֶׁהֶחֱיָנוּ\"?",["אִם רָאָה אוֹתוֹ אֶתְמוֹל","אִם לֹא רָאָה אוֹתוֹ יוֹתֵר מִשְּׁלֹשִׁים יוֹם","אִם הֵם לוֹמְדִים יַחַד כָּל יוֹם"],1,"מְבָרְכִים עַל חָבֵר טוֹב רַק אַחֲרֵי שְׁלֹשִׁים יוֹם שֶׁלֹּא רָאוּ זֶה אֶת זֶה. אִם נִפְגְּשׁוּ בְּתוֹךְ שְׁלֹשִׁים יוֹם – אֵין חִדּוּשׁ.","פֶּרֶק י״ז, הֲלָכָה י׳","תּוֹדָה עַל כָּל טוֹבָה"],["מָתַי אוֹמְרִים \"תְּפִלַּת הַדֶּרֶךְ\"?",["כְּשֶׁהוֹלְכִים לַמַּכֹּלֶת שֶׁלְּיַד הַבַּיִת","לִפְנֵי הַשֵּׁנָה בַּלַּיְלָה","כְּשֶׁיּוֹצְאִים לִנְסִיעָה לְעִיר אַחֶרֶת"],2,"\"תְּפִלַּת הַדֶּרֶךְ\" נֶאֱמֶרֶת כְּשֶׁיּוֹצְאִים לְדֶרֶךְ אֲרֻכָּה מִחוּץ לָעִיר. הֲלִיכָה קְצָרָה לַמַּכֹּלֶת אֵינָהּ \"דֶּרֶךְ\".","פֶּרֶק י״ח, הֲלָכוֹת ב׳–ג׳","תּוֹדָה עַל כָּל טוֹבָה"],["בְּאֵיזֶה מִקְרֶה מְבָרְכִים \"הַטּוֹב וְהַמֵּטִיב\"?",["אַבָּא שָׂמֵחַ בַּמְּעִיל שֶׁקָּנָה לִבְנוֹ","יֶלֶד אוֹכֵל לְבַד פְּרִי חָדָשׁ","יֶלֶד פּוֹגֵשׁ חָבֵר אַחֲרֵי חֹדֶשׁ"],0,"הוֹרִים שֶׁקָּנוּ בֶּגֶד לִבְנָם שְׂמֵחִים בּוֹ יַחַד אִתּוֹ – וּמְבָרְכִים \"הַטּוֹב וְהַמֵּטִיב\". עַל פְּרִי חָדָשׁ וְעַל חָבֵר מְבָרְכִים \"שֶׁהֶחֱיָנוּ\".","פֶּרֶק י״ז, הֲלָכָה ג׳","תּוֹדָה עַל כָּל טוֹבָה"]],"b":[["אֲרִיאֵל בֵּרֵךְ עַל תַּפּוּחַ וְשָׁכַח לוֹמַר \"מֶלֶךְ הָעוֹלָם\". מָה הַדִּין?",["יָצָא, כִּי הִזְכִּיר אֶת שֵׁם ה׳ בִּתְחִלַּת הַבְּרָכָה","לֹא יָצָא, וְצָרִיךְ לְבָרֵךְ שׁוּב כָּרָאוּי","יָצָא, כִּי אָמַר נָכוֹן אֶת סוֹף הַבְּרָכָה","יָצָא בְּדִיעֲבַד, וּבַפַּעַם הַבָּאָה יַקְפִּיד יוֹתֵר"],1,"בְּכָל בְּרָכָה צָרִיךְ שֵׁם וּמַלְכוּת: \"ה׳ אֱלֹהֵינוּ\" וְ\"מֶלֶךְ הָעוֹלָם\". בְּרָכָה בְּלִי מַלְכוּת אֵינָהּ בְּרָכָה, וְלָכֵן חוֹזֵר וּמְבָרֵךְ.","פֶּרֶק א׳, הֲלָכוֹת ג׳, ו׳","תּוֹדָה לַה׳ וְיָדַיִם טְהוֹרוֹת"],["אֵיתָן אֵינוֹ אוֹכֵל. אָחִיו הַקָּטָן רוֹצֶה לֶאֱכֹל עוּגִיָּה, וְעוֹד לֹא יוֹדֵעַ לְבָרֵךְ. מָה יַעֲשֶׂה אֵיתָן?",["יְבָרֵךְ בִּשְׁבִילוֹ בְּקוֹל, וְהַקָּטָן יַעֲנֶה \"אָמֵן\"","יַקְרִיא לְאַט, וְהַקָּטָן יַחֲזֹר מִלָּה בְּמִלָּה","יַשְׁאִיר אוֹתוֹ לֶאֱכֹל בְּלִי בְּרָכָה עַד שֶׁיִּלְמַד","יְבָרֵךְ בִּשְׁבִילוֹ, כְּמוֹ שֶׁמְּבָרְכִים לְחָבֵר עַל תְּפִלִּין"],1,"עַל אֹכֶל רַק מִי שֶׁנֶּהֱנֶה מְבָרֵךְ. אֵיתָן אֵינוֹ אוֹכֵל, וְלָכֵן לֹא יְבָרֵךְ בִּשְׁבִיל אָחִיו – אֲבָל יָכוֹל לְהַקְרִיא לוֹ לְאַט. בְּבִרְכַּת מִצְוָה, כְּמוֹ תְּפִלִּין, הַדִּין שׁוֹנֶה.","פֶּרֶק א׳, הֲלָכָה י׳","תּוֹדָה לַה׳ וְיָדַיִם טְהוֹרוֹת"],["אֵלִי מַאֲכִיל אֶת אָחִיו הַתִּינוֹק בְּפֵרוּרֵי לֶחֶם, וְהוּא עַצְמוֹ לֹא אוֹכֵל. הַאִם אֵלִי צָרִיךְ לִטֹּל יָדַיִם?",["כֵּן, כִּי הוּא נוֹגֵעַ בַּלֶּחֶם בְּיָדָיו","כֵּן, אֲבָל בְּלִי בְּרָכָה, כִּי אֵינוֹ אוֹכֵל","לֹא, הַנְּטִילָה הִיא רַק לְמִי שֶׁאוֹכֵל","רַק אִם יָדָיו מְלֻכְלָכוֹת מִמִּשְׂחָק בַּחוּץ"],2,"הַנְּטִילָה נוֹעֲדָה לְטַהֵר וּלְקַדֵּשׁ אֶת מִי שֶׁעוֹמֵד לֶאֱכֹל בְּעַצְמוֹ. מִי שֶׁרַק מַאֲכִיל אַחֵר אֵינוֹ צָרִיךְ לִטֹּל, גַּם אִם הוּא נוֹגֵעַ בַּלֶּחֶם.","פֶּרֶק ב׳, הֲלָכָה ב׳","תּוֹדָה לַה׳ וְיָדַיִם טְהוֹרוֹת"],["לְיוֹסֵף יֵשׁ פְּלַסְטֶר עַל פֶּצַע בָּאֶצְבַּע, וְכוֹאֵב לוֹ לְהוֹרִיד אוֹתוֹ. אֵיךְ יִטֹּל יָדַיִם לִפְנֵי הַסְּעוּדָה?",["יוֹרִיד אֶת הַפְּלַסְטֶר בְּכָל זֹאת, כִּי הוּא חוֹצֵץ","יִטֹּל אֶת שְׁאָר הַיָּד, וְזֶה מַסְפִּיק","לֹא יִטֹּל כְּלָל, וְיֹאכַל אֶת הַלֶּחֶם בְּמַזְלֵג","יִטֹּל רַק אֶת הַיָּד הַשְּׁנִיָּה, הַבְּרִיאָה"],1,"כְּשֶׁהוֹרָדַת הַתַּחְבֹּשֶׁת כּוֹאֶבֶת אוֹ מַזִּיקָה לַפֶּצַע, נוֹטְלִים אֶת שְׁאָר הַיָּד וְיוֹצְאִים יְדֵי חוֹבָה. כְּדַאי לִשְׁפֹּךְ אָז רְבִיעִית בְּבַת אַחַת.","פֶּרֶק ב׳, הֲלָכָה י׳","תּוֹדָה לַה׳ וְיָדַיִם טְהוֹרוֹת"],["יוֹסֵף נָטַל אֶת שְׁתֵּי יָדָיו וְנִגֵּב אוֹתָן. אָחִיו, שֶׁעוֹד לֹא נָטַל, לָחַץ לוֹ אֶת הַיָּד. מָה עַל יוֹסֵף לַעֲשׂוֹת?",["יְנַגֵּב שׁוּב וְיִטֹּל אֶת שְׁתֵּי הַיָּדַיִם מֵהַתְחָלָה","יִטֹּל שׁוּב רַק אֶת הַיָּד שֶׁאָחִיו נָגַע בָּהּ","יִטֹּל שׁוּב בְּלִי בְּרָכָה, כְּדֵי לִהְיוֹת זָהִיר","כְּלוּם, כִּי אַחֲרֵי הַנִּגּוּב הַיָּדַיִם נִשְׁאָרוֹת טְהוֹרוֹת"],3,"הַזְּהִירוּת מִנְּגִיעָה הִיא רַק בִּזְמַן הַנְּטִילָה. אַחֲרֵי הַנִּגּוּב הַטָּהֳרָה נִגְמְרָה, וְגַם נְגִיעָה שֶׁל מִי שֶׁלֹּא נָטַל אֵינָהּ מְקַלְקֶלֶת.","פֶּרֶק ב׳, הֲלָכָה י״ב","תּוֹדָה לַה׳ וְיָדַיִם טְהוֹרוֹת"],["בֵּין נִגּוּב הַיָּדַיִם לְבִרְכַּת \"הַמּוֹצִיא\" שָׁאַל אוֹתוֹ אָחִיו מָה קָרָה בַּמִּשְׂחָק. מָה נָכוֹן לַעֲשׂוֹת?",["לַעֲנוֹת, כִּי הַבְּרָכָה עַל הַנְּטִילָה כְּבָר נֶאֶמְרָה","לַעֲנוֹת בְּלַחַשׁ וּבְקִצּוּר, וְאָז זֶה לֹא הֶפְסֵק","לְחַכּוֹת, וּלְסַפֵּר רַק אַחֲרֵי שֶׁטָּעַם מִן הַלֶּחֶם","לַעֲנוֹת, וְאַחַר כָּךְ לִטֹּל אֶת הַיָּדַיִם שׁוּב"],2,"בֵּין הַנִּגּוּב לְ\"הַמּוֹצִיא\" לֹא מַפְסִיקִים בְּדִבּוּר, חוּץ מִצָּרְכֵי הַסְּעוּדָה וַעֲנִיַּת \"אָמֵן\". אַחֲרֵי שֶׁטּוֹעֲמִים מִן הַלֶּחֶם – אֶפְשָׁר לְסַפֵּר הַכֹּל.","פֶּרֶק ב׳, הֲלָכָה י״ד","תּוֹדָה לַה׳ וְיָדַיִם טְהוֹרוֹת"],["שִׁירָה רוֹצָה לְבָרֵךְ עַל תַּפּוּחַ, וְרֹאשָׁהּ אֵינוֹ מְכֻסֶּה. מָה הַדִּין?",["תְּכַסֶּה אֶת רֹאשָׁהּ קֹדֶם, כְּמוֹ שֶׁעוֹשִׂים הַגְּבָרִים","תְּבָרֵךְ כָּךְ, כִּי נָשִׁים וּבָנוֹת אֵינָן חַיָּבוֹת לְכַסּוֹת","לֹא תְּבָרֵךְ בְּקוֹל, אֶלָּא רַק תְּהַרְהֵר בַּבְּרָכָה","תְּבַקֵּשׁ מֵאָחִיהָ שֶׁיְּבָרֵךְ בִּשְׁבִילָהּ, וְהִיא תַּעֲנֶה אַחֲרָיו אָמֵן"],1,"גְּבָרִים מְכַסִּים אֶת הָרֹאשׁ בִּזְמַן בְּרָכָה, אֲבָל נָשִׁים וּבָנוֹת אֵינָן חַיָּבוֹת בְּכָךְ – וְשִׁירָה מְבָרֶכֶת כָּרָגִיל. מַחְשָׁבָה בִּלְבַד אֵינָהּ בְּרָכָה, וְעַל אֹכֶל רַק מִי שֶׁאוֹכֵל מְבָרֵךְ.","פֶּרֶק א׳, הֲלָכָה ז׳","תּוֹדָה לַה׳ וְיָדַיִם טְהוֹרוֹת"],["לְרִבְקָה יֵשׁ לַק עַל הַצִּפָּרְנַיִם, וְהוּא הִתְחִיל לְהִתְקַלֵּף. הִיא מַקְפִּידָה שֶׁלֹּא לָלֶכֶת כָּךְ. מָה תַּעֲשֶׂה לִפְנֵי נְטִילַת יָדַיִם לַסְּעוּדָה?",["תִּטֹּל כָּרָגִיל, כִּי לַק לְעוֹלָם אֵינוֹ חוֹצֵץ","תָּסִיר אֶת הַלַּק הַמִּתְקַלֵּף, וְרַק אַחַר כָּךְ תִּטֹּל","תִּטֹּל רַק אֶת כַּף הַיָּד, בְּלִי הָאֶצְבָּעוֹת","תִּטֹּל בְּלִי בְּרָכָה, כִּי יֵשׁ סָפֵק בַּנְּטִילָה שֶׁלָּהּ"],1,"לַק שֶׁרוֹצִים בּוֹ אֵינוֹ חוֹצֵץ, כִּי הוּא כְּמוֹ חֵלֶק מִן הַיָּד. אֲבָל לַק מִתְקַלֵּף, שֶׁמַּקְפִּידִים שֶׁלֹּא לָלֶכֶת בּוֹ – חוֹצֵץ בֵּין הַמַּיִם לַיָּד, וּמְסִירִים אוֹתוֹ לִפְנֵי הַנְּטִילָה.","פֶּרֶק ב׳, הֲלָכָה י׳","תּוֹדָה לַה׳ וְיָדַיִם טְהוֹרוֹת"],["לִפְנֵי אֲרוּחַת הָעֶרֶב מַרְגִּישׁ אוּרִי שֶׁהוּא צָרִיךְ מְאוֹד לְבֵית הַכִּסֵּא, וְלֹא יוּכַל לְהִתְאַפֵּק עוֹד שָׁעָה. מָה יַעֲשֶׂה?",["יְבָרֵךְ מַהֵר עַל הָאֹכֶל, וְאַחַר כָּךְ יֵלֵךְ לְבֵית הַכִּסֵּא","יֵלֵךְ קֹדֶם לְבֵית הַכִּסֵּא, יִרְחַץ יָדַיִם וְאָז יְבָרֵךְ","יְהַרְהֵר אֶת הַבְּרָכָה בַּלֵּב בִּמְקוֹם לוֹמַר אוֹתָהּ בַּפֶּה","יֹאכַל בְּלִי בְּרָכָה, כִּי אָסוּר לוֹ לְבָרֵךְ עַכְשָׁו"],1,"מִי שֶׁאֵינוֹ יָכוֹל לְהִתְאַפֵּק שִׁבְעִים וּשְׁתַּיִם דַּקּוֹת – אָסוּר לוֹ לְבָרֵךְ. לָכֵן הוֹלֵךְ קֹדֶם, רוֹחֵץ יָדַיִם, וְאַחַר כָּךְ מְבָרֵךְ וְאוֹכֵל. וּמִי שֶׁיָּכוֹל לְהִתְאַפֵּק יוֹתֵר – רַשַּׁאי לְבָרֵךְ.","פֶּרֶק א׳, הֲלָכָה ח׳","תּוֹדָה לַה׳ וְיָדַיִם טְהוֹרוֹת"],["בְּטִיּוּל נִשְׁאֲרוּ בַּבַּקְבּוּק שֶׁל נָתָן מְעַט מַיִם, וְהוּא רוֹצֶה לֶאֱכֹל כָּרִיךְ. אֵיךְ יִטֹּל יָדַיִם?",["יִשְׁפֹּךְ אֶת הַמַּיִם עַל הָאֶצְבָּעוֹת בִּלְבַד, וִיבָרֵךְ","יִשְׁפֹּךְ עַל יָד אַחַת בִּלְבַד, כְּדֵי שֶׁיַּסְפִּיק","יִטֹּל אֶת הָאֶצְבָּעוֹת, אֲבָל לֹא יְבָרֵךְ עַל הַנְּטִילָה","יֹאכַל בְּלִי נְטִילָה, כִּי הַמַּיִם אֵינָם מַסְפִּיקִים לְכַף הַיָּד"],0,"בִּשְׁעַת הַדְּחָק סוֹמְכִים עַל הַפּוֹסְקִים שֶׁמַּסְפִּיק לִטֹּל אֶת הָאֶצְבָּעוֹת, וּמְבָרְכִים. עַל הָאֶצְבָּעוֹת כֻּלָּם מַסְכִּימִים, וְהַמַּחֲלֹקֶת הִיא רַק עַל כַּף הַיָּד.","פֶּרֶק ב׳, הֲלָכָה ג׳","תּוֹדָה לַה׳ וְיָדַיִם טְהוֹרוֹת"],["בְּטִיּוּל רָעֵב אִיתָמָר, וְאֵין לוֹ מַיִם. בְּהֶמְשֵׁךְ הַשְּׁבִיל, כִּשְׁלֹשָׁה קִילוֹמֶטְרִים לְפָנָיו, יֵשׁ בֶּרֶז. מָה יַעֲשֶׂה?",["יַעֲטֹף אֶת יָדָיו בִּכְפָפוֹת, וְיֹאכַל כָּאן אֶת הַלֶּחֶם","יַחְזֹר לַחֲנָיָה, אַף שֶׁהִיא רְחוֹקָה יוֹתֵר מִשְּׁנֵי קִילוֹמֶטְרִים","יַמְשִׁיךְ בַּדֶּרֶךְ, וּלְיַד הַבֶּרֶז יִטֹּל יָדַיִם וְיֹאכַל","יֹאכַל אֶת הַלֶּחֶם בְּמַזְלֵג, כִּי אֵין מַיִם עַל יָדוֹ"],2,"מַיִם שֶׁנִּמְצָאִים לְפָנָיו, בְּמֶרְחָק שֶׁל פָּחוֹת מִכְּאַרְבָּעָה קִילוֹמֶטְרִים – מַמְשִׁיךְ אֲלֵיהֶם וְנוֹטֵל שָׁם. רַק אִם הֵם רְחוֹקִים יוֹתֵר, וְהוּא רָעֵב – עוֹטֵף אֶת יָדָיו וְאוֹכֵל.","פֶּרֶק ב׳, הֲלָכָה י״ז","תּוֹדָה לַה׳ וְיָדַיִם טְהוֹרוֹת"],["בְּאֶמְצַע סְעוּדַת שַׁבָּת יָצָא יְהוֹנָתָן לְבֵית הַכִּסֵּא לְצֹרֶךְ גָּדוֹל, וְהוּא רוֹצֶה לֶאֱכֹל עוֹד חַלָּה. מָה הַסֵּדֶר?",["יְבָרֵךְ ״אֲשֶׁר יָצַר״, וְאַחַר כָּךְ יִטֹּל בְּלִי בְּרָכָה","יִטֹּל, יְבָרֵךְ ״עַל נְטִילַת יָדַיִם״, וְאַחֲרֵי הַנִּגּוּב ״אֲשֶׁר יָצַר״","יִרְחַץ יָדַיִם בַּכִּיּוֹר, וְיַחְזֹר לֶאֱכֹל בְּלִי שׁוּם בְּרָכָה","יִטֹּל בְּלִי בְּרָכָה, וְיִדְחֶה אֶת ״אֲשֶׁר יָצַר״ לְסוֹף הַסְּעוּדָה"],1,"מִי שֶׁהָלַךְ לְצֹרֶךְ גָּדוֹל וְרוֹצֶה לֶאֱכֹל עוֹד לֶחֶם כַּבֵּיצָה – נוֹטֵל בִּבְרָכָה, כְּדַעַת רֹב הַפּוֹסְקִים. מְבָרֵךְ ״עַל נְטִילַת יָדַיִם״ מִיָּד אַחֲרֵי הַנְּטִילָה, וְאַחֲרֵי הַנִּגּוּב – ״אֲשֶׁר יָצַר״.","פֶּרֶק ב׳, הֲלָכָה ט״ז","תּוֹדָה לַה׳ וְיָדַיִם טְהוֹרוֹת"],["שְׁמוּאֵל בֵּרֵךְ \"הַמּוֹצִיא\", וְלִפְנֵי שֶׁטָּעַם אָמַר לְאָחִיו: \"תַּעֲבִיר לִי אֶת הַמֶּלַח\". מָה הַדִּין?",["מְבָרֵךְ שׁוּב, כִּי כָּל מִלָּה הִיא הֶפְסֵק","אֵינוֹ חוֹזֵר לְבָרֵךְ, כִּי דִּבֵּר עַל צֹרֶךְ הָאֲכִילָה","נוֹטֵל יָדַיִם שׁוּב וּמְבָרֵךְ \"הַמּוֹצִיא\" מֵחָדָשׁ","מְבָרֵךְ שׁוּב, אֲבָל בְּלִי לִטֹּל יָדַיִם שׁוּב"],1,"דִּבּוּר בֵּין הַבְּרָכָה לָאֲכִילָה מַפְסִיק – אֲבָל דִּבּוּר עַל צָרְכֵי הָאֲכִילָה, כְּמוֹ מֶלַח אוֹ סַכִּין, אֵינוֹ הֶפְסֵק. בְּכָל זֹאת, לְכַתְּחִלָּה טוֹעֲמִים קֹדֶם וּמְדַבְּרִים אַחַר כָּךְ.","פֶּרֶק ג׳, הֲלָכָה ג׳","הַמּוֹצִיא לֶחֶם מִן הָאָרֶץ"],["בְּיוֹם חֹל מַתְחִילִים לַחְתֹּךְ לֶחֶם גָּדוֹל לִפְנֵי הַבְּרָכָה. לָמָּה בְּשַׁבָּת לֹא חוֹתְכִים אֶת הַחַלָּה לִפְנֵי הַבְּרָכָה?",["כִּי בְּשַׁבָּת אָסוּר לְהִשְׁתַּמֵּשׁ בְּסַכִּין לַחֲתִיכַת לֶחֶם","כִּי הַחַלָּה רַכָּה, וְקַל לִפְרֹס אוֹתָהּ מַהֵר","כִּי בְּשַׁבָּת מְבָרְכִים עַל שְׁתֵּי חַלּוֹת שְׁלֵמוֹת","כִּי בְּשַׁבָּת אֵין צֹרֶךְ לְמַהֵר לֶאֱכֹל אַחֲרֵי הַבְּרָכָה"],2,"בְּשַׁבָּת מִצְוָה לְבָרֵךְ עַל שְׁתֵּי חַלּוֹת שְׁלֵמוֹת. מִי שֶׁמַּתְחִיל לַחְתֹּךְ – הַחַלָּה כְּבָר לֹא שְׁלֵמָה. (לַחְמָנִיָּה וּפִתָּה מְבָרְכִים שְׁלֵמוֹת מִסִּבָּה אַחֶרֶת: קַל לִבְצֹעַ אוֹתָן מַהֵר.)","פֶּרֶק ג׳, הֲלָכָה ג׳","הַמּוֹצִיא לֶחֶם מִן הָאָרֶץ"],["בִּסְעוּדַת בַּר מִצְוָה גְּדוֹלָה נָטְלוּ אוֹרְחִים רַבִּים יָדַיִם. אֵיךְ עָדִיף לְבָרֵךְ \"הַמּוֹצִיא\"?",["יְחַכּוּ שֶׁכָּל הָאוֹרְחִים יִגְמְרוּ, וְאֶחָד יְבָרֵךְ לְכֻלָּם","בְּכָל שֻׁלְחָן יְבָרֵךְ אֶחָד לְמִי שֶׁנָּטְלוּ אִתּוֹ","כָּל אוֹרֵחַ יְבָרֵךְ לְעַצְמוֹ, וְלֹא יְחַכֶּה לְאַף אֶחָד","חֲתַן הַבַּר מִצְוָה יְבָרֵךְ לְכֻלָּם בְּמִיקְרוֹפוֹן"],1,"כְּשֶׁאוֹכְלִים יַחַד, טוֹב שֶׁאֶחָד יְבָרֵךְ לָאֲחֵרִים. אֲבָל בִּסְעוּדָה גְּדוֹלָה הַהַמְתָּנָה לְכֻלָּם תִּגְרֹם הֶפְסֵק אָרֹךְ מִדַּי בֵּין הַנְּטִילָה לַבְּרָכָה – וְלָכֵן מְבָרְכִים בְּכָל שֻׁלְחָן.","פֶּרֶק ג׳, הֲלָכָה ד׳","הַמּוֹצִיא לֶחֶם מִן הָאָרֶץ"],["בִּתְחִלַּת הַסְּעוּדָה, אַחֲרֵי \"הַמּוֹצִיא\", הִגִּישׁוּ חֲתִיכוֹת מֶלוֹן. מָה עוֹשִׂים?",["לֹא מְבָרְכִים, כִּי \"הַמּוֹצִיא\" פּוֹטֵר אֶת כָּל הַסְּעוּדָה","מְבָרְכִים לְפָנָיו, כִּי הוּא בָּא לְטַעַם וְלֹא לִשְׂבִיעָה","לֹא מְבָרְכִים, כִּי רַק קִנּוּחַ שֶׁבַּסּוֹף צָרִיךְ בְּרָכָה","מְבָרְכִים לְפָנָיו, וְגַם \"בּוֹרֵא נְפָשׁוֹת\" אַחֲרָיו"],1,"מֶלוֹן בִּתְחִלַּת הַסְּעוּדָה הוּא כְּמוֹ קִנּוּחַ שֶׁפּוֹתֵחַ בְּטַעַם טוֹב, וְאֵינוֹ חֵלֶק מֵהַשְּׂבִיעָה – לָכֵן מְבָרְכִים עָלָיו \"בּוֹרֵא פְּרִי הָאֲדָמָה\". בְּרָכָה אַחֲרוֹנָה לֹא צָרִיךְ: בִּרְכַּת הַמָּזוֹן פּוֹטֶרֶת.","פֶּרֶק ג׳, הֲלָכוֹת ו׳–ז׳","הַמּוֹצִיא לֶחֶם מִן הָאָרֶץ"],["בְּאֶמְצַע הַסְּעוּדָה בָּאוּ חֲבֵרִים וְהֵבִיאוּ סִיר קוּגֶל, שֶׁלֹּא חָשַׁבְתָּ עָלָיו בִּשְׁעַת \"הַמּוֹצִיא\". מָה עוֹשִׂים?",["לֹא מְבָרְכִים, כִּי \"הַמּוֹצִיא\" פּוֹטֵר כָּל מַאֲכַל סְעוּדָה","מְבָרְכִים עָלָיו, כִּי לֹא הִתְכַּוַּנְתָּ אֵלָיו בַּבְּרָכָה","נוֹטְלִים יָדַיִם שׁוּב וּמְבָרְכִים \"הַמּוֹצִיא\" מֵחָדָשׁ","מְבָרְכִים עָלָיו רַק אִם הַסְּעוּדָה נִמְשְׁכָה שָׁעוֹת"],1,"\"הַמּוֹצִיא\" פּוֹטֵר אֶת מָה שֶׁהִתְכַּוַּנְתָּ לֶאֱכֹל – אֲפִלּוּ בִּסְעוּדָה אֲרֻכָּה מְאוֹד. מַאֲכָל שֶׁהִגִּיעַ פִּתְאֹם וְלֹא חָשַׁבְתָּ עָלָיו – צָרִיךְ בְּרָכָה מִשֶּׁלּוֹ.","פֶּרֶק ג׳, הֲלָכָה י׳","הַמּוֹצִיא לֶחֶם מִן הָאָרֶץ"],["דָּוִד רָעֵב, וְהַסְּעוּדָה עִם הַלֶּחֶם תַּתְחִיל בְּעוֹד כַּמָּה דַּקּוֹת. לָמָּה עָדִיף שֶׁלֹּא יִטְעַם עַכְשָׁו מֵהַסָּלָט?",["כִּי אָסוּר לֶאֱכֹל שׁוּם דָּבָר לִפְנֵי נְטִילַת יָדַיִם","כִּי יְבָרֵךְ בְּלִי צֹרֶךְ, וְיִסְתַּפֵּק בַּבְּרָכָה הָאַחֲרוֹנָה","כִּי סָלָט לִפְנֵי הָאֹכֶל מְקַלְקֵל אֶת הַתֵּאָבוֹן","כִּי אַחֲרֵי הַסָּלָט לֹא יוּכַל לְבָרֵךְ \"הַמּוֹצִיא\""],1,"אֶת הַסָּלָט הָיָה \"הַמּוֹצִיא\" פּוֹטֵר. מִי שֶׁאוֹכֵל לִפְנֵי הַסְּעוּדָה גּוֹרֵם לִבְרָכָה שֶׁאֵינָהּ צְרִיכָה, וְגַם לֹא יֵדַע אִם לְבָרֵךְ אַחֲרֶיהָ בְּרָכָה אַחֲרוֹנָה.","פֶּרֶק ג׳, הֲלָכָה י״ב","הַמּוֹצִיא לֶחֶם מִן הָאָרֶץ"],["בְּסוֹף סְעוּדַת שַׁבָּת הִגִּישׁוּ עוּגָה. נֹעַם עוֹד לֹא הֶחְלִיט אִם אֵצְלוֹ עוּגָה הִיא חֵלֶק מֵהַסְּעוּדָה אוֹ קִנּוּחַ. מָה יַעֲשֶׂה?",["יְבָרֵךְ \"מְזוֹנוֹת\", כִּי עַל עוּגָה תָּמִיד מְבָרְכִים","לֹא יְבָרֵךְ \"מְזוֹנוֹת\", כִּי יֵשׁ כָּאן סָפֵק","יִטֹּל יָדַיִם שׁוּב וִיבָרֵךְ \"הַמּוֹצִיא\" עַל הָעוּגָה","יְבָרֵךְ \"מְזוֹנוֹת\" לְפָנֶיהָ, וְ\"עַל הַמִּחְיָה\" אַחֲרֶיהָ"],1,"יֵשׁ אוֹמְרִים שֶׁעוּגָה בַּסְּעוּדָה נִפְטֶרֶת בְּ\"הַמּוֹצִיא\", וְיֵשׁ אוֹמְרִים שֶׁמְּבָרְכִים עָלֶיהָ \"מְזוֹנוֹת\". מִי שֶׁלֹּא הֶחְלִיט – לֹא מְבָרֵךְ, כִּי סְפֵק בְּרָכוֹת לְהָקֵל. וְהָרוֹצִים לְהַדֵּר – לֹא אוֹכְלִים מְזוֹנוֹת בַּסְּעוּדָה.","פֶּרֶק ג׳, הֲלָכָה ח׳","הַמּוֹצִיא לֶחֶם מִן הָאָרֶץ"],["בַּחֲנֻכָּה, בְּסוֹף הַסְּעוּדָה וְלִפְנֵי בִּרְכַּת הַמָּזוֹן, הִגִּישׁוּ סֻפְגָּנִיּוֹת. מָה הַדִּין?",["מְבָרְכִים \"מְזוֹנוֹת\", כְּמוֹ עַל בִּיסְלִי שֶׁמַּגִּישִׁים לְקִנּוּחַ","לֹא מְבָרְכִים, וְעָדִיף לֶאֱכֹל אוֹתָן אַחֲרֵי בִּרְכַּת הַמָּזוֹן","נוֹטְלִים יָדַיִם וּמְבָרְכִים עֲלֵיהֶן \"הַמּוֹצִיא\" מֵחָדָשׁ","מְבָרְכִים \"מְזוֹנוֹת\" לִפְנֵיהֶן, וְ\"עַל הַמִּחְיָה\" אַחֲרֵיהֶן"],1,"בִּיסְלִי שׁוֹנֶה מְאוֹד מִלֶּחֶם, וּמְבָרְכִים עָלָיו \"מְזוֹנוֹת\" גַּם בַּסְּעוּדָה. אֲבָל בְּצֵק הַסֻּפְגָּנִיּוֹת דּוֹמֶה לְלֶחֶם, וְהֵן מַשְׂבִּיעוֹת – וְיֵשׁ סוֹבְרִים שֶׁ\"הַמּוֹצִיא\" פּוֹטֶרֶת אוֹתָן. לָכֵן לֹא מְבָרְכִים עֲלֵיהֶן בַּסְּעוּדָה, וּלְכַתְּחִלָּה עָדִיף לֶאֱכֹל אוֹתָן מִחוּץ לַסְּעוּדָה.","פֶּרֶק ג׳, הֲלָכָה ח׳","הַמּוֹצִיא לֶחֶם מִן הָאָרֶץ"],["בַּסְּעוּדָה הַשְּׁלִישִׁית שֶׁל שַׁבָּת שָׁכַח יוֹנָתָן לוֹמַר \"רְצֵה\", וְנִזְכַּר רַק אַחֲרֵי שֶׁסִּיֵּם אֶת כָּל בִּרְכַּת הַמָּזוֹן. מָה הַדִּין?",["חוֹזֵר וּמְבָרֵךְ שׁוּב מֵהַהַתְחָלָה אֶת כָּל בִּרְכַּת הַמָּזוֹן","אֵינוֹ חוֹזֵר, כִּי סְעוּדָה זוֹ אֶפְשָׁר בְּלִי לֶחֶם","חוֹזֵר רַק לְבִרְכַּת \"הַזָּן\" וּמַמְשִׁיךְ מִשָּׁם","חוֹזֵר לַבְּרָכָה הַשְּׁלִישִׁית וְאוֹמֵר אוֹתָהּ שׁוּב"],1,"אֶת הַסְּעוּדָה הַשְּׁלִישִׁית אֶפְשָׁר בְּדִיעֲבַד לֶאֱכֹל בְּלִי לֶחֶם, וְלָכֵן אֵין חוֹבָה לַחֲזֹר. אֲבָל מִי שֶׁשָּׁכַח \"רְצֵה\" בִּשְׁתֵּי הַסְּעוּדוֹת הָרִאשׁוֹנוֹת – חוֹזֵר לִתְחִלַּת בִּרְכַּת הַמָּזוֹן.","פֶּרֶק ד׳, הֲלָכָה ח׳","אָכַלְנוּ, שָׂבַעְנוּ – וּמְבָרְכִים"],["רְאוּבֵן אָכַל אֲרוּחַת צָהֳרַיִם גְּדוֹלָה וְשָׂבַע. אַחֲרֵי זְמַן קָצָר הוּא אֵינוֹ זוֹכֵר אִם בֵּרַךְ. מָה יַעֲשֶׂה?",["לֹא יְבָרֵךְ, כִּי בְּסָפֵק אַף פַּעַם לֹא מְבָרְכִים","יְבָרֵךְ רַק אֶת הַבְּרָכָה הָרִאשׁוֹנָה, בִּגְלַל הַסָּפֵק","יְבָרֵךְ, כִּי כְּשֶׁשָּׂבְעוּ הַבְּרָכָה הִיא מִן הַתּוֹרָה","יְבָרֵךְ רַק אִם עֲדַיִן לֹא עָבְרָה שָׁעָה"],2,"מִי שֶׁשָּׂבַע חַיָּב לְבָרֵךְ מִן הַתּוֹרָה, וּבְסָפֵק שֶׁל מִצְוָה מִן הַתּוֹרָה מַחְמִירִים וּמְבָרְכִים. רַק מִי שֶׁלֹּא שָׂבַע – שֶׁחִיּוּבוֹ מִדִּבְרֵי חֲכָמִים – לֹא יְבָרֵךְ בְּסָפֵק.","פֶּרֶק ד׳, הֲלָכָה ו׳","אָכַלְנוּ, שָׂבַעְנוּ – וּמְבָרְכִים"],["שְׁלוֹשָׁה חֲבֵרִים אָכְלוּ לֶחֶם יַחַד. שְׁנַיִם סִיְּמוּ וְרוֹצִים לְזַמֵּן, וְהַשְּׁלִישִׁי עוֹד אוֹכֵל. מָה הַדִּין?",["הַשְּׁנַיִם מְחַכִּים עַד שֶׁהַשְּׁלִישִׁי יְסַיֵּם אֶת אֲרוּחָתוֹ","כָּל אֶחָד מְבָרֵךְ לְבַד, כִּי לֹא סִיְּמוּ יַחַד","הַשְּׁנַיִם מְזַמְּנִים לְבַד, בְּלִי הֶחָבֵר הַשְּׁלִישִׁי","הַשְּׁלִישִׁי עוֹצֵר, עוֹנֶה לַזִּמּוּן וּמַמְשִׁיךְ לֶאֱכֹל"],3,"הוֹלְכִים אַחַר הָרֹב. הַשְּׁלִישִׁי מַפְסִיק, עוֹנֶה לַזִּמּוּן, אַחַר כָּךְ מַמְשִׁיךְ לֶאֱכֹל, וּבַסּוֹף מְבָרֵךְ לְעַצְמוֹ. שְׁנַיִם לְבַד אֵינָם יְכוֹלִים לְזַמֵּן.","פֶּרֶק ה׳, הֲלָכָה ג׳","אָכַלְנוּ, שָׂבַעְנוּ – וּמְבָרְכִים"],["בִּסְעוּדָה גְּדוֹלָה שִׁבְעָה אָכְלוּ לֶחֶם, וּשְׁלוֹשָׁה אָכְלוּ רַק פֵּרוֹת וְשָׁתוּ מִיץ. אֵיךְ מְזַמְּנִים?",["מְזַמְּנִים בַּעֲשָׂרָה, וְהַמְּזַמֵּן הוּא מֵאוֹכְלֵי הַלֶּחֶם","מְזַמְּנִים בְּלִי \"אֱלֹהֵינוּ\", כִּי רַק שִׁבְעָה אָכְלוּ לֶחֶם","מְזַמְּנִים בַּעֲשָׂרָה, וְאֶחָד מֵאוֹכְלֵי הַפֵּרוֹת מְזַמֵּן","כָּל אֶחָד מְבָרֵךְ לְבַד, כִּי לֹא אָכְלוּ אוֹתוֹ מַאֲכָל"],0,"כְּשֶׁרֹב נִכָּר – שִׁבְעָה – אָכְלוּ לֶחֶם, גַּם מִי שֶׁאָכַל כְּזַיִת פֵּרוֹת אוֹ שָׁתָה מַשְׁקֶה מִצְטָרֵף לָעֲשָׂרָה, וּמַזְכִּירִים אֶת הַשֵּׁם. אֲבָל הַמְּזַמֵּן צָרִיךְ לִהְיוֹת מִמִּי שֶׁאָכַל לֶחֶם.","פֶּרֶק ה׳, הֲלָכָה י׳","אָכַלְנוּ, שָׂבַעְנוּ – וּמְבָרְכִים"],["בִּסְעוּדַת שַׁבָּת יוֹשְׁבִים אַבָּא וּשְׁנֵי בָּנִים גְּדוֹלִים אַחֲרֵי בַּר מִצְוָה, וְגַם אִמָּא וְהָאֲחָיוֹת. אַבָּא מְזַמֵּן. מִי עוֹנֶה?",["רַק שְׁלוֹשֶׁת הַגְּבָרִים, כִּי הֵם יָצְרוּ אֶת הַזִּמּוּן","כָּל מִי שֶׁאָכַל בַּסְּעוּדָה, גַּם אִמָּא וְהָאֲחָיוֹת","רַק הַבָּנִים, כִּי הַמְּזַמֵּן עַצְמוֹ אֵינוֹ עוֹנֶה","רַק אַבָּא וְאִמָּא, וְהַיְּלָדִים מְבָרְכִים לְעַצְמָם"],1,"כְּשֶׁשְּׁלוֹשָׁה גְּבָרִים יוֹצְרִים חוֹבַת זִמּוּן, גַּם הַנָּשִׁים וְהַבָּנוֹת שֶׁאָכְלוּ חַיָּבוֹת לַעֲנוֹת. צָרִיךְ לְהִתְחַזֵּק בָּזֶה, כִּי הַרְבֵּה פְּעָמִים שׁוֹכְחִים.","פֶּרֶק ה׳, הֲלָכָה ז׳","אָכַלְנוּ, שָׂבַעְנוּ – וּמְבָרְכִים"],["דָּוִד נִכְנַס לַחֶדֶר בְּדִיּוּק כְּשֶׁהַמְּזַמֵּן אָמַר \"נְבָרֵךְ שֶׁאָכַלְנוּ מִשֶּׁלּוֹ\". דָּוִד לֹא אָכַל אִתָּם. מָה יַעֲשֶׂה?",["יַעֲנֶה \"בָּרוּךְ שֶׁאָכַלְנוּ מִשֶּׁלּוֹ וּבְטוּבוֹ חָיִינוּ\" כְּמוֹ כֻּלָּם","יִשְׁתֹּק, כִּי מִי שֶׁלֹּא אָכַל אֵינוֹ שַׁיָּךְ לַזִּמּוּן","יַעֲנֶה \"בָּרוּךְ וּמְבֹרָךְ שְׁמוֹ תָּמִיד לְעוֹלָם וָעֶד\"","יֵצֵא מֵהַחֶדֶר עַד שֶׁיְּסַיְּמוּ אֶת בִּרְכַּת הַמָּזוֹן"],2,"לֹא רָאוּי לַעֲמֹד מִן הַצַּד כְּשֶׁחֲבֵרִים מְשַׁבְּחִים אֶת ה׳. מִי שֶׁלֹּא אָכַל אֵינוֹ יָכוֹל לוֹמַר \"שֶׁאָכַלְנוּ\", וְלָכֵן עוֹנֶה \"בָּרוּךְ וּמְבֹרָךְ שְׁמוֹ תָּמִיד לְעוֹלָם וָעֶד\".","פֶּרֶק ה׳, הֲלָכָה ה׳","אָכַלְנוּ, שָׂבַעְנוּ – וּמְבָרְכִים"],["שָׁלֹשׁ חֲבֵרוֹת אָכְלוּ יַחַד לֶחֶם בִּמְסִבַּת כִּתָּה. מָה נָכוֹן שֶׁיַּעֲשׂוּ בְּבִרְכַּת הַמָּזוֹן?",["כָּל אַחַת תְּבָרֵךְ לְבַד, כִּי לְבָנוֹת אֵין זִמּוּן כְּלָל","מִצְוָה שֶׁיְּזַמְּנוּ יַחַד, אַף שֶׁאֵינָן חַיָּבוֹת בְּזִמּוּן","יְזַמְּנוּ רַק אִם יִצְטָרֵף אֲלֵיהֶן אֶחָד מִן הַבָּנִים","יְזַמְּנוּ עִם \"אֱלֹהֵינוּ\", כְּמוֹ שֶׁמְּזַמְּנִים בַּעֲשָׂרָה"],1,"חֲכָמִים לֹא חִיְּבוּ נָשִׁים לְזַמֵּן, אֲבָל כְּשֶׁשָּׁלֹשׁ אוֹכְלוֹת יַחַד – מִצְוָה שֶׁיְּזַמְּנוּ. הֵן אֵינָן מַזְכִּירוֹת \"אֱלֹהֵינוּ\", וְאֵינָן מִצְטָרְפוֹת לְזִמּוּן עִם בָּנִים, מִשּׁוּם צְנִיעוּת.","פֶּרֶק ה׳, הֲלָכָה ז׳","אָכַלְנוּ, שָׂבַעְנוּ – וּמְבָרְכִים"],["מִיכָל אָכְלָה לֶחֶם עִם אַבָּא וְעִם אָחִיהָ הַגָּדוֹל, שֶׁכְּבָר אַחֲרֵי בַּר מִצְוָה. אֵין שָׁם עוֹד אַף אֶחָד. הַאִם מְזַמְּנִים?",["כֵּן, כִּי מִיכָל מַשְׁלִימָה לִשְׁלוֹשָׁה שֶׁאָכְלוּ יַחַד","לֹא, כִּי אִשָּׁה אֵינָהּ מִצְטָרֶפֶת לִגְבָרִים בַּזִּמּוּן","כֵּן, כִּי בְּתוֹךְ הַמִּשְׁפָּחָה מֻתָּר לְצָרֵף אֶת כֻּלָּם","לֹא, כִּי צָרִיךְ לְפָחוֹת עֲשָׂרָה אֲנָשִׁים לְכָל זִמּוּן"],1,"נָשִׁים אֵינָן מִצְטָרְפוֹת לִגְבָרִים לִיצֹר חוֹבַת זִמּוּן – מִשּׁוּם צְנִיעוּת. חֲכָמִים לֹא חִלְּקוּ בֵּין קְרוֹבִים לִרְחוֹקִים, וַאֲפִלּוּ אָב עִם בִּתּוֹ אֵינָם מִצְטָרְפִים. רַק כְּשֶׁיֵּשׁ שְׁלוֹשָׁה גְּבָרִים – הַנָּשִׁים עוֹנוֹת לַזִּמּוּן.","פֶּרֶק ה׳, הֲלָכָה ז׳","אָכַלְנוּ, שָׂבַעְנוּ – וּמְבָרְכִים"],["אֲחוֹתוֹ שֶׁל אֵיתָן שׁוֹאֶלֶת: \"גַּם בָּנוֹת חַיָּבוֹת לְבָרֵךְ בִּרְכַּת הַמָּזוֹן?\" מָה הַתְּשׁוּבָה?",["לֹא, בָּנוֹת מְבָרְכוֹת רַק בְּרָכָה קְצָרָה בַּלָּשׁוֹן שֶׁהֵן מְבִינוֹת","כֵּן, נָשִׁים וּבָנוֹת חַיָּבוֹת בְּבִרְכַּת הַמָּזוֹן כְּמוֹ גְּבָרִים","רַק כְּשֶׁיֵּשׁ זִמּוּן שֶׁל שְׁלוֹשָׁה גְּבָרִים בַּסְּעוּדָה","רַק בְּשַׁבָּת וּבְחַג, וּבִימֵי חֹל זוֹ רְשׁוּת"],1,"בָּרוּר שֶׁנָּשִׁים וּבָנוֹת חַיָּבוֹת בְּבִרְכַּת הַמָּזוֹן כְּמוֹ גְּבָרִים. הַסָּפֵק הוּא רַק אִם חִיּוּבָן מִן הַתּוֹרָה אוֹ מִדִּבְרֵי חֲכָמִים – אֲבָל מִדִּבְרֵי חֲכָמִים הֵן חַיָּבוֹת בְּוַדַּאי.","פֶּרֶק ד׳, הֲלָכָה ו׳","אָכַלְנוּ, שָׂבַעְנוּ – וּמְבָרְכִים"],["אַחֲרֵי בִּרְכַּת הַמָּזוֹן גִּלָּה חַגַּי שֶׁדִּלֵּג בְּטָעוּת עַל כַּמָּה מִשְׁפָּטִים בְּאֶמְצַע הַבְּרָכָה הָרִאשׁוֹנָה, אֲבָל אָמַר אֶת פְּתִיחָתָהּ וְאֶת חֲתִימָתָהּ. מָה הַדִּין?",["יָצָא, כִּי אָמַר אֶת הַיְּסוֹדוֹת שֶׁל הַבְּרָכָה","לֹא יָצָא, וְצָרִיךְ לַחֲזֹר וּלְבָרֵךְ אֶת כָּל בִּרְכַּת הַמָּזוֹן","יַחְזֹר רַק עַל הַבְּרָכָה הָרִאשׁוֹנָה, וְאַחַר כָּךְ יַמְשִׁיךְ","יֹאכַל שׁוּב כְּזַיִת לֶחֶם, וִיבָרֵךְ מֵחָדָשׁ"],0,"בְּדִיעֲבַד, מִי שֶׁהִשְׁמִיט קְטָעִים מִבִּרְכַּת הַמָּזוֹן – יָצָא, כָּל זְמַן שֶׁאָמַר אֶת הַיְּסוֹדוֹת. בַּבְּרָכָה הָרִאשׁוֹנָה הַיְּסוֹד הוּא לְבָרֵךְ אֶת ה׳ עַל הַמָּזוֹן, עִם שֵׁם ה׳ וּ״מֶלֶךְ הָעוֹלָם״.","פֶּרֶק ד׳, הֲלָכָה ה׳","אָכַלְנוּ, שָׂבַעְנוּ – וּמְבָרְכִים"],["אַחֲרֵי סְעוּדַת שַׁבָּת כְּבֵדָה, עִם חַמִּין וּבָשָׂר, נִרְדַּם דָּוִד בְּלִי לְבָרֵךְ. הוּא הִתְעוֹרֵר אַחֲרֵי שָׁלֹשׁ שָׁעוֹת, וְעוֹד שָׂבֵעַ. מָה יַעֲשֶׂה?",["יְבָרֵךְ עַכְשָׁו, כִּי הוּא עוֹד מַרְגִּישׁ שָׂבֵעַ מֵהַסְּעוּדָה","לֹא יְבָרֵךְ, כִּי עָבְרוּ יוֹתֵר מִשִּׁבְעִים וּשְׁתַּיִם דַּקּוֹת","יְהַרְהֵר בַּלֵּב, כִּי אַחֲרֵי שֵׁנָה הַבְּרָכָה כְּבָר אָבְדָה","יֹאכַל קֹדֶם סְעוּדָה חֲדָשָׁה, וִיבָרֵךְ עַל שְׁתֵּיהֶן יַחַד"],0,"אַחֲרֵי אֹכֶל כָּבֵד מַרְגִּישִׁים שָׂבֵעַ עַד שֵׁשׁ שָׁעוֹת, וְכָל זְמַן שֶׁהוּא שָׂבֵעַ – עוֹד אֶפְשָׁר לְבָרֵךְ. שִׁעוּר שִׁבְעִים וּשְׁתַּיִם הַדַּקּוֹת נוֹגֵעַ רַק לְמִי שֶׁאָכַל מְעַט וְלֹא שָׂבַע.","פֶּרֶק ד׳, הֲלָכָה י״ד","אָכַלְנוּ, שָׂבַעְנוּ – וּמְבָרְכִים"],["בְּסוֹף הַזִּמּוּן בֵּרַךְ הַמְזַמֵּן עַל הַכּוֹס, וְהָאוֹרְחִים רוֹצִים לִטְעֹם מִמֶּנָּה. מָה הַדֶּרֶךְ הַמְהֻדֶּרֶת בְּיוֹתֵר?",["הַמְזַמֵּן יַעֲבִיר לְכֻלָּם אֶת הַכּוֹס שֶׁשָּׁתָה מִמֶּנָּה","לִפְנֵי הַבְּרָכָה מוֹזְגִים לְכָל אוֹרֵחַ כּוֹס מִשֶּׁלּוֹ","רַק הַמְזַמֵּן שׁוֹתֶה, כִּי לָאוֹרְחִים אָסוּר לִטְעֹם","כָּל אוֹרֵחַ מְבָרֵךְ לְעַצְמוֹ עַל הַכּוֹס הַמְּשֻׁתֶּפֶת"],1,"הַדֶּרֶךְ הַמְהֻדֶּרֶת – לִמְזֹג עוֹד לִפְנֵי בִּרְכַּת הַמָּזוֹן לְכָל מִי שֶׁרוֹצֶה לִטְעֹם, וְאַחֲרֵי בִּרְכַּת הַגֶּפֶן שֶׁל הַמְזַמֵּן כֻּלָּם שׁוֹתִים מִכּוֹסָם. כָּךְ אֵין הֶפְסֵק, וְאִישׁ אֵינוֹ צָרִיךְ לִשְׁתּוֹת מִכּוֹס שֶׁל אַחֵר.","פֶּרֶק ה׳, הֲלָכָה ט״ו","אָכַלְנוּ, שָׂבַעְנוּ – וּמְבָרְכִים"],["בַּהַפְסָקָה אָכַל עֲמִיחַי בּוּרֵקַס גְּבִינָה גָּדוֹל, כְּמוֹ שֶׁאוֹכְלִים בֵּין הָאֲרוּחוֹת. מָה בֵּרַךְ לְפָנָיו?",["\"הַמּוֹצִיא\", כִּי מַאֲפֶה גָּדוֹל נוֹעָד תָּמִיד לִסְעוּדָה","\"מְזוֹנוֹת\", כִּי בְּבָצֶק הַבּוּרֵקַס יֵשׁ הַרְבֵּה שֶׁמֶן","\"הַמּוֹצִיא\", כִּי יֵשׁ בְּתוֹכוֹ גְּבִינָה, כְּמוֹ כָּרִיךְ","\"שֶׁהַכֹּל\", כִּי הַגְּבִינָה הִיא עִקַּר הַמַּאֲכָל"],1,"בְּדֶרֶךְ כְּלָל מַאֲפֶה גָּדוֹל נוֹעָד לִסְעוּדָה, אֲבָל הַבּוּרֵקַס שׁוֹנֶה: בְּבָצְקוֹ מְעָרְבִים שֶׁמֶן, וְהוּא שׁוֹנֶה מְאוֹד מִלֶּחֶם. רַק מִי שֶׁקּוֹבֵעַ עָלָיו סְעוּדָה מְבָרֵךְ \"הַמּוֹצִיא\".","פֶּרֶק ו׳, הֲלָכָה ח׳","מִן הַשָּׂדֶה וּמִן הַכֶּרֶם"],["בִּמְסִבַּת בַּר מִצְוָה הִגִּישׁוּ קְרָקֶרִים וְעוּגוֹת בְּלִי לֶחֶם, יַחַד עִם בָּשָׂר וְסָלָטִים. כֻּלָּם אָכְלוּ הַרְבֵּה וְשָׂבְעוּ. מָה הַדִּין?",["מְבָרְכִים \"מְזוֹנוֹת\", כִּי אֵין עַל הַשֻּׁלְחָן אַף לֶחֶם","מְבָרְכִים \"מְזוֹנוֹת\", וּבַסּוֹף \"בּוֹרֵא נְפָשׁוֹת\" עַל הַכֹּל","\"מְזוֹנוֹת\" עַל הַקְּרָקֶרִים, וּבְרָכָה נִפְרֶדֶת עַל הַבָּשָׂר","נוֹטְלִים יָדַיִם וּמְבָרְכִים \"הַמּוֹצִיא\" וּבִרְכַּת הַמָּזוֹן"],3,"כְּשֶׁאוֹכְלִים הַרְבֵּה מִמַּאֲפֵה הַמְּזוֹנוֹת וְשׂוֹבְעִים – זוֹ קְבִיעוּת סְעוּדָה, וְהַמַּאֲפֶה נַעֲשֶׂה כְּמוֹ לֶחֶם. לָכֵן מוּטָב לְהַגִּישׁ לֶחֶם, וְכֻלָּם יִזְכּוּ לְבָרֵךְ בִּרְכַּת הַמָּזוֹן.","פֶּרֶק ו׳, הֲלָכָה ה׳","מִן הַשָּׂדֶה וּמִן הַכֶּרֶם"],["בְּיוֹם חֹל אָכַל מֵאִיר לַאֲרוּחַת עֶרֶב רַק קוּגֶל אִטְרִיּוֹת – הַרְבֵּה, עַד שֶׁשָּׂבַע. מָה יְבָרֵךְ אַחֲרָיו?",["\"עַל הַמִּחְיָה\", כִּי הָאִטְרִיּוֹת בֻּשְּׁלוּ לִפְנֵי הָאֲפִיָּה","בִּרְכַּת הַמָּזוֹן, כִּי קָבַע עַל הַקּוּגֶל סְעוּדָה","\"בּוֹרֵא נְפָשׁוֹת\", כִּי הַקּוּגֶל אֵינוֹ מַאֲפֶה אֲמִתִּי","בִּרְכַּת הַמָּזוֹן, כִּי הַקּוּגֶל נֶאֱפָה בְּתַנּוּר כְּמוֹ לֶחֶם"],0,"אִטְרִיּוֹת הֵן תַּבְשִׁיל. גַּם כְּשֶׁאוֹפִים אוֹתָן אַחַר כָּךְ לְקוּגֶל, לֹא נַעֲשֵׂית לָהֶן צוּרַת לֶחֶם. וְעַל תַּבְשִׁיל מִדָּגָן מְבָרְכִים תָּמִיד \"מְזוֹנוֹת\" וְ\"עַל הַמִּחְיָה\".","פֶּרֶק ו׳, הֲלָכָה י׳","מִן הַשָּׂדֶה וּמִן הַכֶּרֶם"],["בְּאֶמְצַע הַסְּעוּדָה, אַחֲרֵי שֶׁבֵּרַךְ \"הַמּוֹצִיא\", מָזַג יְהוֹנָתָן כּוֹס מִיץ עֲנָבִים. מָה יַעֲשֶׂה?",["שׁוֹתֶה בְּלִי בְּרָכָה, כִּי \"הַמּוֹצִיא\" פָּטְרָה אֶת כָּל הַמַּשְׁקִים","מְבָרֵךְ \"שֶׁהַכֹּל\", כְּמוֹ עַל כָּל מִיץ פֵּרוֹת","מְבָרֵךְ \"הַגֶּפֶן\", כִּי \"הַמּוֹצִיא\" אֵינָהּ פּוֹטֶרֶת אוֹתוֹ","מְבָרֵךְ \"הַגֶּפֶן\" לְפָנָיו, וְ\"עַל הַגֶּפֶן\" אַחֲרָיו"],2,"יַיִן וּמִיץ עֲנָבִים חֲשׁוּבִים, וְאֵינָם נַעֲשִׂים טְפֵלִים לַלֶּחֶם – לָכֵן מְבָרְכִים עֲלֵיהֶם \"הַגֶּפֶן\". וּבַסּוֹף בִּרְכַּת הַמָּזוֹן פּוֹטֶרֶת גַּם אוֹתָם, וְאֵין צֹרֶךְ \"עַל הַגֶּפֶן\".","פֶּרֶק ז׳, הֲלָכוֹת ג׳, ו׳","מִן הַשָּׂדֶה וּמִן הַכֶּרֶם"],["בַּקִּדּוּשׁ שֶׁבְּבֵית הַכְּנֶסֶת שָׁמַע אִתַּי אֶת הַקִּדּוּשׁ, אֲבָל לֹא טָעַם מִכּוֹס הַקִּדּוּשׁ. עַכְשָׁו הוּא רוֹצֶה מִיץ תַּפּוּזִים. מָה הַדִּין?",["מְבָרֵךְ \"שֶׁהַכֹּל\", כִּי לֹא שָׁתָה מִן הַיַּיִן","שׁוֹתֶה בְּלִי בְּרָכָה, כִּי שָׁמַע אֶת בִּרְכַּת \"הַגֶּפֶן\"","מְבָרֵךְ \"הַגֶּפֶן\" בְּעַצְמוֹ, וְאָז שׁוֹתֶה בְּלִי עוֹד בְּרָכָה","שׁוֹתֶה בְּלִי בְּרָכָה, כִּי כְּבָר יָצָא יְדֵי קִדּוּשׁ"],0,"הַקִּדּוּשׁ פּוֹטֵר אֶת הַמַּשְׁקִים רַק לְמִי שֶׁשָּׁתָה מִן הַיַּיִן. אִתַּי יָצָא יְדֵי קִדּוּשׁ בַּשְּׁמִיעָה, אֲבָל הַמִּיץ אֵינוֹ טָפֵל לְיַיִן שֶׁלֹּא שָׁתָה – וְלָכֵן מְבָרֵךְ \"שֶׁהַכֹּל\".","פֶּרֶק ז׳, הֲלָכָה ד׳","מִן הַשָּׂדֶה וּמִן הַכֶּרֶם"],["לָמָּה תִּקְּנוּ \"הַטּוֹב וְהַמֵּטִיב\" רַק עַל סוּג נוֹסָף שֶׁל יַיִן, וְלֹא עַל סוּג נוֹסָף שֶׁל לֶחֶם?",["כִּי הַיַּיִן הַשֵּׁנִי תָּמִיד מְשֻׁבָּח יוֹתֵר מִן הָרִאשׁוֹן","כִּי הַיַּיִן יָקָר יוֹתֵר מִכָּל מַאֲכָל אַחֵר בַּסְּעוּדָה","כִּי עַל לֶחֶם כְּבָר מְבָרְכִים בְּסוֹף בִּרְכַּת הַמָּזוֹן","כִּי הַיַּיִן מְשַׂמֵּחַ, וְכָל סוּג נוֹסָף מַרְבֶּה שִׂמְחָה"],3,"הַיַּיִן גַּם מַזִּין וְגַם מְשַׂמֵּחַ, וּלְכָל יַיִן אֹפִי מִשֶּׁלּוֹ. כְּשֶׁשּׁוֹתִים יַחַד עוֹד סוּג – הַשִּׂמְחָה גְּדֵלָה, וּמוֹדִים לַה׳ עַל הָרִבּוּי. הַיַּיִן הַשֵּׁנִי אֵינוֹ צָרִיךְ לִהְיוֹת מְשֻׁבָּח יוֹתֵר – רַק שׁוֹנֶה.","פֶּרֶק ז׳, הֲלָכָה ז׳","מִן הַשָּׂדֶה וּמִן הַכֶּרֶם"],["לַאֲרוּחַת בֹּקֶר טִגְּנוּ בַּבַּיִת פְּרוּסוֹת לֶחֶם שְׁלֵמוֹת בְּבֵיצָה. מָה מְבָרְכִים עֲלֵיהֶן?",["\"מְזוֹנוֹת\", כִּי טִגּוּן בְּשֶׁמֶן הוּא כְּמוֹ בִּשּׁוּל","\"הַמּוֹצִיא\", כִּי הַחֲתִיכוֹת גְּדוֹלוֹת מִכְּזַיִת","\"שֶׁהַכֹּל\", כִּי הַבֵּיצָה הִיא עִקַּר הַמַּאֲכָל","\"מְזוֹנוֹת\", כִּי הַלֶּחֶם כְּבָר אֵינוֹ נִרְאֶה כְּמוֹ לֶחֶם"],1,"חֲתִיכַת לֶחֶם גְּדוֹלָה מִכְּזַיִת נִשְׁאֶרֶת לֶחֶם, גַּם כְּשֶׁבִּשְּׁלוּ אוֹ טִגְּנוּ אוֹתָהּ. לָכֵן עַל פְּרוּסוֹת שֶׁטֻּגְּנוּ בְּבֵיצָה מְבָרְכִים לְכָל הַדֵּעוֹת \"הַמּוֹצִיא\" וּבִרְכַּת הַמָּזוֹן. רַק עַל חֲתִיכוֹת קְטַנּוֹת מִכְּזַיִת, כְּמוֹ קְרוּטוֹנִים מִן הַמִּפְעָל – \"מְזוֹנוֹת\".","פֶּרֶק ו׳, הֲלָכָה י״ב","מִן הַשָּׂדֶה וּמִן הַכֶּרֶם"],["בַּטִּיּוּל אָכַל שִׁמְשׁוֹן, בֶּן תֵּשַׁע, רַק עוּגָה – עַד שֶׁשָּׂבַע כְּמוֹ מֵאֲרוּחָה. מְבֻגָּר הָיָה צָרִיךְ לֶאֱכֹל הַרְבֵּה יוֹתֵר כְּדֵי לִשְׂבֹּעַ. מָה יְבָרֵךְ שִׁמְשׁוֹן בַּסּוֹף?",["בִּרְכַּת הַמָּזוֹן, כִּי יְלָדִים מְשַׁעֲרִים לְפִי שְׂבִיעַת יְלָדִים","\"עַל הַמִּחְיָה\", כִּי מְבֻגָּר לֹא הָיָה שָׂבֵעַ מִזֶּה","\"עַל הַמִּחְיָה\", כִּי עַל עוּגָה לְעוֹלָם אֵין בִּרְכַּת הַמָּזוֹן","\"בּוֹרֵא נְפָשׁוֹת\", כִּי עוּגָה אֵינָהּ מֵחֲמֵשֶׁת מִינֵי דָּגָן"],0,"מִי שֶׁשָּׂבֵעַ מִמַּאֲפֵה מְזוֹנוֹת כְּמוֹ מֵאֲרוּחָה רְגִילָה – קָבַע עָלָיו סְעוּדָה. יְלָדִים מְשַׁעֲרִים לְפִי מָה שֶׁמַּשְׂבִּיעַ יְלָדִים, וְלָכֵן שִׁמְשׁוֹן מְבָרֵךְ בַּסּוֹף בִּרְכַּת הַמָּזוֹן – גַּם אִם בַּהַתְחָלָה בֵּרַךְ \"מְזוֹנוֹת\" וְנִגְרַר לֶאֱכֹל עוֹד וָעוֹד.","פֶּרֶק ו׳, הֲלָכוֹת ב׳–ג׳","מִן הַשָּׂדֶה וּמִן הַכֶּרֶם"],["בַּמְּסִבָּה אָכַל שְׁמוּאֵל מְשֻׁלָּשׁ אֶחָד שֶׁל פִּיצָה רְגִילָה, מִבָּצֵק שֶׁל לֶחֶם. מָה מְבָרְכִים?",["״מְזוֹנוֹת״ וְ״עַל הַמִּחְיָה״, כִּי אָכַל רַק מְשֻׁלָּשׁ אֶחָד","״שֶׁהַכֹּל״, כִּי הַגְּבִינָה וְהָרֹטֶב הֵם עִקַּר הַפִּיצָה","נְטִילַת יָדַיִם, ״הַמּוֹצִיא״ וּבְסוֹף בִּרְכַּת הַמָּזוֹן","״הַמּוֹצִיא״ בְּלִי נְטִילָה, כִּי הַפִּיצָה אֵינָהּ לֶחֶם שָׁלֵם"],2,"בָּצֵק שֶׁל פִּיצָה רְגִילָה הוּא בָּצֵק שֶׁל לֶחֶם, וְהַתּוֹסָפוֹת אֵינָן מְשַׁנּוֹת אֶת דִּינוֹ. לָכֵן גַּם עַל מְשֻׁלָּשׁ אֶחָד נוֹטְלִים יָדַיִם, מְבָרְכִים ״הַמּוֹצִיא״ וּבִרְכַּת הַמָּזוֹן.","פֶּרֶק ו׳, הֲלָכָה ט׳","מִן הַשָּׂדֶה וּמִן הַכֶּרֶם"],["אָרִי בֵּרֵךְ \"בּוֹרֵא פְּרִי הָעֵץ\" עַל מְלָפְפוֹן, וְאָז נִזְכַּר שֶׁטָּעָה. מָה עָלָיו לַעֲשׂוֹת?",["לְבָרֵךְ שׁוּב \"הָאֲדָמָה\", כִּי הַמְּלָפְפוֹן לֹא גָּדֵל עַל עֵץ","לֶאֱכֹל בְּלִי בְּרָכָה, כִּי \"הָעֵץ\" הִיא בְּרָכָה חֲשׁוּבָה יוֹתֵר","לֶאֱכֹל בְּלִי בְּרָכָה, כִּי גַּם הָעֵץ גָּדֵל מִן הָאֲדָמָה","לְבָרֵךְ שׁוּב \"שֶׁהַכֹּל\", כִּי כָּךְ עוֹשִׂים בְּכָל סָפֵק"],0,"פְּרִי הָאֲדָמָה לֹא גָּדֵל עַל עֵץ, וְלָכֵן \"הָעֵץ\" עָלָיו אֵינָהּ בְּרָכָה נְכוֹנָה. רַק בַּמִּקְרֶה הַהָפוּךְ – \"הָאֲדָמָה\" עַל פְּרִי עֵץ – יוֹצְאִים, כִּי גַּם הָעֵץ גָּדֵל מִן הָאֲדָמָה.","פֶּרֶק ח׳, הֲלָכָה ב׳","הָעֵץ, הָאֲדָמָה וְשֶׁהַכֹּל"],["דָּנִי בֵּרֵךְ \"הָעֵץ\" וְאָכַל אֶשְׁכּוֹלִית. בַּסּוֹף נִשְׁאַר מִיץ בַּצַּלַּחַת, וְהוּא רוֹצֶה לִשְׁתּוֹת אוֹתוֹ. מָה הַדִּין?",["מְבָרֵךְ \"שֶׁהַכֹּל\", כִּי עַל כָּל מִיץ פֵּרוֹת מְבָרְכִים כָּךְ","שׁוֹתֶה בְּלִי בְּרָכָה, כִּי הַמִּיץ טָפֵל לַפְּרִי שֶׁאָכַל","מְבָרֵךְ שׁוּב \"הָעֵץ\", כִּי הַמִּיץ יָצָא מִן הַפְּרִי","לֹא שׁוֹתֶה, כִּי מִיץ מִן הַצַּלַּחַת אֵינוֹ מַשְׁקֶה"],1,"מִיץ שֶׁנִּסְחַט לְבַד – \"שֶׁהַכֹּל\". אֲבָל מִיץ שֶׁיָּצָא מֵהַפְּרִי בִּזְמַן הָאֲכִילָה טָפֵל לַפְּרִי, וְנִפְטָר בַּבְּרָכָה שֶׁבֵּרַךְ עַל הָאֶשְׁכּוֹלִית.","פֶּרֶק ח׳, הֲלָכָה ט״ו","הָעֵץ, הָאֲדָמָה וְשֶׁהַכֹּל"],["לִפְנֵי יוֹסֵף עוּגִיָּה, עֲנָבִים וַאֲבַטִּיחַ, וְהוּא רוֹצֶה לֶאֱכֹל מִכֻּלָּם עַכְשָׁו. עַל מָה יְבָרֵךְ רִאשׁוֹן?",["עַל הָאֲבַטִּיחַ, כִּי הוּא הַגָּדוֹל וְהֶחָבִיב מִכֻּלָּם","עַל הָעֲנָבִים, כִּי הֵם מִשִּׁבְעַת הַמִּינִים","עַל הָעוּגִיָּה, כִּי \"מְזוֹנוֹת\" קוֹדֶמֶת לַפֵּרוֹת","עַל מָה שֶׁיִּרְצֶה – אֵין סֵדֶר קָבוּעַ לַבְּרָכוֹת"],2,"הַסֵּדֶר הוּא מג״ע א״ש: מְזוֹנוֹת, גֶּפֶן, עֵץ, אֲדָמָה, שֶׁהַכֹּל. מַאַכְלֵי הַמְּזוֹנוֹת מְשַׂבְּעִים בְּיוֹתֵר, וְלָכֵן הֵם קוֹדְמִים לַפֵּרוֹת.","פֶּרֶק ט׳, הֲלָכָה ח׳","הָעֵץ, הָאֲדָמָה וְשֶׁהַכֹּל"],["לִפְנֵי דָּוִד תְּמָרִים וְתַפּוּחִים, וּשְׁנֵיהֶם חֲבִיבִים עָלָיו בְּשָׁוֶה. אֵיךְ יְבָרֵךְ?",["עַל הַתַּפּוּחִים, כִּי הֵם גְּדוֹלִים יוֹתֵר מֵהַתְּמָרִים","פַּעֲמַיִם \"הָעֵץ\" – פַּעַם אַחַת עַל כָּל סוּג","עַל הַפְּרִי שֶׁמֻּנָּח קָרוֹב יוֹתֵר אֵלָיו","עַל הַתְּמָרִים, וְכָךְ יִפְטֹר גַּם אֶת הַתַּפּוּחִים"],3,"הַתָּמָר הוּא מִשִּׁבְעַת הַמִּינִים שֶׁנִּשְׁתַּבְּחָה בָּהֶם אֶרֶץ יִשְׂרָאֵל, וְלָכֵן מְבָרְכִים עָלָיו. לִשְׁנֵיהֶם אוֹתָהּ בְּרָכָה, וְלָכֵן בְּרָכָה אַחַת פּוֹטֶרֶת אֶת שְׁנֵיהֶם.","פֶּרֶק ט׳, הֲלָכָה י׳","הָעֵץ, הָאֲדָמָה וְשֶׁהַכֹּל"],["שִׁמְעוֹן בֵּרֵךְ עַל תַּפּוּחַ, וְלִפְנֵי שֶׁנָּגַס שָׁאַל: \"שְׁטַפְתֶּם אוֹתוֹ?\" מָה הַדִּין?",["אֵינוֹ חוֹזֵר לְבָרֵךְ, כִּי שָׁאַל עַל הַתַּפּוּחַ עַצְמוֹ","חוֹזֵר וּמְבָרֵךְ, כִּי כָּל מִלָּה בֵּינְתַיִם מַפְסִיקָה","חוֹזֵר וּמְבָרֵךְ רַק אִם חִכָּה לִתְשׁוּבָה זְמַן רַב","אֵינוֹ חוֹזֵר, כִּי מֻתָּר לְדַבֵּר מָה שֶׁרוֹצִים"],0,"לֹא הָיָה צָרִיךְ לְדַבֵּר. אֲבָל הַשְּׁאֵלָה עָסְקָה בָּאֹכֶל עַצְמוֹ, וְלָכֵן הִיא לֹא מַפְסִיקָה, וְאֵינוֹ חוֹזֵר לְבָרֵךְ. מִלָּה שֶׁאֵינָהּ קְשׁוּרָה לָאֹכֶל – כֵּן מַפְסִיקָה.","פֶּרֶק ט׳, הֲלָכָה ג׳","הָעֵץ, הָאֲדָמָה וְשֶׁהַכֹּל"],["אֵיתָן בֵּרֵךְ \"הָאֲדָמָה\" עַל עַגְבָנִיּוֹת שְׁרִי בַּבַּיִת, וְהָלַךְ עִם הַקֻּפְסָה לְבֵית חֲבֵרוֹ. שָׁם הוּא רוֹצֶה לְהַמְשִׁיךְ לֶאֱכֹל. מָה הַדִּין?",["אֵינוֹ מְבָרֵךְ, כִּי הַקֻּפְסָה הָיְתָה כָּל הַזְּמַן בְּיָדוֹ","אֵינוֹ מְבָרֵךְ, כִּי עֲדַיִן לֹא עָבְרָה חֲצִי שָׁעָה","מְבָרֵךְ שׁוּב, כִּי יָצָא מִבֵּיתוֹ לְבַיִת אַחֵר","מְבָרֵךְ שׁוּב רַק אִם יֹאכַל פְּרִי מִסּוּג אַחֵר"],2,"עַל מַאֲכָל שֶׁאַחֲרָיו מְבָרְכִים \"בּוֹרֵא נְפָשׁוֹת\", מִי שֶׁיָּצָא מִבֵּיתוֹ לָרְחוֹב אוֹ לְבַיִת אַחֵר – שִׁנָּה אֶת מְקוֹמוֹ, וּמְבָרֵךְ שׁוּב. מֵחֶדֶר לְחֶדֶר בְּתוֹךְ הַבַּיִת – לֹא.","פֶּרֶק ט׳, הֲלָכָה ז׳","הָעֵץ, הָאֲדָמָה וְשֶׁהַכֹּל"],["לַאֲרוּחַת צָהֳרַיִם אָכְלָה הֲדַסָּה צַלַּחַת אֹרֶז מְבֻשָּׁל. מָה תְּבָרֵךְ לְפָנָיו וְאַחֲרָיו?",["\"מְזוֹנוֹת\" לְפָנָיו, וְ\"עַל הַמִּחְיָה\" אַחֲרָיו, כְּמוֹ עַל פְּתִיתִים","\"מְזוֹנוֹת\" לְפָנָיו, וְ\"בּוֹרֵא נְפָשׁוֹת\" אַחֲרָיו","\"הָאֲדָמָה\" לְפָנָיו, כִּי הָאֹרֶז הוּא מִין קִטְנִית","\"הַמּוֹצִיא\" וּבִרְכַּת הַמָּזוֹן, כִּי הִיא אָכְלָה אֲרוּחָה מַשְׂבִּיעָה"],1,"עַל אֹרֶז מְבֻשָּׁל קָבְעוּ חֲכָמִים \"מְזוֹנוֹת\", כִּי הוּא מַזִּין כְּמוֹ מִינֵי דָּגָן. אֲבָל הוּא אֵינוֹ מִשִּׁבְעַת הַמִּינִים, וְלָכֵן אַחֲרָיו מְבָרְכִים \"בּוֹרֵא נְפָשׁוֹת\" – וְלֹא \"עַל הַמִּחְיָה\".","פֶּרֶק ח׳, הֲלָכָה י״ג","הָעֵץ, הָאֲדָמָה וְשֶׁהַכֹּל"],["בַּחֲנֻכָּה אָכַל יְהוּדָה לְבִיבוֹת מִתַּפּוּחֵי אֲדָמָה מְגֻרָּדִים, וְרוֹאִים בָּהֶן חֲתִיכוֹת שֶׁל תַּפּוּחַ אֲדָמָה. מָה בֵּרַךְ?",["\"שֶׁהַכֹּל\", כִּי הַלְּבִיבוֹת טֻגְּנוּ בְּשֶׁמֶן עִם עוֹד מַרְכִּיבִים","\"הָאֲדָמָה\", כִּי תַּפּוּחֵי הָאֲדָמָה לֹא רֻסְּקוּ לְגַמְרֵי","\"מְזוֹנוֹת\", כִּי לְבִיבוֹת הֵן כְּמוֹ מַאֲפֶה שֶׁל בָּצֵק","\"הָאֲדָמָה\", אֲבָל רַק אִם אוֹכְלִים אוֹתָן בְּתוֹךְ הַסְּעוּדָה"],1,"תַּפּוּחַ אֲדָמָה מְגֻרָּד לֹא רֻסַּק לְגַמְרֵי, וְלָכֵן נִשְׁאֶרֶת בִּרְכָתוֹ – \"הָאֲדָמָה\". אֲבָל עַל לְבִיבוֹת מִקֶּמַח תַּפּוּחֵי אֲדָמָה, שֶׁרֻסַּק לְגַמְרֵי – \"שֶׁהַכֹּל\".","פֶּרֶק ח׳, הֲלָכָה ט׳","הָעֵץ, הָאֲדָמָה וְשֶׁהַכֹּל"],["בַּחֲנוּת קָנָה אֶלְיָשִׁיב שַׂקִּית גַּרְעִינֵי אֲבַטִּיחַ קְלוּיִים. מָה יְבָרֵךְ עֲלֵיהֶם?",["״שֶׁהַכֹּל״, כִּי גַּרְעִינִים הֵם לֹא הָעִקָּר שֶׁל הַפְּרִי","״הָעֵץ״, כִּי הַגַּרְעִין הוּא הַחֵלֶק שֶׁמִּמֶּנּוּ צוֹמֵחַ","״הָאֲדָמָה״, כִּי מְגַדְּלִים אֶת הָאֲבַטִּיחִים הָאֵלֶּה בִּשְׁבִיל הַגַּרְעִינִים","״הָאֲדָמָה״ רַק כְּשֶׁאוֹכְלִים אוֹתָם יַחַד עִם הָאֲבַטִּיחַ עַצְמוֹ"],2,"גַּרְעִינֵי אֲבַטִּיחַ שֶׁאוֹכְלִים מְגַדְּלִים מִזַּנִּים מְיֻחָדִים, שֶׁיֵּשׁ בָּהֶם מְעַט בָּשָׂר וְהַרְבֵּה גַּרְעִינִים. הַגַּרְעִינִים הֵם עִקַּר הַפְּרִי – וּבִרְכָתָם ״הָאֲדָמָה״. וְכָךְ גַּם גַּרְעִינִים לְבָנִים וּשְׁחֹרִים.","פֶּרֶק ח׳, הֲלָכָה ה׳","הָעֵץ, הָאֲדָמָה וְשֶׁהַכֹּל"],["בִּקְעָרָה יֵשׁ קוֹמְפּוֹט שֶׁל אֲגָסִים. אָחִיו שֶׁל נֹעַם לֹא אוֹהֵב אֶת הָאֲגָסִים, וְשׁוֹתֶה רַק אֶת הַנֹּזֶל. מָה יְבָרֵךְ?",["״הָעֵץ״, כִּי הַנֹּזֶל קִבֵּל אֶת הַטַּעַם מִן הָאֲגָסִים","״שֶׁהַכֹּל״, כִּי בִּשְׁתִיַּת הַנֹּזֶל לְבַדּוֹ יֵשׁ סָפֵק","לֹא מְבָרְכִים עַל נֹזֶל שֶׁנִּשְׁאַר אַחֲרֵי בִּשּׁוּל","״הָאֲדָמָה״, כִּי הָאֲגָסִים בֻּשְּׁלוּ וְאִבְּדוּ אֶת חֲשִׁיבוּתָם"],1,"עַל מֵי קוֹמְפּוֹט לְבַדָּם נֶחְלְקוּ גְּדוֹלֵי הָרִאשׁוֹנִים אִם מְבָרְכִים ״הָעֵץ״ אוֹ ״שֶׁהַכֹּל״, וּמִסָּפֵק מְבָרְכִים ״שֶׁהַכֹּל״. אֲבָל מִי שֶׁאוֹכֵל גַּם מִן הַפֵּרוֹת – מְבָרֵךְ ״הָעֵץ״, וְהַנֹּזֶל נִפְטָר.","פֶּרֶק ח׳, הֲלָכָה י״ז","הָעֵץ, הָאֲדָמָה וְשֶׁהַכֹּל"],["יְהוֹנָתָן בֵּרַךְ ״שֶׁהַכֹּל״ עַל חֲתִיכַת דָּג, בְּלִי לַחְשֹׁב עַל שׁוּם דָּבָר אַחֵר. עַל הַשֻּׁלְחָן לְפָנָיו יֵשׁ גַּם שׁוֹקוֹלָד. מָה הַדִּין?",["יְבָרֵךְ שׁוּב ״שֶׁהַכֹּל״, כִּי דָּג וְשׁוֹקוֹלָד הֵם מִינִים שׁוֹנִים","לֹא יְבָרֵךְ, כִּי הַשּׁוֹקוֹלָד מֻנָּח לְפָנָיו וּבִרְכָתוֹ שָׁוָה","יְבָרֵךְ שׁוּב, כִּי בִּשְׁעַת הַבְּרָכָה לֹא חָשַׁב עָלָיו","לֹא יֹאכַל שׁוֹקוֹלָד עַד שֶׁיְּבָרֵךְ ״בּוֹרֵא נְפָשׁוֹת״ עַל הַדָּג"],1,"מִי שֶׁבֵּרַךְ סְתָם – בִּרְכָתוֹ פּוֹטֶרֶת אֶת כָּל הַמַּאֲכָלִים שֶׁלְּפָנָיו עַל הַשֻּׁלְחָן וּבִרְכָתָם שָׁוָה, גַּם מִינִים שׁוֹנִים לְגַמְרֵי. וְטוֹב לְהִתְרַגֵּל לְכַוֵּן בְּכָל בְּרָכָה עַל כָּל מָה שֶׁבַּבַּיִת וּבִרְכָתוֹ שָׁוָה.","פֶּרֶק ט׳, הֲלָכָה ה׳","הָעֵץ, הָאֲדָמָה וְשֶׁהַכֹּל"],["בַּצַּלַּחַת שֶׁל אַבְרָהָם עוּגִיָּה שְׁלֵמָה, וְעוּגִיַּת שׁוֹקוֹלָד שְׁבוּרָה שֶׁהוּא אוֹהֵב יוֹתֵר. עַל אֵיזוֹ יְבָרֵךְ ״מְזוֹנוֹת״?",["עַל הַשְּׁבוּרָה, כִּי הַמַּאֲכָל הֶחָבִיב תָּמִיד קוֹדֵם","עַל הַשְּׁלֵמָה, כִּי הַשָּׁלֵם קוֹדֵם גַּם לֶחָבִיב","עַל שְׁתֵּיהֶן יַחַד, כִּי אֵין סֵדֶר בְּעוּגִיּוֹת","עַל הַגְּדוֹלָה מִבֵּינֵיהֶן, כִּי הַגֹּדֶל קוֹבֵעַ רִאשׁוֹן"],1,"יֵשׁ שְׁלֹשָׁה כְּלָלֵי חֲשִׁיבוּת: שָׁלֵם, חָבִיב וְגָדוֹל – לְפִי הַסֵּדֶר הַזֶּה. כְּשֶׁהֵם מִתְנַגְּשִׁים, הַכְּלָל הָרִאשׁוֹן גּוֹבֵר: הָעוּגִיָּה הַשְּׁלֵמָה קוֹדֶמֶת לַשְּׁבוּרָה, גַּם אִם הַשְּׁבוּרָה חֲבִיבָה יוֹתֵר.","פֶּרֶק ט׳, הֲלָכָה ט׳","הָעֵץ, הָאֲדָמָה וְשֶׁהַכֹּל"],["אֵלִיָּה אָכַל כְּזַיִת תְּמָרִים וּכְזַיִת תַּפּוּחִים. אֵיזוֹ בְּרָכָה אַחֲרוֹנָה יְבָרֵךְ?",["\"עַל הָעֵץ\" וְגַם \"בּוֹרֵא נְפָשׁוֹת\" עַל הַתַּפּוּחִים","רַק \"בּוֹרֵא נְפָשׁוֹת\", כִּי הִיא פּוֹטֶרֶת אֶת כָּל הַפֵּרוֹת","רַק \"עַל הָעֵץ\", וְהִיא פּוֹטֶרֶת גַּם אֶת הַתַּפּוּחִים","\"בּוֹרֵא נְפָשׁוֹת\" עַל שְׁנֵיהֶם, כִּי אָכַל שְׁנֵי פֵּרוֹת שׁוֹנִים"],2,"\"עַל הָעֵץ\" הִיא הוֹדָאָה עַל פְּרִי הָעֵץ, וְלָכֵן הִיא פּוֹטֶרֶת גַּם אֶת שְׁאָר פֵּרוֹת הָעֵץ. רַק עַל פְּרִי אֲדָמָה הָיָה צָרִיךְ לְהוֹסִיף \"בּוֹרֵא נְפָשׁוֹת\".","פֶּרֶק י׳, הֲלָכָה ג׳","בְּרָכָה אַחֲרוֹנָה, עִקָּר וְטָפֵל"],["מֹשֶׁה אָכַל כְּזַיִת עֲנָבִים וּכְזַיִת מְלָפְפוֹן, וּבֵרַךְ רַק \"בּוֹרֵא נְפָשׁוֹת\". מָה הַדִּין?",["יָצָא, כִּי \"בּוֹרֵא נְפָשׁוֹת\" פּוֹטֶרֶת כָּל מַאֲכָל בְּדִיעֲבַד","לֹא יָצָא עַל הָעֲנָבִים, וְעָלָיו לְבָרֵךְ גַּם \"עַל הָעֵץ\"","יָצָא, כִּי הָעֲנָבִים וְהַמְּלָפְפוֹן מִצְטָרְפִים יַחַד","לֹא יָצָא כְּלָל, וְעָלָיו לֶאֱכֹל שׁוּב וּלְבָרֵךְ מֵחָדָשׁ"],1,"בַּבְּרָכָה הָאַחֲרוֹנָה אֵין בְּרָכָה אַחַת פּוֹטֶרֶת אֶת חֲבֶרְתָּהּ. עַל הַמְּלָפְפוֹן יָצָא בְּ\"בוֹרֵא נְפָשׁוֹת\", וְעַל הָעֲנָבִים – מִשִּׁבְעַת הַמִּינִים – עָלָיו לְבָרֵךְ \"עַל הָעֵץ\".","פֶּרֶק י׳, הֲלָכָה ד׳","בְּרָכָה אַחֲרוֹנָה, עִקָּר וְטָפֵל"],["נֹעַם שָׁתָה כּוֹס מִיץ גְּדוֹלָה בִּלְגִימוֹת קְטַנּוֹת, לְאַט לְאַט, בְּמֶשֶׁךְ שָׁעָה שְׁלֵמָה. מָה הַדִּין?",["לֹא יְבָרֵךְ, כִּי לֹא שָׁתָה רְבִיעִית בִּרְצִיפוּת","יְבָרֵךְ \"בּוֹרֵא נְפָשׁוֹת\", כִּי בַּסּוֹף שָׁתָה כּוֹס שְׁלֵמָה","יְבָרֵךְ רַק אִם שָׁתָה יוֹתֵר מִשְּׁתֵּי כּוֹסוֹת","לֹא יְבָרֵךְ, כִּי עַל מִיץ אֵין בְּרָכָה אַחֲרוֹנָה"],0,"עַל מַשְׁקֶה מְבָרְכִים בְּרָכָה אַחֲרוֹנָה רַק כְּשֶׁשָּׁתוּ רְבִיעִית בִּרְצִיפוּת, כְּמוֹ שֶׁרְגִילִים לִשְׁתּוֹת. מִי שֶׁשּׁוֹתֶה לְאַט מִזֶּה – לֹא מְבָרֵךְ.","פֶּרֶק י׳, הֲלָכָה י׳","בְּרָכָה אַחֲרוֹנָה, עִקָּר וְטָפֵל"],["בְּפַשְׁטִידַת יְרָקוֹת שָׂמוּ מְעַט קֶמַח, רַק כְּדֵי שֶׁהִיא תִּדָּבֵק וְלֹא תִּתְפָּרֵק. מָה מְבָרְכִים עָלֶיהָ?",["\"מְזוֹנוֹת\", כִּי כָּל תַּעֲרֹבֶת עִם קֶמַח בִּרְכָתָהּ מְזוֹנוֹת","\"שֶׁהַכֹּל\", כִּי הַיְּרָקוֹת נִתְמַעֲכוּ וְהִשְׁתַּנּוּ לְגַמְרֵי","שְׁתֵּי בְּרָכוֹת – \"מְזוֹנוֹת\" וְ\"הָאֲדָמָה\" – כְּדֵי לָצֵאת מִסָּפֵק","\"הָאֲדָמָה\", כִּי הַקֶּמַח רַק מַדְבִּיק וְהוּא טָפֵל"],3,"קֶמַח שֶׁבָּא לָתֵת טַעַם אוֹ לְהַשְׂבִּיעַ קוֹבֵעַ \"מְזוֹנוֹת\". אֲבָל קֶמַח שֶׁבָּא רַק לְהַדְבִּיק – טָפֵל, וְהַבְּרָכָה הוֹלֶכֶת אַחַר הַיְּרָקוֹת.","פֶּרֶק י״א, הֲלָכָה ד׳","בְּרָכָה אַחֲרוֹנָה, עִקָּר וְטָפֵל"],["עֲקִיבָא אוֹכֵל גְּלִידָה בִּגְבִיעַ טָעִים וּפָרִיךְ, וְהוּא נֶהֱנֶה גַּם מֵהַגָּבִיעַ. מָה יְבָרֵךְ?",["רַק \"שֶׁהַכֹּל\" עַל הַגְּלִידָה, וְהַגָּבִיעַ טָפֵל לָהּ","\"מְזוֹנוֹת\" עַל הַגָּבִיעַ וְ\"שֶׁהַכֹּל\" עַל הַגְּלִידָה","רַק \"מְזוֹנוֹת\", כִּי הַגָּבִיעַ עָשׂוּי מִמִּינֵי דָּגָן","רַק \"שֶׁהַכֹּל\", כִּי גְּלִידָה הִיא מַשְׁקֶה קָפוּא"],1,"כְּשֶׁהַגָּבִיעַ טָעִים וְרוֹצִים בּוֹ – יֵשׁ לוֹ חֲשִׁיבוּת מִשֶּׁלּוֹ, וּמְבָרְכִים עַל שְׁנֵיהֶם. רַק גָּבִיעַ תָּפֵל, שֶׁבָּא לְהַחֲזִיק, טָפֵל לַגְּלִידָה.","פֶּרֶק י״א, הֲלָכָה ז׳","בְּרָכָה אַחֲרוֹנָה, עִקָּר וְטָפֵל"],["יְהוּדָה מָרַח שִׁכְבָה עָבָה שֶׁל מִמְרָח שׁוֹקוֹלָד עַל קְרֶקֶר, כְּדֵי שֶׁהַקְּרֶקֶר יִהְיֶה טָעִים. מָה יְבָרֵךְ?",["\"שֶׁהַכֹּל\", כִּי הַשּׁוֹקוֹלָד חָבִיב עָלָיו יוֹתֵר מֵהַקְּרֶקֶר","שְׁתֵּי בְּרָכוֹת, כִּי הַשִּׁכְבָה עָבָה וַחֲשׁוּבָה","\"מְזוֹנוֹת\" עַל הַקְּרֶקֶר, וְהַמִּמְרָח נִפְטָר אִתּוֹ","\"שֶׁהַכֹּל\", כִּי יֵשׁ יוֹתֵר מִמְרָח מִקְּרֶקֶר"],2,"הַמִּמְרָח בָּא לְהַטְעִים אֶת הַקְּרֶקֶר, וְלָכֵן הוּא טָפֵל – גַּם כְּשֶׁהַשִּׁכְבָה עָבָה וְגַם כְּשֶׁהוּא אוֹהֵב אוֹתוֹ מְאוֹד.","פֶּרֶק י״א, הֲלָכָה ו׳","בְּרָכָה אַחֲרוֹנָה, עִקָּר וְטָפֵל"],["יוֹסֵף אָכַל עֵנָב אֶחָד בִּלְבַד, וְלֹא יוֹתֵר. מָה הַדִּין לְגַבֵּי בְּרָכָה אַחֲרוֹנָה?",["מְבָרֵךְ \"עַל הָעֵץ\", כִּי הָעֵנָב הוּא מִשִּׁבְעַת הַמִּינִים","מְבָרֵךְ \"בּוֹרֵא נְפָשׁוֹת\", כִּי עֵנָב אֶחָד אֵינוֹ כְּזַיִת","לֹא מְבָרֵךְ, וּלְכַתְּחִלָּה עָדִיף לֶאֱכֹל כְּשִׁעוּר כְּזַיִת","חַיָּב לֶאֱכֹל עוֹד, אַחֶרֶת הַבְּרָכָה הָרִאשׁוֹנָה לְבַטָּלָה"],2,"לַהֲלָכָה מְבָרְכִים בְּרָכָה אַחֲרוֹנָה רַק אַחֲרֵי כְּזַיִת, גַּם עַל בְּרִיָּה שְׁלֵמָה. אֲבָל כְּדֵי לֹא לְהִכָּנֵס לְסָפֵק – לְכַתְּחִלָּה רָאוּי לֹא לֶאֱכֹל בְּרִיָּה לְבַדָּהּ.","פֶּרֶק י׳, הֲלָכָה ח׳","בְּרָכָה אַחֲרוֹנָה, עִקָּר וְטָפֵל"],["בַּצַּלַּחַת מָרָק, וּבוֹ הַרְבֵּה נוֹזְלִים וּמְעַט מְאוֹד יְרָקוֹת. מָה מְבָרְכִים?",["\"שֶׁהַכֹּל\" עַל הַמָּרָק, וְהַיְּרָקוֹת הַמְּעַטִּים טְפֵלִים לוֹ","\"הָאֲדָמָה\" עַל הַיְּרָקוֹת, וְהַנּוֹזְלִים טְפֵלִים לָהֶם תָּמִיד","שְׁתֵּי בְּרָכוֹת, כִּי בְּכָל מָרָק יֵשׁ יְרָקוֹת וּמַיִם","\"מְזוֹנוֹת\", כִּי מָרָק הוּא מַאֲכָל מַשְׂבִּיעַ כְּמוֹ אֹרֶז"],0,"כְּשֶׁרֹב הַמָּרָק נוֹזְלִים וְיֵשׁ בּוֹ מְעַט מְאוֹד יְרָקוֹת – הַיְּרָקוֹת טְפֵלִים, וּמְבָרְכִים \"שֶׁהַכֹּל\". רַק כְּשֶׁיֵּשׁ מִעוּט חָשׁוּב שֶׁל יְרָקוֹת מְבָרְכִים שְׁתֵּי בְּרָכוֹת.","פֶּרֶק י״א, הֲלָכָה ט׳","בְּרָכָה אַחֲרוֹנָה, עִקָּר וְטָפֵל"],["אוּרִי אָכַל מַהֵר חֹפֶן גָּדוֹל שֶׁל בַּמְבָּה, בְּנֶפַח שֶׁל יוֹתֵר מֵחֲצִי בֵּיצָה – אֲבָל הִיא כִּמְעַט לֹא שׁוֹקֶלֶת כְּלוּם. הַאִם יְבָרֵךְ ״בּוֹרֵא נְפָשׁוֹת״?",["לֹא, כִּי בַּמִּשְׁקָל אֵין בַּבַּמְבָּה אֲפִלּוּ כְּזַיִת","כֵּן, כִּי מוֹדְדִים לְפִי הַנֶּפַח, כּוֹלֵל הַחֲרִירִים הַקְּטַנִּים","לֹא, כִּי מַפְחִיתִים אֶת כָּל הָאֲוִיר שֶׁבְּתוֹךְ הַבַּמְבָּה","כֵּן, אֲבָל רַק אִם אָכַל אֶת כֻּלָּהּ בִּנְגִיסָה אַחַת"],1,"הַשִּׁעוּר תָּלוּי בַּנֶּפַח, וְלֹא בַּמִּשְׁקָל. בְּבַמְבָּה, בְּפּוֹפְּקוֹרְן וּבִפְרִיכִיּוֹת אֵין חֲלָלִים גְּדוֹלִים, וְלָכֵן הוֹלְכִים לְפִי הַנֶּפַח שֶׁלְּפָנֵינוּ – וּמִי שֶׁאָכַל כַּחֲצִי בֵּיצָה מְבָרֵךְ.","פֶּרֶק י׳, הֲלָכָה ו׳","בְּרָכָה אַחֲרוֹנָה, עִקָּר וְטָפֵל"],["נָתָן לֹא זוֹכֵר אִם כְּבָר בֵּרֵךְ עַל הָעוּגִיָּה שֶׁבְּיָדוֹ. אָחִיו עוֹמֵד לְבָרֵךְ ״מְזוֹנוֹת״ עַל עוּגִיָּה. מָה כְּדַאי לַעֲשׂוֹת?",["יְבָרֵךְ שׁוּב בְּעַצְמוֹ, כִּי חוֹבָה לְבָרֵךְ לִפְנֵי אֲכִילָה","יְבַקֵּשׁ מֵאָחִיו לְהוֹצִיא אוֹתוֹ, וְיַעֲנֶה אָמֵן","יַפְסִיק לֶאֱכֹל, עַד שֶׁיִּזְכֹּר בְּוַדַּאי מָה עָשָׂה","יְבָרֵךְ וְיַחְלִיף אֶת שֵׁם ה׳ בְּמִלָּה אַחֶרֶת"],1,"בְּסָפֵק לֹא מְבָרְכִים, כִּי אוּלַי זוֹ בְּרָכָה לְבַטָּלָה. אֲבָל כְּשֶׁאֶפְשָׁר – יוֹצְאִים מֵהַסָּפֵק: שׁוֹמְעִים אֶת הַבְּרָכָה מִמִּי שֶׁמְּבָרֵךְ אוֹתָהּ, עוֹנִים אָמֵן וְאוֹכְלִים מִיָּד.","פֶּרֶק י״ב, הֲלָכָה ד׳","בְּרָכָה בִּמְקוֹמָהּ וְשֻׁלְחָן שֶׁל חֶסֶד"],["בְּמוֹצָאֵי שַׁבָּת, לִפְנֵי הַהַבְדָּלָה, בֵּרֵךְ אֵיתָן ״שֶׁהַכֹּל״ עַל מִיץ – וְאָז נִזְכַּר. מָה יַעֲשֶׂה?",["יִטְעַם מְעַט, כְּדֵי שֶׁהַבְּרָכָה לֹא תִּהְיֶה לְבַטָּלָה","לֹא יִטְעַם כְּלָל, כִּי אָסוּר לֶאֱכֹל לִפְנֵי הַבְדָּלָה","יִשְׁתֶּה אֶת כָּל הַכּוֹס, כִּי כְּבָר בֵּרֵךְ עָלֶיהָ","יַשְׁאִיר אֶת הַמִּיץ וִיבָרֵךְ שׁוּב אַחֲרֵי הַהַבְדָּלָה"],0,"הַמִּיץ עַצְמוֹ כָּשֵׁר, רַק הַזְּמַן לֹא מַתְאִים. לָכֵן טוֹעֲמִים מְעַט, וְהַבְּרָכָה לֹא נֶאֶמְרָה לַשָּׁוְא. אֲבָל עַל מַאֲכָל אָסוּר, כְּמוֹ חָמֵץ בְּפֶסַח, וּבְיוֹם צוֹם – לֹא טוֹעֲמִים.","פֶּרֶק י״ב, הֲלָכָה י״א","בְּרָכָה בִּמְקוֹמָהּ וְשֻׁלְחָן שֶׁל חֶסֶד"],["גַּד לָקַח סֻכָּרִיָּה מֵחָבֵר בְּלִי רְשׁוּת. הַאִם יְבָרֵךְ עָלֶיהָ?",["כֵּן, כִּי הַסֻּכָּרִיָּה עַצְמָהּ כְּשֵׁרָה לְגַמְרֵי","כֵּן, וְאַחַר כָּךְ יְשַׁלֵּם לַחָבֵר אֶת מְחִירָהּ","יְבָרֵךְ בְּלַחַשׁ, כְּדֵי שֶׁאִישׁ לֹא יִשְׁמַע","לֹא, עַל מַאֲכָל גָּנוּב אֵין מְבָרְכִים בִּכְלָל"],3,"מִי שֶׁלָּקַח בְּלִי רְשׁוּת צָרִיךְ לְהַחֲזִיר, וְאָסוּר לוֹ לְבָרֵךְ. כָּתוּב: ״וּבֹצֵעַ בֵּרֵךְ נִאֵץ ה׳״ – בְּרָכָה כָּזוֹ הִיא זִלְזוּל וְלֹא שֶׁבַח.","פֶּרֶק י״ב, הֲלָכָה י׳","בְּרָכָה בִּמְקוֹמָהּ וְשֻׁלְחָן שֶׁל חֶסֶד"],["אוֹרֵחַ שֶׁאֵינוֹ רָגִיל לְבָרֵךְ יוֹשֵׁב אֶצְלְכֶם לָאֲרוּחָה. מָה נָכוֹן לַעֲשׂוֹת?",["לֹא לְהַגִּישׁ לוֹ אֹכֶל, כְּדֵי שֶׁלֹּא יֹאכַל בְּלִי בְּרָכָה","לְהַסְבִּיר לוֹ בְּתֹקֶף שֶׁאָסוּר לֶאֱכֹל בְּלִי בְּרָכָה","לְבָרֵךְ בְּקוֹל, וּלְהַצִּיעַ לוֹ בַּעֲדִינוּת לַעֲנוֹת אָמֵן","לְהַגִּישׁ לוֹ, וְלֹא לְהִתְעָרֵב כְּלָל בְּעִנְיַן הַבְּרָכוֹת"],2,"הַמְּכַבֵּד בְּאֹכֶל אַחְרַאי לְכָךְ שֶׁהָאוֹרֵחַ יְבָרֵךְ, וְרֹב הָאוֹרְחִים שְׂמֵחִים לְבָרֵךְ אוֹ לַעֲנוֹת אָמֵן. אֲבָל אָסוּר לְהַעֲלִיב – עֶלְבּוֹן עָלוּל לְהַרְחִיק אוֹתוֹ מִתּוֹרָה וּמִצְווֹת.","פֶּרֶק י״ב, הֲלָכָה י״ב","בְּרָכָה בִּמְקוֹמָהּ וְשֻׁלְחָן שֶׁל חֶסֶד"],["בְּסוֹף הָאֲרוּחָה שְׁמוּאֵל רוֹצֶה עוֹד מָנָה, אַף שֶׁכְּבָר אָכַל הַרְבֵּה. מָה הָעֵצָה הַטּוֹבָה?",["לְהַמְתִּין כְּעֶשְׂרִים דַּקּוֹת, וְרַק אָז לְהַחְלִיט","לְסַיֵּם מַהֵר, לִפְנֵי שֶׁהַשֹּׂבַע מַגִּיעַ","לֶאֱכֹל עַד שֶׁהַבֶּטֶן מִתְמַלֵּאת לְגַמְרֵי","לְהַפְסִיק לֶאֱכֹל לְגַמְרֵי עַד מָחָר בַּבֹּקֶר"],0,"בִּזְמַן הָאֲכִילָה הַתֵּאָבוֹן נִמְשָׁךְ, וְאַחֲרֵי הַפְסָקָה הַגּוּף מַרְגִּישׁ שֹׂבַע. הָרַמְבָּ״ם כָּתַב שֶׁלֹּא אוֹכְלִים עַד שֶׁהַבֶּטֶן מִתְמַלֵּאת. וְגַם צוֹם עַד מָחָר אֵינוֹ הַדֶּרֶךְ – לֹא מְצַעֲרִים אֶת הַגּוּף.","פֶּרֶק י״ג, הֲלָכָה ט׳","בְּרָכָה בִּמְקוֹמָהּ וְשֻׁלְחָן שֶׁל חֶסֶד"],["בְּאֶמְצַע הַשֻּׁלְחָן קְעָרַת חוּמוּס גְּדוֹלָה. מָתַי מֻתָּר לִטְבֹּל בָּהּ אֶת הַפִּתָּה?",["תָּמִיד, כִּי כָּךְ נוֹהֲגִים בְּהַרְבֵּה מִשְׁפָּחוֹת","רַק אִם הַפִּתָּה שֶׁלּוֹ עוֹד לֹא נְגוּסָה","כְּשֶׁאַף אֶחָד מֵהַיּוֹשְׁבִים לֹא נִגְעָל מִזֶּה","אַף פַּעַם, כִּי זֶה תָּמִיד נֶחְשָׁב מַגְעִיל"],2,"יֵשׁ חֲבוּרוֹת שֶׁרְגִילוֹת לִטְבֹּל בַּקְּעָרָה הַמְּשֻׁתֶּפֶת, וְאָז אֵין בָּזֶה אִסּוּר. אֲבָל אִם יֵשׁ שָׁם מִי שֶׁנִּגְעָל – נִמְנָעִים, כְּדֵי לֹא לְצַעֵר אוֹתוֹ.","פֶּרֶק י״ג, הֲלָכָה ו׳","בְּרָכָה בִּמְקוֹמָהּ וְשֻׁלְחָן שֶׁל חֶסֶד"],["מִצְוַת מֵאָה בְּרָכוֹת בְּכָל יוֹם – לָמָּה נָשִׁים אֵינָן חַיָּבוֹת בָּהּ?",["כִּי נָשִׁים אֵינָן מְבָרְכוֹת בִּרְכוֹת הַנֶּהֱנִין עַל אֹכֶל","כִּי הֵן פְּטוּרוֹת מִשָּׁלֹשׁ תְּפִלּוֹת בְּכָל יוֹם","כִּי דָּוִד הַמֶּלֶךְ תִּקֵּן אֶת הַמִּצְוָה רַק לַכֹּהֲנִים","כִּי הֵן חַיָּבוֹת רַק בְּשִׁבְעִים בְּרָכוֹת בְּכָל יוֹם"],1,"הַגְּבָרִים מַגִּיעִים לְמֵאָה בְּרָכוֹת בְּעִקָּר בִּזְכוּת שָׁלֹשׁ הַתְּפִלּוֹת. נָשִׁים פְּטוּרוֹת מִשָּׁלֹשׁ תְּפִלּוֹת בְּכָל יוֹם, וּמִמֵּילָא אֵין בְּיָדָן לְהַגִּיעַ לְמֵאָה בְּרָכוֹת. וְכַמּוּבָן – גַּם הֵן מְבָרְכוֹת עַל הָאֹכֶל.","פֶּרֶק י״ב, הֲלָכָה ה׳","בְּרָכָה בִּמְקוֹמָהּ וְשֻׁלְחָן שֶׁל חֶסֶד"],["דָּנִי שׁוֹמֵעַ בָּרַדְיוֹ, בְּשִׁדּוּר חַי, חַזָּן שֶׁמְּסַיֵּם בְּרָכָה. מָה הַדִּין?",["חַיָּב לַעֲנוֹת אָמֵן, כְּמוֹ בְּבֵית הַכְּנֶסֶת מַמָּשׁ","אָסוּר לוֹ לַעֲנוֹת אָמֵן עַל קוֹל שֶׁל מַכְשִׁיר","יַעֲנֶה אָמֵן רַק אִם רָאָה אֶת הַחַזָּן בַּמָּסָךְ","טוֹב שֶׁיַּעֲנֶה אָמֵן, אֲבָל אֵינוֹ חַיָּב"],3,"הַשּׁוֹמֵעַ בְּרָכָה דֶּרֶךְ טֶלֶפוֹן אוֹ רַדְיוֹ בְּשִׁדּוּר חַי – טוֹב שֶׁיַּעֲנֶה אָמֵן, אֲבָל אֵינוֹ חַיָּב. וְעַל בְּרָכוֹת וְקַדִּישׁ שֶׁשּׁוֹמְעִים בְּרַמְקוֹל – עוֹנִים אָמֵן.","פֶּרֶק י״ב, הֲלָכָה ט׳","בְּרָכָה בִּמְקוֹמָהּ וְשֻׁלְחָן שֶׁל חֶסֶד"],["הַדּוֹד שֶׁל אֶלְחָנָן אֵרַח אוֹתוֹ, וְאֶלְחָנָן אָכַל עַד שֶׁשָּׂבַע. הַדּוֹד מַפְצִיר: ״קַח עוֹד מָנָה!״ מָה הַדִּין?",["חַיָּב לֶאֱכֹל, כִּי כָּל מָה שֶׁאוֹמֵר בַּעַל הַבַּיִת עוֹשִׂים","אֵינוֹ חַיָּב, כִּי כְּבָר אָכַל וְשָׂבַע מִסְּעוּדָתוֹ","יֹאכַל עוֹד, אַחֶרֶת הַדּוֹד יַחְשֹׁב שֶׁהָאֹכֶל לֹא טָעִים","יַפְסִיק, כִּי אָסוּר לְאוֹרֵחַ לֶאֱכֹל יוֹתֵר מִמָּנָה אַחַת"],1,"הָאוֹרֵחַ שׁוֹמֵעַ בְּקוֹל בַּעַל הַבַּיִת – אֲבָל מִי שֶׁכְּבָר אָכַל וְשָׂבַע, אֵינוֹ חַיָּב לְהַמְשִׁיךְ לֶאֱכֹל. בַּעַל הַבַּיִת אֵינוֹ צָרִיךְ לְהִתְבַּיֵּשׁ, כִּי הָאוֹרֵחַ כְּבָר שָׂבַע מִסְּעוּדָתוֹ. וְאֶפְשָׁר לְסָרֵב בְּנִימוּס וּבְתוֹדָה.","פֶּרֶק י״ג, הֲלָכָה ב׳","בְּרָכָה בִּמְקוֹמָהּ וְשֻׁלְחָן שֶׁל חֶסֶד"],["בַּחֲתֻנָּה שֶׁל הַדּוֹד רוֹצֶה מֵאִיר לְצַלֵּם בַּטֶּלֶפוֹן אֶת סָבָא בְּדִיּוּק כְּשֶׁהוּא נוֹגֵס בְּעוֹף. מָה נָכוֹן?",["לֹא יְצַלֵּם אוֹתוֹ בִּזְמַן הָאֲכִילָה, אֶלָּא אִם הִסְכִּים","מֻתָּר לְצַלֵּם, כִּי סָבָא הוּא בֶּן מִשְׁפָּחָה קָרוֹב","מֻתָּר לְצַלֵּם, אִם לֹא יַרְאֶה אֶת הַתְּמוּנָה לְאַף אֶחָד","יְצַלֵּם, כִּי בְּשִׂמְחָה מְשֻׁתֶּפֶת כָּל הַתְּמוּנוֹת מֻתָּרוֹת"],0,"אָדָם שֶׁאוֹכֵל עָלוּל לְהִתְבַּיֵּשׁ כְּשֶׁמִּסְתַּכְּלִים עָלָיו, וְקַל וָחֹמֶר כְּשֶׁמְּצַלְּמִים אוֹתוֹ. לָכֵן אֵין לְצַלֵּם אָדָם בִּזְמַן שֶׁהוּא אוֹכֵל, בְּלִי שֶׁהִסְכִּים.","פֶּרֶק י״ג, הֲלָכָה ז׳","בְּרָכָה בִּמְקוֹמָהּ וְשֻׁלְחָן שֶׁל חֶסֶד"],["בְּאֶמְצַע טֶקֶס בְּבֵית הַסֵּפֶר, כְּשֶׁיּוֹסֵף עוֹמֵד עַל הַבָּמָה מוּל כָּל הַהוֹרִים, הוּא מַרְגִּישׁ שֶׁהוּא צָרִיךְ לְבֵית הַכִּסֵּא. הַיְּצִיאָה תְּבַיֵּשׁ אוֹתוֹ מְאוֹד. מָה הַדִּין?",["חַיָּב לָצֵאת מִיָּד, כִּי אָסוּר בְּשׁוּם אֹפֶן לְהִתְאַפֵּק","מֻתָּר לוֹ לְחַכּוֹת, כִּי כְּבוֹד הַבְּרִיּוֹת דּוֹחֶה אֶת הָאִסּוּר","מֻתָּר לְחַכּוֹת רַק אִם הַמּוֹרֶה נוֹתֵן לוֹ רְשׁוּת","יֵצֵא, כִּי הַבְּרִיאוּת חֲשׁוּבָה יוֹתֵר מֵהַבּוּשָׁה שֶׁלּוֹ"],1,"הַמִּתְאַפֵּק כְּשֶׁהוּא צָרִיךְ מְאוֹד עוֹבֵר עַל ״בַּל תְּשַׁקְּצוּ״. אֲבָל כְּשֶׁהַיְּצִיאָה תִּגְרֹם לוֹ בּוּשָׁה גְּדוֹלָה – לְכָל הַדֵּעוֹת מֻתָּר לוֹ לְחַכּוֹת עוֹד, כִּי גָּדוֹל כְּבוֹד הַבְּרִיּוֹת. וּכְשֶׁהַטֶּקֶס יִגָּמֵר – יֵלֵךְ מִיָּד.","פֶּרֶק י״ג, הֲלָכָה י״ג","בְּרָכָה בִּמְקוֹמָהּ וְשֻׁלְחָן שֶׁל חֶסֶד"],["אֲרִיאֵל גָּר עַל חוֹף הַיָּם הַתִּיכוֹן. הַחֹדֶשׁ הָיָה עָסוּק, וְלֹא הִבִּיט בַּיָּם שְׁלוֹשִׁים יוֹם. כְּשֶׁיִּרְאֶה אוֹתוֹ – מָה הַדִּין?",["יְבָרֵךְ, כִּי עָבְרוּ שְׁלוֹשִׁים יוֹם מֵהַפַּעַם הָאַחֲרוֹנָה","לֹא יְבָרֵךְ, כִּי הַיָּם קָרוֹב וְרָגִיל לוֹ","יְבָרֵךְ בְּלִי שֵׁם וּמַלְכוּת, מִפְּנֵי הַסָּפֵק","יְבָרֵךְ רַק כְּשֶׁיֵּלֵךְ לְחוֹף אַחֵר שֶׁל הַיָּם"],1,"מִי שֶׁגָּר לְיַד הַיָּם יָכוֹל לִרְאוֹת אוֹתוֹ בְּקַלּוּת, וְאֵין לוֹ חִדּוּשׁ בָּרְאִיָּה – גַּם לֹא מֵחוֹף אַחֵר. רַק אִם עָזַב אֶת מְקוֹמוֹ לִשְׁלוֹשִׁים יוֹם וְחָזַר – יְבָרֵךְ.","פֶּרֶק ט״ו, הֲלָכָה ד׳","רֵיחַ טוֹב וּמַרְאוֹת נִפְלָאִים"],["עַל אֵיזֶה מָקוֹם לֹא מְבָרְכִים ״עוֹשֶׂה מַעֲשֵׂה בְרֵאשִׁית״?",["עַל יָם הַמֶּלַח, שֶׁיֵּשׁ בּוֹ מַיִם כָּל הַשָּׁנָה","עַל הַכִּנֶּרֶת, כְּשֶׁבָּאִים אֵלֶיהָ לְטִיּוּל אַחֲרֵי חָדְשַׁיִם","עַל הַר תָּבוֹר, כְּשֶׁמְּטַיְּלִים בּוֹ וּמִתְפַּעֲלִים מִמֶּנּוּ","עַל אֲגַם עֲנָק שֶׁבְּנֵי אָדָם יָצְרוּ בְּסֶכֶר"],3,"הַבְּרָכָה הִיא שֶׁבַח לְמַעֲשֵׂה הַבּוֹרֵא, וְלֹא לְמַעֲשֵׂה בְּנֵי אָדָם. לָכֵן עַל אֲגַם שֶׁנּוֹצַר מִסֶּכֶר לֹא מְבָרְכִים, גַּם אִם הוּא עֲנָק. עַל יָם הַמֶּלַח, הַכִּנֶּרֶת וְהַר תָּבוֹר – מְבָרְכִים.","פֶּרֶק ט״ו, הֲלָכָה ב׳","רֵיחַ טוֹב וּמַרְאוֹת נִפְלָאִים"],["בְּאֶמְצַע סוּפָה רָאָה עוֹבַדְיָה בָּרָק וּבֵרַךְ. אַחַר כָּךְ רָאָה עוֹד הַרְבֵּה בְּרָקִים מֵאוֹתָם עֲנָנִים. מָה יַעֲשֶׂה?",["לֹא יְבָרֵךְ שׁוּב, כִּי אֵלּוּ אוֹתָם עֲנָנִים","יְבָרֵךְ עַל כָּל בָּרָק, כִּי כָּל אֶחָד חָדָשׁ","יְבָרֵךְ שׁוּב רַק עַל בָּרָק חָזָק בִּמְיֻחָד","יְבָרֵךְ שׁוּב רַק אַחֲרֵי שְׁלוֹשִׁים יוֹם"],0,"כָּל הַבְּרָקִים שֶׁל אוֹתָהּ מַעֲרֶכֶת עֲנָנִים יוֹצְאִים בִּבְרָכָה אַחַת. לְמָחֳרָת, אוֹ כְּשֶׁהַשָּׁמַיִם הִתְבַּהֲרוּ וּבָאוּ עֲנָנִים חֲדָשִׁים – מְבָרְכִים שׁוּב.","פֶּרֶק ט״ו, הֲלָכָה ז׳","רֵיחַ טוֹב וּמַרְאוֹת נִפְלָאִים"],["אֶחָד מִגְּדוֹלֵי הַתּוֹרָה שֶׁל הַדּוֹר בִּקֵּר בַּיְּשִׁיבָה. מָה מְבָרְכִים כְּשֶׁרוֹאִים אוֹתוֹ?",["״שֶׁנָּתַן מֵחָכְמָתוֹ לְבָשָׂר וָדָם״, כְּמוֹ עַל כָּל חָכָם","״חֲכַם הָרָזִים״, כִּי הוּא מְלַמֵּד אֶת כָּל הָעָם","״שֶׁחָלַק מֵחָכְמָתוֹ לִירֵאָיו״, כִּי לוֹ חֵלֶק בַּתּוֹרָה","״שֶׁחָלַק מִכְּבוֹדוֹ לִירֵאָיו״, כְּמוֹ עַל מֶלֶךְ יִשְׂרָאֵל"],2,"עַל חַכְמֵי הַתּוֹרָה – ״שֶׁחָלַק מֵחָכְמָתוֹ לִירֵאָיו״: יֵשׁ לָהֶם חֵלֶק עִם ה׳ בַּתּוֹרָה, וְיִרְאַת שָׁמַיִם הִיא תְּנַאי לְהָבִין אוֹתָהּ. ״שֶׁנָּתַן מֵחָכְמָתוֹ לְבָשָׂר וָדָם״ – עַל חַכְמֵי הָעַמִּים.","פֶּרֶק ט״ו, הֲלָכָה י״ח","רֵיחַ טוֹב וּמַרְאוֹת נִפְלָאִים"],["לְאַבָּא שֶׁל אֵלִי נַעֲשָׂה נֵס גָּדוֹל, וְהוּא נִצַּל מִסַּכָּנָה. כְּשֶׁאֵלִי מַגִּיעַ לַמָּקוֹם – מָה הַדִּין?",["אֵלִי לֹא מְבָרֵךְ, כִּי הַנֵּס נַעֲשָׂה לְאַבָּא","גַּם אֵלִי מְבָרֵךְ, כְּמוֹ אָבִיו, עַל הַנֵּס","אֵלִי מְבָרֵךְ רַק אִם הָיָה שָׁם בִּזְמַן הַנֵּס","רַק אַבָּא מְבָרֵךְ, וְאֵלִי עוֹנֶה אַחֲרָיו אָמֵן"],1,"כְּמוֹ שֶׁבַּעַל הַנֵּס מְבָרֵךְ כְּשֶׁהוּא רוֹאֶה אֶת הַמָּקוֹם, כָּךְ גַּם בָּנָיו וּנְכָדָיו – כִּי הַנֵּס שֶׁל אַבָּא הוּא גַּם הַחַיִּים שֶׁלָּהֶם.","פֶּרֶק ט״ו, הֲלָכָה כ״ה","רֵיחַ טוֹב וּמַרְאוֹת נִפְלָאִים"],["שִׁמְעוֹן בֵּרֵךְ ״בּוֹרֵא עֲצֵי בְשָׂמִים״ עַל הֲדַס. לִפְנֵי שֶׁהֵרִיחַ, עָנָה לְחָבֵר עַל שְׁאֵלָה. מָה יַעֲשֶׂה?",["יָרִיחַ מִיָּד, כִּי הַבְּרָכָה כְּבָר נֶאֶמְרָה","יֹאמַר ״בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ״ וְיָרִיחַ","לֹא יָרִיחַ הַיּוֹם, כְּדֵי שֶׁלֹּא יְבָרֵךְ פַּעֲמַיִם","יְבָרֵךְ שׁוּב, כִּי הַדִּבּוּר הִפְסִיק בָּאֶמְצַע"],3,"דִּבּוּר בֵּין הַבְּרָכָה לַהֲנָאָה מַפְסִיק, וְהַבְּרָכָה הָרִאשׁוֹנָה כְּבָר לֹא מוֹעִילָה. לָכֵן מְבָרֵךְ שׁוּב, וּמֵרִיחַ מִיָּד.","פֶּרֶק י״ד, הֲלָכָה ו׳","רֵיחַ טוֹב וּמַרְאוֹת נִפְלָאִים"],["אָבִיתָר קָטַף עָלֶה שֶׁל נַעֲנָע כְּדֵי לְהָרִיחַ אוֹתוֹ. אֵיזוֹ בְּרָכָה עָדִיף שֶׁיְּבָרֵךְ?",["״עִשְׂבֵי בְשָׂמִים״, כִּי הַנַּעֲנָע הִיא צֶמַח רַךְ וְקָטָן","״מִינֵי בְשָׂמִים״, כִּי יֵשׁ סָפֵק בְּסוּגָהּ","״עֲצֵי בְשָׂמִים״, כִּי הִיא גְּדֵלָה בַּגִּנָּה כָּל הַשָּׁנָה","״הַנּוֹתֵן רֵיחַ טוֹב בַּפֵּרוֹת״, כִּי שָׂמִים אוֹתָהּ בַּתֵּה"],1,"עַל נַעֲנָע הִסְתַּפְּקוּ אִם הִיא עֵץ אוֹ עֵשֶׂב, וְלָכֵן עָדִיף לְבָרֵךְ \"מִינֵי בְשָׂמִים\" – בְּרָכָה שֶׁמּוֹעִילָה לְכָל רֵיחַ. מִי שֶׁטּוֹעֶה בֵּין עֵץ לְעֵשֶׂב – לֹא יָצָא.","פֶּרֶק י״ד, הֲלָכָה ה׳","רֵיחַ טוֹב וּמַרְאוֹת נִפְלָאִים"],["שִׁירָה מְבַשֶּׂמֶת אֶת עַצְמָהּ לִפְנֵי שִׂמְחָה מִשְׁפַּחְתִּית. עַל אֵיזֶה רֵיחַ הִיא מְבָרֶכֶת?",["עַל הָרֵיחַ שֶׁנּוֹדֵף מִמֶּנָּה אַחֲרֵי שֶׁהִתְבַּשְּׂמָה","עַל שׁוּם רֵיחַ, כִּי בֹּשֶׂם נוֹעַד לְבַשֵּׂם אֶת הַגּוּף","עַל הָרֵיחַ שֶׁנִּשְׁאָר בַּבְּגָדִים שֶׁלָּהּ כָּל הַיּוֹם","עַל הָרֵיחַ שֶׁיּוֹצֵא מִבַּקְבּוּק הַבֹּשֶׂם עַצְמוֹ"],3,"בֹּשֶׂם נוֹעַד לֵהָנוֹת מֵרֵיחוֹ, וְלָכֵן מְבָרְכִים עָלָיו. הַמִּתְבַּשֶּׂמֶת מְבָרֶכֶת עַל הָרֵיחַ שֶׁיּוֹצֵא מִן הַבַּקְבּוּק. עַל רֵיחַ שֶׁנּוֹדֵף מֵאָדָם אוֹ מִבְּגָדִים – לֹא מְבָרְכִים, כִּי אֵין לוֹ עִקָּר.","פֶּרֶק י״ד, הֲלָכָה ג׳","רֵיחַ טוֹב וּמַרְאוֹת נִפְלָאִים"],["אַחֲרֵי חֹרֶף שֶׁל בַּצֹּרֶת הִתְחִיל סוֹף סוֹף לָרֶדֶת גֶּשֶׁם. מָתַי אוֹמְרִים אֶת בִּרְכַּת הַהוֹדָאָה עַל הַגְּשָׁמִים?",["כְּשֶׁהַגֶּשֶׁם חָזָק וְהַטִּפּוֹת קוֹפְצוֹת מִן הַשְּׁלוּלִיּוֹת","מִיָּד כְּשֶׁנּוֹפֶלֶת הַטִּפָּה הָרִאשׁוֹנָה מִן הַשָּׁמַיִם","רַק אַחֲרֵי שֶׁכָּל הַמַּאֲגָרִים וְהַכִּנֶּרֶת מִתְמַלְּאִים","רַק כְּשֶׁיּוֹרֵד גֶּשֶׁם בַּיּוֹם הָרִאשׁוֹן שֶׁל הַחֹרֶף"],0,"חֲכָמִים אָמְרוּ: מְבָרְכִים כְּשֶׁהַטִּפּוֹת יוֹצְאוֹת ״כְּחָתָן לִקְרַאת כַּלָּה״ – כְּשֶׁהַגֶּשֶׁם מַכֶּה בַּמַּיִם וְהֵם קוֹפְצִים לְמַעְלָה. לֹא צָרִיךְ לְחַכּוֹת שֶׁהָאֲדָמָה תִּרְוֶה.","פֶּרֶק ט״ו, הֲלָכָה ט׳","רֵיחַ טוֹב וּמַרְאוֹת נִפְלָאִים"],["עֲזַרְיָה רָאָה הַר גָּבוֹהַּ וּמְיֻחָד רַק דֶּרֶךְ טֶלֶסְקוֹפּ בַּמִּצְפֶּה. הַאִם יְבָרֵךְ ״עוֹשֶׂה מַעֲשֵׂה בְרֵאשִׁית״?",["כֵּן, כִּי הוּא רָאָה אֶת הָהָר הֵיטֵב וּבְבֵרוּר","לֹא, כִּי רְאִיָּה בְּטֶלֶסְקוֹפּ אֵינָהּ כִּרְאִיָּה מַמָּשִׁית","כֵּן, כְּמוֹ מִי שֶׁרוֹאֶה אֶת הָהָר בְּמִשְׁקָפַיִם","יְבָרֵךְ רַק אִם יִרְאֶה אֶת הָהָר גַּם בְּסֶרֶט"],1,"רְאִיָּה בִּתְמוּנָה, בְּסֶרֶט אוֹ בְּטֶלֶסְקוֹפּ אֵינָהּ מְעוֹרֶרֶת הִתְפַּעֲלוּת כְּמוֹ רְאִיָּה מַמָּשִׁית, וְלָכֵן אֵין מְבָרְכִים. אֲבָל הָרוֹאֶה בְּמִשְׁקָפַיִם נֶחְשָׁב כְּרוֹאֶה רָגִיל.","פֶּרֶק ט״ו, הֲלָכָה א׳","רֵיחַ טוֹב וּמַרְאוֹת נִפְלָאִים"],["מֵהַמִּצְפֶּה רָאוּ אֶלְיָקִים וְאָבִיו יַחַד אֶת הַכִּנֶּרֶת וְאֶת צוּקֵי הַר אַרְבֵּל, וְלֹא רָאוּ אוֹתָם שְׁלֹשִׁים יוֹם. כַּמָּה פְּעָמִים יְבָרְכוּ?",["פַּעַם אַחַת, כִּי הֵם רוֹאִים אֶת שְׁנֵיהֶם יַחַד","פַּעֲמַיִם, כִּי עַל כָּל נוֹף מְבָרְכִים בְּרָכָה בִּפְנֵי עַצְמָהּ","פַּעַם אַחַת, וְרַק עַל הַכִּנֶּרֶת שֶׁהִיא הַחֲשׁוּבָה","לֹא יְבָרְכוּ, כִּי עַל צוּקִים אֵין מְבָרְכִים בִּכְלָל"],0,"הָרוֹאֶה כַּמָּה נוֹפִים מְיֻחָדִים יַחַד – מְבָרֵךְ עַל כֻּלָּם בְּרָכָה אַחַת. אֲבָל אִם הָיוּ רוֹאִים אוֹתָם בְּזֶה אַחַר זֶה, בִּמְקוֹמוֹת שׁוֹנִים – הָיוּ מְבָרְכִים עַל כָּל אֶחָד בִּנְפָרָד.","פֶּרֶק ט״ו, הֲלָכָה ג׳","רֵיחַ טוֹב וּמַרְאוֹת נִפְלָאִים"],["בְּגַן הַחַיּוֹת רָאָה נְתַנְאֵל תֻּכִּי צִבְעוֹנִי וּמַרְהִיב, וּבֵרַךְ. אַחַר כָּךְ, בְּפִנָּה אַחֶרֶת, רָאָה טַוָּס נָאֶה בִּמְיֻחָד. מָה הַדִּין?",["לֹא יְבָרֵךְ, כִּי כְּבָר בֵּרַךְ הַיּוֹם עַל עוֹף נָאֶה","יְבָרֵךְ שׁוּב, כִּי עַל כָּל בְּרִיָּה מְבָרְכִים בִּפְנֵי עַצְמָהּ","יְבָרֵךְ רַק אַחֲרֵי שְׁלֹשִׁים יוֹם מִן הַבְּרָכָה הָרִאשׁוֹנָה","לֹא יְבָרֵךְ, כִּי בְּגַן חַיּוֹת אֵין מְבָרְכִים עַל עוֹפוֹת"],1,"עַל כָּל בְּרִיָּה נָאָה בִּמְיֻחָד מְבָרְכִים בְּרָכָה בִּפְנֵי עַצְמָהּ, וַאֲפִלּוּ אִם רוֹאִים אֶת כֻּלָּן בְּיוֹם אֶחָד. רַק אִם רוֹאִים שְׁנֵי מִינִים יַחַד – בְּרָכָה אַחַת עוֹלָה לִשְׁנֵיהֶם.","פֶּרֶק ט״ו, הֲלָכוֹת י״ב–י״ג","רֵיחַ טוֹב וּמַרְאוֹת נִפְלָאִים"],["אַבָּא שֶׁל אֲבִיגְדוֹר הִבְרִיא לְגַמְרֵי מִמַּחֲלָה מְסֻכֶּנֶת בְּיוֹם שֵׁנִי. קְרִיאַת הַתּוֹרָה הַבָּאָה הִיא בְּיוֹם חֲמִישִׁי. מָה נָכוֹן לַעֲשׂוֹת?",["לְבָרֵךְ \"הַגּוֹמֵל\" עַד יוֹם רְבִיעִי, בְּתוֹךְ שְׁלֹשָׁה יָמִים","לְהַמְתִּין לְיוֹם חֲמִישִׁי כְּדֵי לְבָרֵךְ סָמוּךְ לִקְרִיאַת הַתּוֹרָה","לְבָרֵךְ רַק בְּשַׁבָּת, כְּשֶׁכָּל הַקָּהָל נִמְצָא בְּבֵית הַכְּנֶסֶת","כְּבָר אִי אֶפְשָׁר לְבָרֵךְ, כִּי עָבַר יוֹתֵר מִיּוֹם אֶחָד"],0,"נָכוֹן לְבָרֵךְ בְּתוֹךְ שְׁלֹשָׁה יָמִים, וְלֹא מְחַכִּים לִקְרִיאַת הַתּוֹרָה אִם הִיא אַחֲרֵיהֶם. וּבְדִיעֲבַד – גַּם אַחֲרֵי זְמַן רַב לֹא הִפְסִיד אֶת הַבְּרָכָה.","פֶּרֶק ט״ז, הֲלָכָה ג׳","תּוֹדָה עַל כָּל טוֹבָה"],["בְּטִיּוּל עָבַר אַבָּא שֶׁל מֵאִיר לְיַד נָחָשׁ. הוּא נִבְהַל מְאוֹד, אֲבָל הַנָּחָשׁ לֹא הִתְקָרֵב אֵלָיו. הַאִם יְבָרֵךְ \"הַגּוֹמֵל\"?",["כֵּן, כִּי הוּא נִבְהַל מְאוֹד וְהִרְגִּישׁ שֶׁהוּא בְּסַכָּנָה","לֹא, כִּי בְּפֹעַל הוּא לֹא נִכְנַס לְסַכָּנָה","כֵּן, כִּי כָּל מִי שֶׁרָאָה נָחָשׁ בַּשֶּׁטַח מְבָרֵךְ","לֹא, כִּי עַל נְחָשִׁים מְבָרְכִים רַק בְּמִדְבָּר רָחוֹק"],1,"\"הַגּוֹמֵל\" מְבָרְכִים עַל הַצָּלָה מִסַּכָּנָה אֲמִתִּית, וְלֹא עַל פַּחַד בִּלְבַד. מִי שֶׁהַנָּחָשׁ הִכִּישׁ אוֹתוֹ וְנִרְפָּא – מְבָרֵךְ.","פֶּרֶק ט״ז, הֲלָכָה ח׳","תּוֹדָה עַל כָּל טוֹבָה"],["יְהוּדָה אֵינוֹ בָּטוּחַ אִם עָלָיו לְבָרֵךְ \"שֶׁהֶחֱיָנוּ\" אוֹ \"הַטּוֹב וְהַמֵּטִיב\". מָה יַעֲשֶׂה?",["יְבָרֵךְ \"הַטּוֹב וְהַמֵּטִיב\", כִּי הִיא הַבְּרָכָה הַגְּדוֹלָה יוֹתֵר","יְבָרֵךְ \"שֶׁהֶחֱיָנוּ\", כִּי הִיא מוֹעִילָה גַּם בִּמְקוֹם הַשְּׁנִיָּה","יְבָרֵךְ אֶת שְׁתֵּיהֶן, זוֹ אַחַר זוֹ, כְּדֵי לָצֵאת מִסָּפֵק","לֹא יְבָרֵךְ כְּלָל, כִּי בְּסָפֵק אֵין מְבָרְכִים"],1,"מִי שֶׁהָיָה צָרִיךְ לְבָרֵךְ \"הַטּוֹב וְהַמֵּטִיב\" וּבֵרֵךְ \"שֶׁהֶחֱיָנוּ\" – יָצָא, כִּי הוֹדָה עַל הַטּוֹבָה. אֲבָל מִי שֶׁבֵּרֵךְ \"הַטּוֹב וְהַמֵּטִיב\" עַל שִׂמְחָה שֶׁל יָחִיד – לֹא יָצָא.","פֶּרֶק י״ז, הֲלָכָה ג׳","תּוֹדָה עַל כָּל טוֹבָה"],["נְתַנְאֵל קִוָּה לִזְכּוֹת בִּפְרָס כַּסְפִּי גָּדוֹל, וְנוֹדַע לוֹ שֶׁלֹּא זָכָה. הוּא עָצוּב. הַאִם יְבָרֵךְ \"דַּיַּן הָאֱמֶת\"?",["כֵּן, כִּי עַל כָּל שְׁמוּעָה מַעֲצִיבָה מְבָרְכִים","לֹא, כִּי הוּא לֹא הִפְסִיד דָּבָר שֶׁהָיָה שֶׁלּוֹ","כֵּן, אֲבָל רַק אִם הַפְּרָס הָיָה גָּדוֹל מְאוֹד","לֹא, כִּי מְבָרְכִים אוֹתָהּ רַק עַל צָרָה בַּמִּשְׁפָּחָה"],1,"\"דַּיַּן הָאֱמֶת\" מְבָרְכִים עַל דָּבָר רַע שֶׁקָּרָה בְּפֹעַל, כְּמוֹ הֶפְסֵד שֶׁל מַה שֶּׁהָיָה שַׁיָּךְ לוֹ. מִי שֶׁרַק לֹא הִרְוִיחַ – לֹא הִפְסִיד דָּבָר.","פֶּרֶק י״ז, הֲלָכָה ח׳","תּוֹדָה עַל כָּל טוֹבָה"],["אֶלְיָשִׁיב לֹא רָאָה אֶת חֲבֵרוֹ הַטּוֹב חֳדָשִׁים רַבִּים, אֲבָל בַּחֹדֶשׁ הָאַחֲרוֹן שׂוֹחֲחוּ שִׂיחָה אִישִׁית בַּטֶּלֶפוֹן. כְּשֶׁנִּפְגְּשׁוּ – מָה הַדִּין?",["לֹא יְבָרֵךְ, כִּי הַשִּׂיחָה בַּטֶּלֶפוֹן חִדְּשָׁה אֶת הַקֶּשֶׁר","יְבָרֵךְ, כִּי בַּטֶּלֶפוֹן אִי אֶפְשָׁר לִרְאוֹת אֶת הֶחָבֵר","יְבָרֵךְ רַק אִם בֵּינְתַיִם שָׁלְחוּ זֶה לָזֶה מִכְתָּבִים","לֹא יְבָרֵךְ, כִּי עַל חָבֵר מְבָרְכִים רַק אַחֲרֵי שָׁנָה"],0,"שִׂיחָה אִישִׁית בַּטֶּלֶפוֹן בְּתוֹךְ שְׁלֹשִׁים הַיָּמִים מְבַטֶּלֶת אֶת הַחִדּוּשׁ שֶׁבַּפְּגִישָׁה. מִכְתָּב – לֹא מְבַטֵּל, וּמְבָרְכִים.","פֶּרֶק י״ז, הֲלָכָה י״א","תּוֹדָה עַל כָּל טוֹבָה"],["לִכְבוֹד בַּר הַמִּצְוָה קָנָה שְׁלֹמֹה חֲלִיפָה, אֲבָל צָרִיךְ לְקַצֵּר אֶת שַׁרְווּלֶיהָ. מָתַי יְבָרֵךְ \"שֶׁהֶחֱיָנוּ\"?",["מִיָּד בַּחֲנוּת, בִּשְׁעַת הַקְּנִיָּה וְהַתַּשְׁלוּם","כְּשֶׁיִּלְבַּשׁ אוֹתָהּ לָרִאשׁוֹנָה, אַחֲרֵי הַתִּקּוּן","כְּשֶׁיִּמְסֹר אוֹתָהּ לַחַיָּט לְקַצֵּר אֶת הַשַּׁרְווּלִים","בַּפַּעַם הַשְּׁנִיָּה שֶׁיִּלְבַּשׁ, אַחֲרֵי שֶׁיִּתְרַגֵּל אֵלֶיהָ"],1,"בֶּגֶד שֶׁעוֹד אֵינוֹ רָאוּי לִלְבִישָׁה – מְבָרְכִים עָלָיו בַּלְּבִישָׁה הָרִאשׁוֹנָה, כִּי אָז שְׂמֵחִים בּוֹ בֶּאֱמֶת.","פֶּרֶק י״ז, הֲלָכָה ו׳","תּוֹדָה עַל כָּל טוֹבָה"],["אִשָּׁה נִצְּלָה מִתְּאוּנָה מְסֻכֶּנֶת, וְהִיא רוֹצָה לְבָרֵךְ \"הַגּוֹמֵל\". אֵיךְ תַּעֲשֶׂה זֹאת?",["תְּבָרֵךְ לְבַד בַּבַּיִת, כִּי נָשִׁים אֵינָן צְרִיכוֹת מִנְיָן","תְּבָרֵךְ מֵעֶזְרַת הַנָּשִׁים, וְהַקָּהָל יַעֲנֶה אַחֲרֶיהָ אָמֵן","תְּבַקֵּשׁ מֵחֲבֵרָה לְבָרֵךְ בִּשְׁבִילָהּ אֶת הַבְּרָכָה בַּבַּיִת","לֹא תְּבָרֵךְ כְּלָל, כִּי נָשִׁים פְּטוּרוֹת מִבִּרְכַּת הַגּוֹמֵל"],1,"\"הַגּוֹמֵל\" מְבָרְכִים בִּפְנֵי מִנְיָן. אִשָּׁה שֶׁחַיֶּבֶת – מוֹדִיעָה לַגַּבַּאי, וּמֵעֶזְרַת הַנָּשִׁים מְבָרֶכֶת בִּפְנֵי הַקָּהָל, שֶׁעוֹנֶה אַחֲרֶיהָ. וְאִם הִזְדַּמְּנוּ עֲשָׂרָה בְּמָקוֹם אַחֵר – מְבָרֶכֶת שָׁם.","פֶּרֶק ט״ז, הֲלָכָה ה׳","תּוֹדָה עַל כָּל טוֹבָה"],["נוֹעָה, בַּת שֶׁבַע, קִבְּלָה שִׂמְלַת שַׁבָּת חֲדָשָׁה, וְהִיא וְהוֹרֶיהָ שְׂמֵחִים בָּהּ. מִי מְבָרֵךְ, וּמָה?",["נוֹעָה – \"שֶׁהֶחֱיָנוּ\", וְהַהוֹרִים – \"הַטּוֹב וְהַמֵּטִיב\"","רַק הַהוֹרִים מְבָרְכִים \"שֶׁהֶחֱיָנוּ\", כִּי הֵם קָנוּ אוֹתָהּ","כֻּלָּם יַחַד מְבָרְכִים \"שֶׁהֶחֱיָנוּ\" בְּקוֹל אֶחָד","אִישׁ אֵינוֹ מְבָרֵךְ, כִּי עַל בִּגְדֵי יְלָדִים אֵין בְּרָכָה"],0,"הַהוֹרִים, שֶׁאַחְרָאִים עַל לְבוּשׁ יַלְדָּתָם וּשְׂמֵחִים בּוֹ, מְבָרְכִים \"הַטּוֹב וְהַמֵּטִיב\". וְאֶת הַיַּלְדָּה, מִגִּיל חִנּוּךְ, מְחַנְּכִים לְבָרֵךְ \"שֶׁהֶחֱיָנוּ\" עַל בִּגְדָהּ הֶחָדָשׁ.","פֶּרֶק י״ז, הֲלָכָה ג׳","תּוֹדָה עַל כָּל טוֹבָה"],["שְׁלֹמֹה זָכָה בַּמָּקוֹם הָרִאשׁוֹן בְּחִידוֹן הַתַּנַ״ךְ הָעִירוֹנִי, וְקִבֵּל פְּרָס שֶׁל חֲמֵשׁ מֵאוֹת שְׁקָלִים. הוּא שָׂמֵחַ מְאוֹד. מָה הַדִּין?",["יְבָרֵךְ ״שֶׁהֶחֱיָנוּ״, כִּי זֶה פְּרָס מְיֻחָד וּסְכוּם חָשׁוּב בְּעֵינָיו","לֹא יְבָרֵךְ, כִּי עַל כֶּסֶף אַף פַּעַם לֹא מְבָרְכִים","יְבָרֵךְ ״הַטּוֹב וְהַמֵּטִיב״, כִּי כָּל הַמִּשְׁפָּחָה תֵּהָנֶה מִן הַכֶּסֶף","יְבָרֵךְ רַק כְּשֶׁיִּקְנֶה בַּכֶּסֶף בֶּגֶד חָדָשׁ"],0,"הַזּוֹכֶה בְּכֶסֶף מְבָרֵךְ ״שֶׁהֶחֱיָנוּ״, אִם הַסְּכוּם חָשׁוּב בְּעֵינָיו וְהוּא שָׂמֵחַ בּוֹ. לְצָעִיר שֶׁעוֹד אֵינוֹ עוֹבֵד, חֲמֵשׁ מֵאוֹת שְׁקָלִים יְכוֹלִים לִהְיוֹת סְכוּם גָּדוֹל. וּפְרָס עַל דָּבָר נָאֶה שֶׁעָשָׂה – אֵין בּוֹ בּוּשָׁה.","פֶּרֶק י״ז, הֲלָכָה ה׳","תּוֹדָה עַל כָּל טוֹבָה"],["לִכְבוֹד סִיּוּם הַשָּׁנָה קִבֵּל אֲבִיגְדוֹר חֻמָּשׁ חָדָשׁ וּמְהֻדָּר, וְהוּא שָׂמֵחַ בּוֹ מְאוֹד. לְפִי הָרַב מֶלָמֵד, מָה נָכוֹן?",["נָכוֹן לְבָרֵךְ ״שֶׁהֶחֱיָנוּ״, כִּי הַחֻמָּשׁ חָבִיב עָלָיו מְאוֹד","אָסוּר לְבָרֵךְ, כִּי עַל סֵפֶר אַף פַּעַם לֹא מְבָרְכִים","יְבָרֵךְ ״הַטּוֹב וְהַמֵּטִיב״, כִּי כָּל הַכִּתָּה קִבְּלָה חֻמָּשׁ","יְבָרֵךְ רַק כְּשֶׁיְּסַיֵּם לִלְמֹד אֶת כָּל הַחֻמָּשׁ"],0,"נֶחְלְקוּ הַפּוֹסְקִים אִם מְבָרְכִים עַל סִפְרֵי קֹדֶשׁ. לְדַעַת הָרַב מֶלָמֵד, כְּשֶׁהַסְּפָרִים חֲבִיבִים מְאוֹד וְהוּא שָׂמֵחַ בָּהֶם – נָכוֹן לְבָרֵךְ ״שֶׁהֶחֱיָנוּ״. וְיֵשׁ אוֹמְרִים שֶׁעַל סִפְרֵי קֹדֶשׁ אֵין מְבָרְכִים.","פֶּרֶק י״ז, הֲלָכָה ט׳","תּוֹדָה עַל כָּל טוֹבָה"],["נוֹלַד לְאַהֲרֹן אָח קָטָן, וְאַהֲרֹן שָׂמֵחַ מְאוֹד. כְּשֶׁהוּא רוֹאֶה אֶת הַתִּינוֹק בַּפַּעַם הָרִאשׁוֹנָה – מָה הַדִּין?",["רַק הַהוֹרִים מְבָרְכִים, וְהָאַחִים אֵינָם רַשָּׁאִים לְבָרֵךְ","רַשַּׁאי לְבָרֵךְ ״שֶׁהֶחֱיָנוּ״, כִּי הוּא שָׂמֵחַ מְאוֹד","חַיָּב לְבָרֵךְ ״הַטּוֹב וְהַמֵּטִיב״, כְּמוֹ הַהוֹרִים עַל לֵידַת בֵּן","יְבָרֵךְ רַק בַּבְּרִית, כְּשֶׁיִּתְּנוּ לַתִּינוֹק שֵׁם"],1,"גַּם בְּנֵי מִשְׁפָּחָה וִידִידִים קְרוֹבִים, אִם הֵם שְׂמֵחִים מְאוֹד כְּשֶׁרוֹאִים אֶת הַתִּינוֹק לָרִאשׁוֹנָה – רַשָּׁאִים לְבָרֵךְ ״שֶׁהֶחֱיָנוּ״. ״הַטּוֹב וְהַמֵּטִיב״ עַל לֵידַת בֵּן מְבָרְכִים הַהוֹרִים, כִּי זוֹ שִׂמְחָה מְשֻׁתֶּפֶת לָהֶם.","פֶּרֶק י״ז, הֲלָכָה י״ג","תּוֹדָה עַל כָּל טוֹבָה"]]};